local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>하이가든, 심판소</color>",
  ui_story_5043_50430101_2_dialog_content = "심판관님, 절대 그런 일은 없었습니다!",
  ui_story_5043_50430101_3_dialog_content = "빛의 신께 맹세코 그녀에 대한 제 「사랑」은 진짜입니다! 절대 속인 적 없습니다!",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5043_50430101_5_dialog_content = "정숙하세요. 원고의 발언을 끊지 마세요.",
  ui_story_5043_50430101_6_dialog_content = "레인 심판관, 계속하세요.",
  ui_story_5043_50430101_7_dialog_content = "피고가 약혼자로서의 의무를 다하지 않았다는 것이 원고 측 주장이 맞습니까?",
  ui_story_5043_50430101_8_dialog_content = "네!",
  ui_story_5043_50430101_9_dialog_content = "변론을 시작하기 전, 원고는 최종 의견을 진술할 수 있습니다.",
  ui_story_5043_50430101_10_dialog_content = "지난달 관월제는 저희 약혼 7개월 기념일이었어요.",
  ui_story_5043_50430101_11_dialog_content = "근데 저 사람은 전혀 신경조차 안 썼다구요!",
  ui_story_5043_50430101_12_dialog_content = "제발... 아무리 기념일이라도 매달 축하해야 하는 건 좀 심하잖아!",
  ui_story_5043_50430101_13_dialog_content = "기념일을 안 챙기는 건 그렇다 쳐요.\n근데 저 사람은 그날 여러 사람한테 전부 다른 관월제 선물을 줬어요!",
  ui_story_5043_50430101_14_dialog_content = "잠깐만, 그건 내가 설명했잖아! 전부 우리 가문이랑 거래하는 사람들이라서 준 거라고...",
  ui_story_5043_50430101_15_dialog_content = "자, 잠시만요... 두 분, 싸우지 마세요...",
  ui_story_5043_50430101_16_dialog_content = "<size=30>티나, 지금 당신은 심판관입니다. 당당하게 말하세요!</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>아, 그렇죠! 그럼... 크흠...</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>정숙, 정숙하세요!</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5043_50430101_20_dialog_content = "(...그래서 난 왜 지금 여기서 알지도 못하는 커플의 사랑싸움 얘길 듣고 있는 거지...)",
  ui_story_5043_50430101_21_dialog_content = "PlayerName, 지겨워 보이네? 얼굴이 좀 굳었어.",
  ui_story_5043_50430101_22_dialog_content = "그, 그런 건 아닌데...\n휴, 그래. 역시 카렌 눈은 못 속인다니까.",
  ui_story_5043_50430101_23_dialog_content = "사실 나도 같은 기분이야.",
  ui_story_5043_50430101_24_dialog_content = "하지만 난 그런 태도를 멋대로 드러낼 수 없어.",
  ui_story_5043_50430101_25_dialog_content = "응, 알아. 사람들은 카렌 네 태도가 곧 저쪽에 계신 성주님의 태도라고 여길 테니까.",
  ui_story_5043_50430101_26_dialog_content = "......",
  ui_story_5043_50430101_27_dialog_content = "성주님은 오히려 아무런 반응도 없으신걸.",
  ui_story_5043_50430101_28_dialog_content = "미안해. 사실 하이가든 회의장에서 네게 용주 대륙에 관한 보고를 부탁하고 싶었거든.",
  ui_story_5043_50430101_29_dialog_content = "하지만 아무래도 성주님은 그럴 틈이 없으실 것 같아.",
  ui_story_5043_50430101_30_dialog_content = "괜찮아. 어차피 나도 요 며칠은 딱히 급한 일도 없으니까.",
  ui_story_5043_50430101_31_dialog_content = "<size=30>오히려 저런 갑갑한 분위기의 회의장에 안 들어가도 돼서 다행이랄까...</size>",
  ui_story_5043_50430101_32_dialog_content = "음? 뭐라고?",
  ui_story_5043_50430101_33_dialog_content = "아무것도 아니야!",
  ui_story_5043_50430101_34_dialog_content = "(그러고 보니까 여기 온 건 <color=#FFB400>그 사건</color> 이후로 처음이네...)",
  ui_story_5043_50430101_35_dialog_content = "(그때도 이리돈 씨는 같은 자리에서 카렌에 대한 심판소의 판결을 읽었었지...)",
  ui_story_5043_50430101_36_dialog_content = "(지금의 카렌은... 이미 그때와는 많이 달라진 것 같네...)",
  ui_story_5043_50430101_37_dialog_content = "PlayerName, 무슨 생각해?",
  ui_story_5043_50430101_38_dialog_content = "어? 아... 음...",
  ui_story_5043_50430101_39_dialog_content = "왠지... 관월제 뒤로 백야성의 분위기가 많이 바뀐 것 같아서 말이야...!",
  ui_story_5043_50430101_40_dialog_content = "맞아. 게다가 매년 이때가 되면 이런 상황이 늘 지속되거든.",
  ui_story_5043_50430101_41_dialog_content = "청춘 남녀들은 저마다 관월제의 여운에 빠져 있어.\n누군가는 새로운 인연을 시작하고, 누군가는 갈라서지.",
  ui_story_5043_50430101_42_dialog_content = "게다가 향락을 좋아하는 귀족들은 어떻게든 관월제의 즐거움을 계속 이어가려고 해.",
  ui_story_5043_50430101_43_dialog_content = "그래서 심판소에서는 매년 이때마다 대량의 치정 소송을 처리하고 있어.",
  ui_story_5043_50430101_44_dialog_content = "성주님도 이 시기엔 더 자주 방청하러 오고 계셔.\n심판소에 돌발 사건이 일어나는 걸 방지하기 위해서 말이야.",
  ui_story_5043_50430101_45_dialog_content = "뭐, 가끔씩 방청석에서 보고만 있는 정도라면 피고석에 서는 것보다는 훨씬 편하겠지만.",
  ui_story_5043_50430101_46_dialog_content = "카렌...",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>탕! 탕! 탕!</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>정숙하세요!</size>",
  ui_story_5043_50430101_49_dialog_content = "어쨌든 이건 결코 용납할 수 없는 악질적인 사건이에요!",
  ui_story_5043_50430101_50_dialog_content = "전 이 자리에서 약혼 취소 소송을 제기하겠어요!",
  ui_story_5043_50430101_51_dialog_content = "후훗, 아름다운 원고 아가씨, 당신의 요구는 이미 충분히 잘 이해했습니다.",
  ui_story_5043_50430101_52_dialog_content = "제가 알기로 두 분의 결혼은 양 가문이 오래전에 결정한 것이고,\n아가씨와 피고 측도 소꿉친구라고 들었습니다.",
  ui_story_5043_50430101_53_dialog_content = "이제야 납득이 가는군요. 소꿉친구가 아니었다면 피고 같은 남자가\n당신처럼 멋진 아가씨와 사랑을 나눌 수 있을 리가 없으니까요.",
  ui_story_5043_50430101_54_dialog_content = "앗...! 맞아요, 슈와브 심판관님. 저흰 확실히 소꿉친구고, 저 남자는 제가 가장 잘 알아요.",
  ui_story_5043_50430101_55_dialog_content = "정말 부러움을 참을 수 없는 사이네요. 저마저도 피고 측에 질투심을 느끼기 시작했어요.",
  ui_story_5043_50430101_56_dialog_content = "(뭐야?! 저 심판관... 되게 끈적거리네!)",
  ui_story_5043_50430101_57_dialog_content = "시, 심판관님...?",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5043_50430101_59_dialog_content = "슈와브 심판관, 직분에 걸맞게 행동하세요.",
  ui_story_5043_50430101_60_dialog_content = "하지만 피고 측이 정말로 어떤 사람인지는 저나 대심판관님도 모릅니다.",
  ui_story_5043_50430101_61_dialog_content = "아가씨는 분명히 오랜 시간을 피고와 교제해 오면서 판단한 끝에,\n심사숙고해서 이번 소송을 제기하셨겠죠.",
  ui_story_5043_50430101_62_dialog_content = "네...?",
  ui_story_5043_50430101_63_dialog_content = "(훗, 정말 쉽게도 걸려드는군.)",
  ui_story_5043_50430101_64_dialog_content = "저, 전...",
  ui_story_5043_50430101_65_dialog_content = "피고 측, 이리돈 대심판관님께서 판결을 내리시기 전에 마지막으로 진술할 내용이 있습니까?",
  ui_story_5043_50430101_66_dialog_content = "<size=45>달링, 난 어렸을 때부터 지금까지 줄곧 너만을 사랑해 왔어!</size>",
  ui_story_5043_50430101_67_dialog_content = "아... 다, 당신...! 이런 데서 갑자기 그런 말을 하면 어떡해요...",
  ui_story_5043_50430101_68_dialog_content = "자~ 그럼 이제...",
  ui_story_5043_50430101_69_dialog_content = "<size=45>잠깐만요!</size>",
  ui_story_5043_50430101_70_dialog_content = "죄송해요. 방금 저 사람과의 문제를 다시 생각해 봤는데요...",
  ui_story_5043_50430101_71_dialog_content = "소송을 <color=#FFB400>취하</color>하고 싶어요.",
  ui_story_5043_50430101_72_dialog_content = "(이렇게 쉽게 취하한다고?!)",
  ui_story_5043_50430101_73_dialog_content = "정말 미안해. 내가 깊게 생각하지 못했어. 우리 사이엔 다른 오해도 없는데...",
  ui_story_5043_50430101_74_dialog_content = "아니야, 내가 너무 소극적이었어. 내가 잘못한 거야.",
  ui_story_5043_50430101_75_dialog_content = "각하합니다. 심판소는 엄숙한 장소입니다.\n소송 제기와 취하 모두 절차에 따라 진행되어야 합니다.",
  ui_story_5043_50430101_76_dialog_content = "다만, 취하보다 더 신속하게 해결할 수 있는 방법도 있습니다.",
  ui_story_5043_50430101_77_dialog_content = "주문. 피고에게──",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5043_50430101_79_dialog_content = "무죄를 선고한다.",
  ui_story_5043_50430101_80_dialog_content = "달링~",
  ui_story_5043_50430101_81_dialog_content = "자기야, 가까운 살롱에 애프터눈 티 마시러 가자...",
  ui_story_5043_50430101_82_dialog_content = "...이상으로 본건의 심리를 마치고 폐정하겠습니다.",
  ui_story_5043_50430101_83_dialog_content = "슈와브 님! 잠시만요~",
  ui_story_5043_50430101_84_dialog_content = "슈와브 님, 무사히 재판을 마쳐서 다행이에요!\n축하드려요! 이건 기념으로 준비한 꽃다발이에요!",
  ui_story_5043_50430101_85_dialog_content = "그, 그리고 화이트초콜릿도 준비했어요... 부디 받아주세요...",
  ui_story_5043_50430101_86_dialog_content = "(쳇...)",
  ui_story_5043_50430101_87_dialog_content = "아름다운 백합꽃 여러분~ 서두르지 말고 한 명씩 천천히 오세요~",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>하이가든, 대심판관의 사무실</color>",
  ui_story_5043_50430101_89_dialog_content = "「규칙」의 의미는 혼란이 어디에 있는지 알아볼 수 있도록 하는 것에 있다.",
  ui_story_5043_50430101_90_dialog_content = "심판소에 저런 혼란스러운 치정 소송 사건이 제기된 지 얼마나 되었지?",
  ui_story_5043_50430101_91_dialog_content = "최근 한 달 사이에 상대적으로 빈번하게 발생하고 있습니다.",
  ui_story_5043_50430101_92_dialog_content = "그렇군. 역시 젊다는 건 좋은 것이지.",
  ui_story_5043_50430101_93_dialog_content = "허나 심판소는 엄숙하고 신성한 곳이다.",
  ui_story_5043_50430101_94_dialog_content = "...이런 유형의 소송은 심리하지 말라는 말씀이신가요?",
  ui_story_5043_50430101_95_dialog_content = "아니, 아직 그러기엔 이르겠지.",
  ui_story_5043_50430101_96_dialog_content = "그렇게 해서는 백성들의 남은 불만이 심판소로 향하게 될 뿐이다.",
  ui_story_5043_50430101_97_dialog_content = "그렇다면 성주님께서 지시를 내려 주시지요.",
  ui_story_5043_50430101_98_dialog_content = "임시 지부를 개설해서, 이러한 치정 관련 소송을 전담하도록 하라.",
  ui_story_5043_50430101_99_dialog_content = "동일하게 백야성 하이가든에 설치하되, 지금의 심판소와는 거리를 두어야 한다.",
  ui_story_5043_50430101_100_dialog_content = "인선이라면 젊은이 몇 명을 뽑아 경험을 쌓게 하는 것이 좋겠군.",
  ui_story_5043_50430101_101_dialog_content = "그렇다면 임시 지부에도 임시 대심판관이 필요하겠네요.",
  ui_story_5043_50430101_102_dialog_content = "염두에 두신 인선이 있으신가요?",
  ui_story_5043_50430101_103_dialog_content = "음, 확실히 아까부터 한 사람이 떠오르긴 했지...",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>하이가든, 심판소</color>",
  ui_story_5043_50430101_105_dialog_content = "성주님이 이리돈 대심판관과 중요한 대화를 나누고 계시는 것 같아.",
  ui_story_5043_50430101_106_dialog_content = "오늘 회의는 아마 취소될 거야. 내 기억에 성주님이 시간을 낼 수 있는 다음 일정은...",
  ui_story_5043_50430101_107_dialog_content = "미안해, PlayerName. 또 며칠 기다려 줘야 할 것 같아.",
  ui_story_5043_50430101_108_dialog_content = "이제 너도 곧 알게 될 거야.\n저분은 항상 약속을 어기고 남의 의견을 무시하는 걸 좋아하는 사람이라는 걸.",
  ui_story_5043_50430101_109_dialog_content = "그, 그렇게 말할 것까진 없어... 그리고 우리도 덕분에 간만에 푹 쉴 수 있잖아. 안 그래?",
  ui_story_5043_50430101_110_dialog_content = "심판관들이 자료 정리하는 걸 보는 것도 나름대로 시간 잘 가는 일이고 말이야.",
  ui_story_5043_50430101_111_dialog_content = "소장, 증거물, 변호인 의견서... 좋습니다, 다 갖추어져 있군요.",
  ui_story_5043_50430101_112_dialog_content = "정리는 이걸로 거의 다 끝난 것 같습니다. 티나, 그쪽은 어떻습니까?",
  ui_story_5043_50430101_113_dialog_content = "아... 네...?",
  ui_story_5043_50430101_114_dialog_content = "어머... 레인 씨, 미안해요. 아까 심리가 세 시간이나 걸려서, 이제 더는... 하아암~",
  ui_story_5043_50430101_115_dialog_content = "정말 곤란하군요. 그렇다면...",
  ui_story_5043_50430101_116_dialog_content = "하루종일 고생 많았습니다! 자, 정신을 풀어주는 차라도 마시고 잠시 쉬시죠.",
  ui_story_5043_50430101_117_dialog_content = "어머... 정말 고마워요. 홀짝...",
  ui_story_5043_50430101_118_dialog_content = "으앗?!",
  ui_story_5043_50430101_119_dialog_content = "왜, 왜 핫초코인 거죠?!",
  ui_story_5043_50430101_120_dialog_content = "후후, 이제 잠이 좀 깼습니까?\n아무리 「기면증」이라곤 해도 잠은 일을 끝낸 뒤에 자세요.",
  ui_story_5043_50430101_121_dialog_content = "그런데 당신, 왠지 요 며칠간은 전보다 더 쉽게 졸려 하게 된 것 같은데요.",
  ui_story_5043_50430101_122_dialog_content = "그런가요...? 하지만 전 매일 규칙적으로 네 시간만 깨어 있는걸요.",
  ui_story_5043_50430101_123_dialog_content = "적어도 오늘은 아닌 것 같습니다만. 어제도 퇴근 전부터 하품을 했었고 말이죠.",
  ui_story_5043_50430101_124_dialog_content = "밤에 잠이 부족하기라도 한 겁니까? 설마 당신마저 불면증이 있는 건 아니겠죠?",
  ui_story_5043_50430101_125_dialog_content = "노, 농담은 하지 말아주세요. 그럴 리가 없잖아요...",
  ui_story_5043_50430101_126_dialog_content = "아무튼 제 쪽 자료도 다 정리했어요. 그럼 전 퇴근할게요.",
  ui_story_5043_50430101_127_dialog_content = "다들 내일 봬요!",
  ui_story_5043_50430101_128_dialog_content = "음, 저도 슬슬 가도 되겠군요.",
  ui_story_5043_50430101_129_dialog_content = "방청석에 계신 카렌 전하와 파트너분, 그럼 먼저 실례하겠습니다.",
  ui_story_5043_50430101_130_dialog_content = "응, 다음에 봐!",
  ui_story_5043_50430101_131_dialog_content = "(졸지에 카렌의 「파트너」가 된 건가...)",
  ui_story_5043_50430101_132_dialog_content = "오오~ 참으로 오랜만이로군. 공주 전하의 「파트너」.",
  ui_story_5043_50430101_133_dialog_content = "이 목소리는...",
  ui_story_5043_50430101_134_dialog_content = "마티외! 뢰베도 있었구나!",
  ui_story_5043_50430101_135_dialog_content = "마티외 경, 여전히 입만 바쁘고 몸은 한가한 모양이군.",
  ui_story_5043_50430101_136_dialog_content = "그리 화내지 마시죠, 전하. 게다가 저도 지금 놀러 온 게 아닙니다만.",
  ui_story_5043_50430101_137_dialog_content = "「재미있는 일」이 하나 있는데, 관심 없으십니까?",
  ui_story_5043_50430101_138_dialog_content = "「재미있는 일」?",
  ui_story_5043_50430101_139_dialog_content = "그렇습니다. 제가 방금 전에 얻은 정보입니다.\n평범한 서민이라면 내일은 돼야 알 수 있는 것이란 말이죠.",
  ui_story_5043_50430101_140_dialog_content = "말해봐.",
  ui_story_5043_50430101_141_dialog_content = "실은 최근 기묘한 사건이 심판소에 접수되었습니다. 아직 담당은 정해지지 않았습니다만...",
  ui_story_5043_50430101_142_dialog_content = "아마 틀림없이 제가 담당하겠죠~",
  ui_story_5043_50430101_143_dialog_content = "대심판관님께 아주 오랫동안 부탁드려서 겨우 허락받았으면서.",
  ui_story_5043_50430101_144_dialog_content = "야! 끼어들지 마!",
  ui_story_5043_50430101_145_dialog_content = "아무튼 그 사건은 최근 관월제의 풍조와도 관계가 있지요...",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>하이가든, 주거 구역</color>",
  ui_story_5043_50430101_147_dialog_content = "흥흥~ 흥...흥~♪",
  ui_story_5043_50430101_148_dialog_content = "(집에 도착하면 제일 먼저 우체통에 편지가 왔는지, 문 앞에 소포가 왔는지 봐야겠죠~)",
  ui_story_5043_50430101_149_dialog_content = "아...",
  ui_story_5043_50430101_150_dialog_content = "역시 안 왔군요...",
  ui_story_5043_50430101_151_dialog_content = "(지난달에 <color=#FFB400>그</color>가 선물로 준 나뭇잎과 나무열매, 아직도 소중히 간직하고 있는데...)",
  ui_story_5043_50430101_152_dialog_content = "(답례를 해야 할 시기가 됐는데도 <color=#FFB400>그</color>는 새 주소를 가르쳐 주지 않네요...)",
  ui_story_5043_50430101_153_dialog_content = "(그러고 보니 최근 한 달 동안 <color=#FFB400>그</color>의 답장을 받지 못했어요.)",
  ui_story_5043_50430101_154_dialog_content = "(걱정이네요... 언제쯤 제가 준비한 쿠키를 줄 수 있을지 모르겠네요...)",
  ui_story_5043_50430101_155_dialog_content = "(역시... 제가 더 적극적으로 나서야 하는 걸까요?)",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5043_50430201_2_dialog_content = "대략적인 상황은 지금 이야기한 대로입니다.",
  ui_story_5043_50430201_3_dialog_content = "성주님께서는 최근 증가하고 있는 치정 관련 소송을 전담하는 임시 지부를\n하이가든에 설치할 것을 명하셨습니다.",
  ui_story_5043_50430201_4_dialog_content = "지부의 호칭은 「<color=#FFB400>심판소 연애 지부</color>」로 하겠습니다.",
  ui_story_5043_50430201_5_dialog_content = "알겠습니다. 그럼 연애 지부에서도 제 직무를 충실히 수행하겠습니다.",
  ui_story_5043_50430201_6_dialog_content = "혹시 한 가지만 여쭤봐도 되겠습니까?\n연애 지부의 대심판관도 정해졌습니까? 아니면 대심판관님께서 겸임하시는 겁니까?",
  ui_story_5043_50430201_7_dialog_content = "아니요, 전 아니에요. 성주님께서 직접 <color=#FFB400>슈와브</color> 심판관을 지명하셨어요.",
  ui_story_5043_50430201_8_dialog_content = "비록 이해는 잘 되지 않습니다만, 어제 성주님께서는 슈와브를 보고\n깊은 인상을 받으신 것 같더군요...",
  ui_story_5043_50430201_9_dialog_content = "아마 그런 방식이 치정 소송에 유연하게 대응할 수 있어서일지도 모르죠.",
  ui_story_5043_50430201_10_dialog_content = "그렇군요. 확실히 어제 그 혼란스러운 재판을 수습한 방식은 저도 감탄했었습니다.",
  ui_story_5043_50430201_11_dialog_content = "그 사람은 자기 매력을 활용하는 방법을 잘 알고 있으니까요...",
  ui_story_5043_50430201_12_dialog_content = "당신도 실망할 필요는 없어요, 레인.",
  ui_story_5043_50430201_13_dialog_content = "비록 정식으로 심판관이 된 지는 얼마 안 됐지만,\n성주님께서는 당신들의 활약을 기대하고 계셔요.",
  ui_story_5043_50430201_14_dialog_content = "연애 지부에 다녀오고 나면, 당신들의 승진에도 긍정적인 성과가 될 거예요.",
  ui_story_5043_50430201_15_dialog_content = "감사합니다, 대심판관님.",
  ui_story_5043_50430201_16_dialog_content = "그리고 한 가지 더 맡길 일이 있어요.",
  ui_story_5043_50430201_17_dialog_content = "지금 연애 지부에 들어온 가장 성가신 소송이라고 할 수 있을 것 같군요.",
  ui_story_5043_50430201_18_dialog_content = "어쩌면 이미 들었을지도 모르겠네요. 「<color=#FFB400>목 없는 조각상 사건</color>」 말이에요.",
  ui_story_5043_50430201_19_dialog_content = "네? 벌써 첫 재판을 준비할 수 있게 된 겁니까?",
  ui_story_5043_50430201_20_dialog_content = "당신이 그렇게 말하니까 안심이 되네요.\n이미 대여섯 명 정도가 이 사건을 맡는 걸 거절했거든요.",
  ui_story_5043_50430201_21_dialog_content = "왜 거절한 겁니까?",
  ui_story_5043_50430201_22_dialog_content = "사건 자체가 이상하다는 것도 이유겠지만,\n대부분 연인과 살롱에 가야 한다는 등의 이유 때문이었죠.",
  ui_story_5043_50430201_23_dialog_content = "아, 이해했습니다...",
  ui_story_5043_50430201_24_dialog_content = "(휴, 역시 귀족들은 늘 한결같다니까...)",
  ui_story_5043_50430201_25_dialog_content = "「목 없는 조각상 사건」의 원고는 <color=#FFB400>바이런</color>이라는 미드가든의 한 귀족입니다.",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>4일 전</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>딩동, 딩동── 딩동──</color>",
  ui_story_5043_50430201_28_dialog_content = "나가요! 그만 누르세요!",
  ui_story_5043_50430201_29_dialog_content = "당신이 초인종을 누른 사람인가요?",
  ui_story_5043_50430201_30_dialog_content = "그래. 난 내 이웃을 고소할 거야!",
  ui_story_5043_50430201_31_dialog_content = "그놈이 심판소 앞에 있는 <color=#FFB400>갈라테아</color>를 부쉈어! 내 눈으로 똑똑히 봤어!",
  ui_story_5043_50430201_32_dialog_content = "잠깐만요... 정의를 상징하는 심판소 조각상에 언제 「갈라테아」라는 이름이 붙었죠?",
  ui_story_5043_50430201_33_dialog_content = "확실히 저건 며칠 전에 부서지긴 했지만, 저흰 오랫동안 보수를 안 해서 그런 줄 알았는데...",
  ui_story_5043_50430201_34_dialog_content = "아가씨, 말조심해! 「<color=#FFB400>저거</color>」라니! 갈라테아라는 이름은 내가 지어 준 거라고.",
  ui_story_5043_50430201_35_dialog_content = "아, 알겠어요...그럼 소장을 제출해 주시겠어요?",
  ui_story_5043_50430201_36_dialog_content = "어디 보자...",
  ui_story_5043_50430201_37_dialog_content = "어라? 바이런 씨, 이웃에 대한 고발 내용을... 잘못 쓰신 것 같은데요?",
  ui_story_5043_50430201_38_dialog_content = "조각상을 부쉈다고 하셨는데, 죄명은 왜... 「<color=#FFB400>연애 방해</color>」인 거죠?!",
  ui_story_5043_50430201_39_dialog_content = "전혀 틀리지 않았어. 왜냐면...",
  ui_story_5043_50430201_40_dialog_content = "갈라테아는 내 <color=#FFB400>애인</color>이니까!",
  ui_story_5043_50430201_41_dialog_content = "그러니까 조각상과 사랑에 빠져서... 조각상을 파괴한 사람을 고소하겠다는 겁니까?",
  ui_story_5043_50430201_42_dialog_content = "네. 조각상은 공공미술이고, 우린 누군가 그걸 사랑하지 못하게 할 권리는 없어요.",
  ui_story_5043_50430201_42X1_dialog_content = "따라서 이 건은 엄밀히 말하면 연애 지부에 배당되어야 할 사건이에요.",
  ui_story_5043_50430201_43_dialog_content = "그리고 제가 이미 사람을 보내 피고 측을 조사하도록 했지만, 유감스럽게도...",
  ui_story_5043_50430201_44_dialog_content = "소장 내용에 허점이 많아, 피고를 용의자로 특정하는 건 적절하지 않은 상황이에요.",
  ui_story_5043_50430201_45_dialog_content = "심판소는 줄곧 「조사·심리 일관체제」를 취해 왔어요.\n그러니 개정 전까지 되도록 많은 정보를 수집해야 해요.",
  ui_story_5043_50430201_46_dialog_content = "아니면 또 휴정을 하고, 다시 개정할 때까지 기다려야 하니까요.\n하지만 연애 지부는 이 기간에 한해 임시로 설치한 지부라서, 그럴 시간이 없어요.",
  ui_story_5043_50430201_47_dialog_content = "알겠습니다. 연애 지부의 운영 기간 내에 사건을 해결해 보겠습니다.",
  ui_story_5043_50430201_48_dialog_content = "그럼 잘 부탁할게요. 그리고... 당신과 함께 소송을 맡을 동료가 두 명 있어요.",
  ui_story_5043_50430201_49_dialog_content = "한 명은 줄곧 당신의 파트너였던 티나예요. 오늘 아침에 참여 의사를 확인했어요.",
  ui_story_5043_50430201_50_dialog_content = "사건 자료 정리를 맡겼는데, 지금쯤 아마 낮잠을 자고 있겠죠.",
  ui_story_5043_50430201_51_dialog_content = "다른 한 명은... 조금 골치가 아프지만,\n그래도 당신들의 <color=#FFB400>선배</color>인 이상, 뭔가 배울 점이 있을 거예요.",
  ui_story_5043_50430201_52_dialog_content = "그럼 즉시 훼손된 조각상 쪽으로 가서 그와 합류하세요.",
  ui_story_5043_50430201_53_dialog_content = "그리고 조사를 마치면 티나와 정보를 검토해보도록 해요.",
  ui_story_5043_50430201_54_dialog_content = "알겠습니다. 지금 바로 가겠습니다.",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>하이가든, 조각상 앞</color>",
  ui_story_5043_50430201_56_dialog_content = "(대심판관님이 말씀하신 그 선배는 대체 누구일까...)",
  ui_story_5043_50430201_57_dialog_content = "이런 이런, 요즘 심판소는 이제 출신도 안 가리고 서민 신입까지 채용하게 된 건가?",
  ui_story_5043_50430201_58_dialog_content = "(역시나...)",
  ui_story_5043_50430201_59_dialog_content = "확실히 마티외 경보다는 심판관다운 느낌이 드는걸.",
  ui_story_5043_50430201_60_dialog_content = "평안하십니까. 선창의 기사 레인, 카렌 호위대장님께 인사드립니다!",
  ui_story_5043_50430201_61_dialog_content = "그렇게 격식차릴 거 없어.\n이쪽은 PlayerName, 마티외 경의 권유로 우리도 협력하기로 했어.",
  ui_story_5043_50430201_62_dialog_content = "당신이 바로 그 전설의 아이테르이십니까? 소문보다 훨씬 친근해 보이시는군요!",
  ui_story_5043_50430201_63_dialog_content = "그, 그럴 것까지야... 잘 부탁할게.",
  ui_story_5043_50430201_64_dialog_content = "<size=32>대체 무슨 소문이 난 거냐고...</size>",
  ui_story_5043_50430201_65_dialog_content = "빛의 신의 은총에 감사해라, 서민 신입.\n우리가 있는 한 네 업무는 분명히 순조롭게 처리될 거다.",
  ui_story_5043_50430201_66_dialog_content = "발목이나 안 잡으면 다행이지.",
  ui_story_5043_50430201_67_dialog_content = "흐음? 신입, 별로 안 기쁜 표정인데?",
  ui_story_5043_50430201_68_dialog_content = "이건 심판소 역사상 가장 기괴한 소송이라고. 그러니 분발하란 말이다!",
  ui_story_5043_50430201_69_dialog_content = "그것도 그렇네요. 기괴한 조각상, 기괴한 죄명, 기괴한 원고, 기괴한 선배까지.",
  ui_story_5043_50430201_70_dialog_content = "어이, 이 자식! 좀 더 공손한 태도를 보이는 게 좋을 거다.",
  ui_story_5043_50430201_71_dialog_content = "그만하죠. 오늘 전 선배와 말싸움하러 온 게 아니니까요. 조각상은 이미 확인하셨나요?",
  ui_story_5043_50430201_72_dialog_content = "이 저금통 말하는 거냐?",
  ui_story_5043_50430201_73_dialog_content = "아, 미안하군. 목 없이 속이 텅 빈 석고상만 보면 나이티움을 던져 넣고 싶어서 말이지.",
  ui_story_5043_50430201_74_dialog_content = "정말... 좀 진지하게 임해주실 순 없는 겁니까...",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>바스락...</color>",
  ui_story_5043_50430201_76_dialog_content = "무슨 소리지?",
  ui_story_5043_50430201_77_dialog_content = "그르르... 크오오!",
  ui_story_5043_50430201_78_dialog_content = "뭐야?! 하이가든의 법도는 어디로 간 거냐! 이 더러운 놈들이 여기까지 굴러들어 왔다고?!",
  ui_story_5043_50430201_79_dialog_content = "말도 안 돼...! 백야성은 밤낮으로 경비병이 지키고 있어.\n암귀가 숨어들어올 수 있을 리가...",
  ui_story_5043_50430201_80_dialog_content = "경비병!",
  ui_story_5043_50430201_81_dialog_content = "예!",
  ui_story_5043_50430201_82_dialog_content = "최근 통행증 기록을 전부 확인해라!\n나이트워치 쪽에도 연락해서 최근의 일지를 취합해 보고하도록!",
  ui_story_5043_50430201_83_dialog_content = "그리고 이 암귀들은... PlayerName, 너희한테 맡겨도 괜찮을까?",
  ui_story_5043_50430201_84_dialog_content = "응, 걱정 말고 얼른 가 봐!",
  ui_story_5043_50430201_85_dialog_content = "그럼 이 암귀들에게 심판을 내리도록 하죠.",
  ui_story_5043_50430202_1_dialog_content = "끝났네! 다들 다친 데는 없어?",
  ui_story_5043_50430202_2_dialog_content = "전혀. 좀 구역질이 나긴 한다만.",
  ui_story_5043_50430202_3_dialog_content = "하루 업무가 이제 막 시작됐는데, 또 가서 샤워를 해야 한다니.",
  ui_story_5043_50430202_4_dialog_content = "어이, 서민 신입, 괜찮냐?",
  ui_story_5043_50430202_5_dialog_content = "신경 써주셔서 감사합니다만, 전 청결하지 않으면 안 되는\n어느 귀족님들만큼 까탈스럽진 않아서 괜찮습니다.",
  ui_story_5043_50430202_6_dialog_content = "그거 정말 미안하게 됐어~\n근데 그렇게 따지자면 뢰베야말로 가장 결벽증이 심한 녀석인데?",
  ui_story_5043_50430202_7_dialog_content = "온몸을 옷으로 덮고 있잖아. 공기조차 더럽다는 거지.",
  ui_story_5043_50430202_8_dialog_content = "이 조각상이 깨졌으면 다들 해임됐을 거야.",
  ui_story_5043_50430202_9_dialog_content = "어이! 무시하지 마!",
  ui_story_5043_50430202_10_dialog_content = "됐어, 이미 충분히 봤으니까 빨리 수거하자.",
  ui_story_5043_50430202_11_dialog_content = "중요한 <color=#FFB400>물증</color>을 여기 방치할 순 없어.",
  ui_story_5043_50430202_12_dialog_content = "원고에게 있어선 이게 곧 「<color=#FFB400>피해자</color>」입니다.",
  ui_story_5043_50430202_13_dialog_content = "제가 좀 더 자세히 살펴보도록 하죠...",
  ui_story_5043_50430202_14_dialog_content = "음... 파괴된 단면의 색상이 조각상의 외부보다 선명한 점으로 본다면,\n노화에 의한 자연적 손상은 아닐 겁니다.",
  ui_story_5043_50430202_15_dialog_content = "균열의 방향에서 봤을 때 큰 외력에 의해 파괴된 게 확실합니다.",
  ui_story_5043_50430202_16_dialog_content = "PlayerName 씨는 어떻게 생각하십니까?",
  ui_story_5043_50430202_17_dialog_content = "보다 보니까 마침 궁금한 게 생겼어.",
  ui_story_5043_50430202_18_option_content = "왜 머리만 사라진 거지?",
  ui_story_5043_50430202_19_dialog_content = "이 조각상, 그냥 대충 부순 건 아닌 것 같아. 단면도 깔끔하고...",
  ui_story_5043_50430202_20_dialog_content = "게다가 목부터 아래쪽은 아무 손상도 없어. 사라진 건 머리뿐이야.",
  ui_story_5043_50430202_21_option_content = "왜 부서진 조각이 없는 거지?",
  ui_story_5043_50430202_22_dialog_content = "조각상 주위가 너무 깨끗하잖아. 부수면서 조각이 떨어졌을 텐데 말이야.",
  ui_story_5043_50430202_23_dialog_content = "으음... 그건 아마 물증 채취를 담당하는 사람들이 청소를 해서 그럴 겁니다.",
  ui_story_5043_50430202_24_dialog_content = "그, 그렇겠네! 그럼... 이상한 점은 역시 사라진 머리겠구나.",
  ui_story_5043_50430202_25_dialog_content = "말씀하신 대로입니다. 아무래도 조각상의 머리는 누군가 <color=#FFB400>훔친</color> 것처럼 보입니다...",
  ui_story_5043_50430202_26_dialog_content = "어이, 너희들 말이야. 아까부터 <color=#FFB400>저거</color> 못 보고 있었냐?",
  ui_story_5043_50430202_27_dialog_content = "저쪽 창문 밖, 백야성의 하늘에 갑자기...",
  ui_story_5043_50430202_28_dialog_content = "<color=#FFB400>달</color>이 떴단 말이다.",
  ui_story_5043_50430202_29_dialog_content = "지, 진짜네!",
  ui_story_5043_50430202_30_dialog_content = "기묘한 일들이 점점 더 많아지는군요. 대체 어떻게 된 걸까요?",
  ui_story_5043_50430202_31_dialog_content = "재미있군. 한번 보러 가 볼까?",
  ui_story_5043_50430202_32_dialog_content = "아니, 잠시만요... 아직 일이 안 끝났잖습니까!",
  ui_story_5043_50430202_33_dialog_content = "어라, 다들 모여 있었네요?",
  ui_story_5043_50430202_34_dialog_content = "왔군요, 티나. 이쪽은 PlayerName 씨, 바로 그 아이테르입니다.",
  ui_story_5043_50430202_35_dialog_content = "후훗, 사실 저흰 지난 달 관월제 때 이미 만난 적 있어요.",
  ui_story_5043_50430202_36_dialog_content = "안녕하세요, PlayerName 씨. 아침부터 만날 수 있다니 정말 기뻐요~",
  ui_story_5043_50430202_37_dialog_content = "안녕, 티나. 지금이 아침은 아니긴 하지만...",
  ui_story_5043_50430202_38_dialog_content = "티나는 자기가 눈을 떴을 때마다 아침 인사를 하는 게 습관입니다.",
  ui_story_5043_50430202_39_dialog_content = "티나 양, 마침 잘 왔어. 그럼 지금까지 조사한 결과를 취합해 보자고.",
  ui_story_5043_50430202_40_dialog_content = "그렇다면... 우리 동시에 말하는 걸로 해요. 지금까지의 조사 성과는...",
  ui_story_5043_50430202_41_dialog_content = "없어요.\n없다.",
  ui_story_5043_50430202_42_dialog_content = "어머, 역시 그랬군요. 여러분도 아무 진전이 없었나 보네요.",
  ui_story_5043_50430202_43_dialog_content = "대심판관님이 주신 소송 자료는 여러 번 자세히 읽어봤어요.",
  ui_story_5043_50430202_44_dialog_content = "하지만 앞뒤 내용이 모순되고, 논리도 혼란스러워서 전 이해할 수 없는 내용이었어요.",
  ui_story_5043_50430202_45_dialog_content = "이쪽은 굳이 말하자면, 불확실한 추측을 한 가지 하고 있었습니다.",
  ui_story_5043_50430202_46_dialog_content = "누군가 조각상의 머리를 가져갔다는 게 저와 PlayerName 씨의 생각입니다.",
  ui_story_5043_50430202_47_dialog_content = "음... 왜 그런 짓을 하는 사람이 있는 거죠?",
  ui_story_5043_50430202_48_dialog_content = "누가 알겠냐! 어쩌면 하급 재판관 녀석이 새 머리를 찾고 있는 건지도 모르지.",
  ui_story_5043_50430202_49_dialog_content = "아무튼 딱히 진전도 없는데, 오늘 업무는 그냥 여기까지 하지 그래?",
  ui_story_5043_50430202_50_dialog_content = "잠시만요! 저기... 사실...",
  ui_story_5043_50430202_51_dialog_content = "여러분을 찾아온 건 개인적인 일을 하나 부탁하고 싶어서예요!",
  ui_story_5043_50430202_52_dialog_content = "음... 「개인적인 일」이 뭐죠? 그다지 개입하고 싶지는 않습니다만...",
  ui_story_5043_50430202_53_dialog_content = "그래요... 그, 그게 사실 요즘 곤란한 문제가 하나 생겼는데,\n다른 사람들 의견을 좀 들어보고 싶거든요...",
  ui_story_5043_50430202_54_dialog_content = "이런 이런, 하필 지금 이 시기에 말이야?",
  ui_story_5043_50430202_55_dialog_content = "뭐, 이해할 수 없는 건 아니야. 감정 문제겠지?",
  ui_story_5043_50430202_56_dialog_content = "갑자기 흥미가 넘치는 모양이네.",
  ui_story_5043_50430202_57_dialog_content = "으... 아무튼, 여러분을 저희 집으로 초대하고 싶어요. 차와 간식을 대접할게요.",
  ui_story_5043_50430202_58_dialog_content = "PlayerName 씨도 같이 오세요.",
  ui_story_5043_50430202_59_dialog_content = "아이테르는 보기만 해도 남의 마음을 읽을 수 있다고 자주 들었어요.\n그러니까 꼭 제 고민을 들어주셨으면 좋겠어요.",
  ui_story_5043_50430202_60_dialog_content = "초대해 준다니 영광이야. 근데 아이테르의 능력은 그 정도까진 아니야...",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>하이가든, 주거 구역, 티나의 저택</color>",
  ui_story_5043_50430301_2_dialog_content = "실은...",
  ui_story_5043_50430301_3_dialog_content = "지난달 관월제 때 <color=#FFB400>그</color>의 선물을 받았어요.",
  ui_story_5043_50430301_4_dialog_content = "비록 전부 흔한 물건이었지만, 전 그 안에서 <color=#FFB400>그</color>의 마음을 느낄 수 있었어요.",
  ui_story_5043_50430301_5_dialog_content = "자, 잠시만요. 제가 잘못 들은 건 아니겠죠? 티나, 지금 사랑에 빠졌다는 겁니까?",
  ui_story_5043_50430301_6_dialog_content = "네? 이런 마음도 「사랑」인가요? 전 왠지 아닌 것 같은데요...",
  ui_story_5043_50430301_7_dialog_content = "듣기엔 꼭 연애할 때 할 것 같은 일인데?",
  ui_story_5043_50430301_8_dialog_content = "PlayerName 씨까지 그렇게 말씀하신다면...",
  ui_story_5043_50430301_9_dialog_content = "음, 일단 넘어가요! 제 이야기를 끝까지 들어보세요.",
  ui_story_5043_50430301_10_dialog_content = "이제 관월제가 끝난 지 벌써 한 달이 됐어요.\n풍습대로라면 이번엔 제가 <color=#FFB400>그</color>에게 답례를 할 차례예요.",
  ui_story_5043_50430301_11_dialog_content = "그래서 전 선물로 줄 쿠키를 구웠어요. 모양도 하나하나 제가 신중하게 고른 것들이구요.",
  ui_story_5043_50430301_12_dialog_content = "이제 남은 건 쿠키를 보내기만 하면 되는데...",
  ui_story_5043_50430301_13_dialog_content = "<color=#FFB400>그</color>는 제가 보낸 연락에 전혀 답장을 하지 않고 있어요.",
  ui_story_5043_50430301_14_dialog_content = "전 <color=#FFB400>그</color>와 몰래 만날 수도 없고, 이젠 편지조차 받을 수 없어요.",
  ui_story_5043_50430301_15_dialog_content = "그래서 요즘 잠을 못 자게 돼서 수면부족인 상태예요... 매일 16시간밖에 못 자거든요...",
  ui_story_5043_50430301_16_dialog_content = "그런 비열한 자가 있다니!",
  ui_story_5043_50430301_17_dialog_content = "마티외보다 악질이네.",
  ui_story_5043_50430301_18_dialog_content = "그런 녀석이라면 그냥 안 좋아하면 되는 거잖아~?",
  ui_story_5043_50430301_19_dialog_content = "하지만 지금은 아직 포기하고 싶지 않아요. 무슨 사정이 있을지도 모르잖아요.",
  ui_story_5043_50430301_20_dialog_content = "<color=#FFB400>그</color> 모습으로는 어딜 가나 많은 사람들의 주의를 끌 테니까요.",
  ui_story_5043_50430301_21_dialog_content = "정말 어쩔 수가 없군요.",
  ui_story_5043_50430301_22_dialog_content = "으음...?",
  ui_story_5043_50430301_23_dialog_content = "<size=32>PlayerName 씨, 마티외 씨, 뢰베 씨, 혹시 눈치채셨습니까...?</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>티나가 말한 「<color=#FFB400>그 사람</color>」, 뭔가 익숙하지 않습니까?!</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>그러고 보니 그렇네! 「어딜 가나 사람들의 주의를 끌게 되는」 사람...</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>「적극적인 상대의 태도에 건성으로 대할 뿐」일지도 모르지...</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>분명 「성격이 나쁘고, 경박하고, 오만한 나르시시스트」겠지.</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>그걸 네가 할 말은 아니잖아.</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>아무튼... 티나가 말하는 사람은 역시... <color=#FFB400>슈와브</color>겠죠?</size>",
  ui_story_5043_50430301_30_dialog_content = "어라? 뭘 수군거리고 계시는 거죠?",
  ui_story_5043_50430301_31_dialog_content = "크흠... 티나, 우린 이미 상대가 누구인지 알았습니다!",
  ui_story_5043_50430301_32_dialog_content = "네에?! 벌써 알았어요? 아, 아직 인정할 생각은 없었는데...",
  ui_story_5043_50430301_33_dialog_content = "(티나, 확실히 무척 당황한 것 같네...)",
  ui_story_5043_50430301_34_dialog_content = "그를 처음 만난 건 살라르 가문의 장원에서였어요.",
  ui_story_5043_50430301_35_dialog_content = "그때 전 살라르 가문에서 연 무도회에 초대를 받았었죠.",
  ui_story_5043_50430301_36_dialog_content = "전 초대장에 적혀 있던 시간보다 조금 일찍 도착했고,\n화원으로 안내를 받아 거기서 잠시 시간을 보내고 있었어요.",
  ui_story_5043_50430301_37_dialog_content = "하지만 살라르 가문의 화원은 정말 웅장해서,\n얼마 뒤 전 토피어리 미궁에서 길을 잃고 말았어요.",
  ui_story_5043_50430301_38_dialog_content = "그렇게 얼마나 걸었을까, 마침내 전 쉼터에 있는 그와 마주쳤던 거예요.",
  ui_story_5043_50430301_39_dialog_content = "그도 제가 온 걸 보고 매우 놀란 것 같았어요.\n그렇게 우린 아름다운 푸른 하늘 아래에서 오랫동안 서로를 바라봤죠...",
  ui_story_5043_50430301_40_dialog_content = "그때 전 깨달았어요. 그는 무척 상냥하고, 온화하고, 선량하고...\n그 모습은 주변의 화초와도 잘 어울렸어요.",
  ui_story_5043_50430301_41_dialog_content = "그 후 그가 먼저 쉼터를 떠났어요.\n하지만 전 그날 무도회가 끝날 때까지 그 누구에게도 시선을 주지 못했죠.",
  ui_story_5043_50430301_42_dialog_content = "쳇, 거 참 로맨틱한 만남이네.",
  ui_story_5043_50430301_43_dialog_content = "(살라르 가문의 장원이라... 역시 슈와브 살라르가 확실하겠어.)",
  ui_story_5043_50430301_44_dialog_content = "(하지만... 상냥하고, 온화하고, 선량하다고?!)",
  ui_story_5043_50430301_45_dialog_content = "이미 알아챈 이상, 여러분께 작은 부탁이 하나 있어요.",
  ui_story_5043_50430301_46_dialog_content = "부디 여러분이 제 「<color=#FFB400>무우마</color>」 계획을 도와주셨으면 해요!",
  ui_story_5043_50430301_47_dialog_content = "그건 또 무슨 이상한 이름의 계획입니까...",
  ui_story_5043_50430301_48_dialog_content = "「<color=#FFB400>무조건 우연히 마주친다</color> 계획」, 줄여서 「무우마」예요!",
  ui_story_5043_50430301_49_dialog_content = "어차피 도와주지 않아도 포기할 생각은 없는 거겠지?",
  ui_story_5043_50430301_50_dialog_content = "미, 미안해요...",
  ui_story_5043_50430301_51_dialog_content = "좋습니다. 동료로서 도움을 드리도록 하겠습니다.",
  ui_story_5043_50430301_52_dialog_content = "나도 낄래.",
  ui_story_5043_50430301_53_dialog_content = "그억 그억.",
  ui_story_5043_50430301_54_dialog_content = "더러운 놈이 있다아아!",
  ui_story_5043_50430301_55_dialog_content = "어머! 정말이네요! 시종! 누구 없나요?!",
  ui_story_5043_50430301_56_dialog_content = "뭐, 됐어요. 마침 「신의 손」도 한동안 쓰지 않았으니까요.",
  ui_story_5043_50430301_57_dialog_content = "청소는 제가 직접 할게요.",
  ui_story_5043_50430301_58_dialog_content = "지금 너네 집에 암귀가 나왔다니까? 무슨 바퀴벌레 나온 것처럼 침착한 건 뭔데?!",
  ui_story_5043_50430302_1_dialog_content = "정말 상쾌한 싸움이었어요... 하아암~",
  ui_story_5043_50430302_2_dialog_content = "방금 처음 안 건데, 티나 너 왼손잡이였구나?",
  ui_story_5043_50430302_3_dialog_content = "아하하, 맞아요. 「신의 손」의 힘을 계승하기 위해 전 어렸을 때부터 훈련을 받았거든요.",
  ui_story_5043_50430302_4_dialog_content = "근데 싸움이 끝나니까 역시 피곤하네요...",
  ui_story_5043_50430302_5_dialog_content = "지금 잘 거면 이제 우린 돌아가도 되는 겁니까?",
  ui_story_5043_50430302_6_dialog_content = "안 졸려요! 아직 기운이 넘친다구요~",
  ui_story_5043_50430302_7_dialog_content = "그럼 하던 이야기를 계속하죠. 제발 「무우마」 계획 좀 도와주세요!",
  ui_story_5043_50430302_8_dialog_content = "그래서 구체적으로 뭘 하면 되는데?",
  ui_story_5043_50430302_9_dialog_content = "사실... 제가 이런 경험이 거의 없어서... 여러분께 좀 여쭤보고 싶어요...",
  ui_story_5043_50430302_10_dialog_content = "제가 주의해야 할 점이 뭐가 있을까요?",
  ui_story_5043_50430302_11_dialog_content = "음... 사람은 부끄러움을 알아야 용감해진다는 말을 책에서 읽은 적 있습니다.\n자신의 잘못을 인정하는 게 변화의 첫걸음이라는 뜻이죠.",
  ui_story_5043_50430302_12_dialog_content = "상대가 자신을 받아들이게 하고 싶다면... 우선 <color=#FFB400>적극적으로 고백</color>해야 합니다.",
  ui_story_5043_50430302_13_dialog_content = "먼저 상대가 잘 나타나는 곳에서 상대를 기다리세요.",
  ui_story_5043_50430302_14_dialog_content = "그리고 상대가 모습을 보이면, 즉시 행동을 시작해서\n상대에게 생각할 틈을 주지 말아야 합니다!",
  ui_story_5043_50430302_15_dialog_content = "아아! 그렇군요...",
  ui_story_5043_50430302_16_dialog_content = "틀렸어, 서민 신입. 적극적인 것만으론 부족해.\n<color=#FFB400>자신을 숨기는 법</color>도 알아야 한다고.",
  ui_story_5043_50430302_17_dialog_content = "자신의 진심을 숨기고, 긴장된 눈빛을 숨기는 거다.",
  ui_story_5043_50430302_18_dialog_content = "적극적으로 나설 용기는 있지만, 상대를 똑바로 볼 수 없을 땐\n부끄러운 척을 하면 오히려 더 좋은 효과를 얻는 법이지.",
  ui_story_5043_50430302_19_dialog_content = "그런가요! 알겠어요...",
  ui_story_5043_50430302_20_dialog_content = "그리고 <color=#FFB400>탐색</color>도 중요해.",
  ui_story_5043_50430302_21_dialog_content = "평범한 대화 주제로 상대의 태도를 확인하는 거지.",
  ui_story_5043_50430302_22_dialog_content = "그렇게 몇 번 주고받다 보면 상대의 본성을 알 수 있어.",
  ui_story_5043_50430302_23_dialog_content = "조금 어려워 보이네요! 그래도 해볼게요...",
  ui_story_5043_50430302_24_dialog_content = "나도 생각해 봤는데, 난 <color=#FFB400>진심을 보여주는</color> 게 중요하다고 생각해.",
  ui_story_5043_50430302_25_dialog_content = "서로 안 시간이 오래되면 서로의 버릇이나 단점도 알게 되잖아.",
  ui_story_5043_50430302_26_dialog_content = "그땐 어쩌면 숨기려고 해도 소용없을지도 몰라.\n그러니까 가장 중요한 건 서로의 진심인 거지.",
  ui_story_5043_50430302_27_dialog_content = "맞아요! 저도 그와 그 정도로 가까워질 수 있었으면 좋겠네요...",
  ui_story_5043_50430302_28_dialog_content = "아무튼 알겠어요. 다들 고마워요!",
  ui_story_5043_50430302_29_dialog_content = "근데... 그 방법들, 전부 실제로 써 보신 적 있으세요?",
  ui_story_5043_50430302_30_dialog_content = "크흠...",
  ui_story_5043_50430302_31_dialog_content = "실전 경험은 없어... 미안...",
  ui_story_5043_50430302_32_dialog_content = "여, 여러분을 탓할 생각은 아니었어요!\n그럼... 역시 직접 시도해 볼 수밖에 없겠네요.",
  ui_story_5043_50430302_33_dialog_content = "근데 대체 어디에 가면 그를 만날 수 있을까요?",
  ui_story_5043_50430302_34_dialog_content = "이 시간대라면 아마 사람들이 모이는 떠들썩한 곳에 있을 겁니다.",
  ui_story_5043_50430302_35_dialog_content = "네? 그런가요...?",
  ui_story_5043_50430302_36_dialog_content = "음~ 떠들썩한 곳이라면 역시 거기겠지.",
  ui_story_5043_50430302_37_dialog_content = "귀족과 서민이 한데 모이는 곳, 「달」 아래다.",
  ui_story_5043_50430302_38_dialog_content = "어, 어째서?!",
  ui_story_5043_50430302_39_dialog_content = "「달」에 관한 정보는 진작에 들어서 알고 있었다.\n이참에 우리도 직접 가서 확인해 보는 게 좋을 것 같군.",
  ui_story_5043_50430302_40_dialog_content = "자기가 가고 싶을 뿐이면서.",
  ui_story_5043_50430302_41_dialog_content = "마티외 씨가 말씀 안 하셨어도 사실 저도 관심이 있었어요. 그럼 지금 바로 가요!",
  ui_story_5043_50430302_42_dialog_content = "아니지, 잠시만요!",
  ui_story_5043_50430302_43_dialog_content = "우리가 처음 만나서 악수했을 때 꼈던 <color=#FFB400>장갑</color>을 껴야겠어요.",
  ui_story_5043_50430302_44_dialog_content = "그리고 선물로 줄 쿠키도 챙길게요!",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>하이가든, 주거 구역</color>",
  ui_story_5043_50430401_2_dialog_content = "그러니까 저 「달」처럼 생긴 열기구가 요즘 하늘에 자주 떠 있었다는 겁니까?",
  ui_story_5043_50430401_3_dialog_content = "전혀 몰랐습니다...",
  ui_story_5043_50430401_4_dialog_content = "제 인식 속에선 태양과 하이가든이야말로 육안으로 볼 수 있는 가장 높은 것이었거든요.",
  ui_story_5043_50430401_5_dialog_content = "눈치채지 못하는 게 정상이지.\n너희 같은 서민들이 아름다운 하늘을 감상하는 맛을 어떻게 알겠어.",
  ui_story_5043_50430401_6_dialog_content = "뭐라고요?!",
  ui_story_5043_50430401_7_dialog_content = "어머, 왜 또 싸우고 그래요~",
  ui_story_5043_50430401_8_dialog_content = "어렸을 때 저희 어머니가 절 데리고 처음으로 천성의 계단에 갔을 때 그러셨어요.\n계단을 오르면 별을 볼 수 있다고 말이에요.",
  ui_story_5043_50430401_9_dialog_content = "계단을 하나 올라갈 때마다 새로운 별이 하나씩 보이고, 다 올라가면 딱 천 개가 되는 거죠.",
  ui_story_5043_50430401_10_dialog_content = "그때 전 너무 기뻐서 단숨에 맨 위까지 올라가 버렸어요.",
  ui_story_5043_50430401_11_dialog_content = "그리고 별을 몇 개 봤는데?",
  ui_story_5043_50430401_12_dialog_content = "하나도 안 보였어요. 그땐 점심이었거든요. 그래서 태양밖에 못 봤어요.",
  ui_story_5043_50430401_13_dialog_content = "밤에 올라갔어야지!",
  ui_story_5043_50430401_14_dialog_content = "하지만 밤에는 잠을 자야 하잖아요...",
  ui_story_5043_50430401_15_dialog_content = "......",
  ui_story_5043_50430401_16_dialog_content = "근데 마티외 씨는 「달」에 대해 어떤 정보를 들으셨나요?",
  ui_story_5043_50430401_17_dialog_content = "흥, 전부 관월제 때문에 들뜬 바보들이 벌이는 짓거리에 대한 얘기였지.",
  ui_story_5043_50430401_18_dialog_content = "녀석들은 백야성에 달 모양의 열기구를 띄워서\n자유연애의 풍조를 선전하려는 모양이야.",
  ui_story_5043_50430401_19_dialog_content = "열기구가 뜨면 이 자들은 그걸 신호에 삼아서 빠르게 한 자리에 모여 살롱을 여는 거지.",
  ui_story_5043_50430401_20_dialog_content = "귀족들은 늘 유행을 좇고 사교와 문화 활동을 즐기지. 그래서 저 일에 열광하고 있는 거다.",
  ui_story_5043_50430401_21_dialog_content = "그랬구나... 관월제 마니아 같은 건가? 왠지 카렌도 그런 말을 했던 것 같네.",
  ui_story_5043_50430401_22_dialog_content = "「관월제」의 이름에 달이 들어가니 달을 상징으로 삼았다는 겁니까?",
  ui_story_5043_50430401_23_dialog_content = "귀족들은 정말 단순하군요.",
  ui_story_5043_50430401_24_dialog_content = "전 오히려 그 마음을 잘 알아요.\n달은 사랑만큼이나 순수하고 소중한 것이니까요.",
  ui_story_5043_50430401_25_dialog_content = "살롱 주최자도 분명히 그런 아름다운 의미를 담아서 달을 상징으로 선택했을 거예요.",
  ui_story_5043_50430401_26_dialog_content = "꽤 훌륭하게 들리는 해석입니다. 역시 사랑에 빠진 소녀라는 겁니까...",
  ui_story_5043_50430401_27_dialog_content = "사랑이 아니라고 말했잖아요... 뭐, 됐으니까 놀리지 마세요!",
  ui_story_5043_50430401_28_dialog_content = "아무튼 열기구의 위치로 보자면 이번 살롱은 미드가든에서 열릴 것 같군.",
  ui_story_5043_50430401_29_dialog_content = "쳇, 도착은 했다만, 또 하염없이 걸어야 하는 건가?\n호위대는 대체 언제쯤 천성의 계단에 마찻길을 만들 생각이지?",
  ui_story_5043_50430401_30_dialog_content = "누구나 너처럼 마차를 탈 돈이 있는 건 아니야.",
  ui_story_5043_50430401_31_dialog_content = "천성의 계단은 미드가든과 하이가든을 연결하는 통로야.",
  ui_story_5043_50430401_32_dialog_content = "마티외, 서민의 세계에 발을 들여놓을 준비는 됐어?",
  ui_story_5043_50430401_33_dialog_content = "시끄러워!",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>미드가든, 초원 광장</color>",
  ui_story_5043_50430401_35_dialog_content = "우와...",
  ui_story_5043_50430401_36_dialog_content = "미드가든에 언제 이런 초원이 생긴 거죠? 정말 예쁘네요.",
  ui_story_5043_50430401_37_dialog_content = "올봄에 이제 막 완성된 인조 잔디 초원이라고 들었습니다.\n루미나틱스로 일상적인 유지보수를 실시하고 있다더군요.",
  ui_story_5043_50430401_38_dialog_content = "어라? 다들 무슨 소리 안 들려...?",
  ui_story_5043_50430401_39_dialog_content = "공연장 중앙의 달 아래에서 음악이 들리는 것 같아.",
  ui_story_5043_50430401_39X1_dialog_content = "아, 입수한 정보에 따르면 살롱에서는 이야기를 나누거나,\n무도회, 찬송가 감상 등을 한다더군.",
  ui_story_5043_50430401_40_dialog_content = "으음~ 아주 표준적인 사교댄스 음악이잖아. 취향은 그런대로 나쁘지 않군.",
  ui_story_5043_50430401_40X1_dialog_content = "여러분, 달의 살롱에는 처음이십니까?",
  ui_story_5043_50430401_40X2_dialog_content = "자, 멀뚱멀뚱 서 있지 말고 다들 들어오시죠.",
  ui_story_5043_50430401_40X3_dialog_content = "어이! 잠깐만, 잡아당기지 마! 구역질 난다고!",
  ui_story_5043_50430401_41_dialog_content = "그랬군요, 달의 살롱 무도회 시간이었군요!",
  ui_story_5043_50430401_42_dialog_content = "그럼 가만히 서 있는 것도 실례잖아요. 우리도 같이 춤을 춰요.\n그러면서 겸사겸사 참가자들을 관찰하는 거죠!",
  ui_story_5043_50430401_43_dialog_content = "하, 하지만 전 당신들의 복잡한 예법이나 댄스 스텝 같은 건 모른단 말입니다!",
  ui_story_5043_50430401_44_dialog_content = "나도 춤은 전혀...",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5043_50430401_46_dialog_content = "그러니까... 왜 내가 이 서민 신입과 춤을 춰야 하냔 말이다! 토할 것 같아!",
  ui_story_5043_50430401_47_dialog_content = "저도 뭐 좋은 줄 아십니까!",
  ui_story_5043_50430401_48_dialog_content = "으악!",
  ui_story_5043_50430401_49_dialog_content = "너 바보냐?! 발 조심하라고... 아악!",
  ui_story_5043_50430401_50_dialog_content = "방금 그건 확실히 고의였겠지!",
  ui_story_5043_50430401_51_dialog_content = "잠시만요! 뭘 하려는 겁니까?!",
  ui_story_5043_50430401_52_dialog_content = "이러지 좀 마세요! 제 머리에서 손 떼시라고요...",
  ui_story_5043_50430401_53_dialog_content = "푸후훕! 저쪽 두 분은 참 떠들썩하네요.",
  ui_story_5043_50430401_54_dialog_content = "PlayerName 씨, 긴장하셨나요?",
  ui_story_5043_50430401_55_dialog_content = "아, 아니, 괜찮아...",
  ui_story_5043_50430401_56_dialog_content = "왼쪽으로 한 발, 발끝을 세우고, 오른쪽으로 물러섰다가, 한 바퀴 돌고...",
  ui_story_5043_50430401_57_dialog_content = "아, 미, 미미미미안! 손이 일부러 닿은 건 아니야!",
  ui_story_5043_50430401_58_dialog_content = "긴장하지 않아도 돼요, PlayerName 씨. 그냥 사교댄스일 뿐인걸요.",
  ui_story_5043_50430401_59_dialog_content = "바로 그 스텝이에요. 그럼 다시 한번 해 볼까요?",
  ui_story_5043_50430401_60_dialog_content = "응... 더 노력해 볼게!",
  ui_story_5043_50430401_61_dialog_content = "후훗, 보세요. 이제 잘하게 됐잖아요.",
  ui_story_5043_50430401_62_dialog_content = "금방 배우시네요!",
  ui_story_5043_50430401_63_dialog_content = "휴~ 음악이 끝났네요. 몸도 충분히 풀어준 것 같아요.",
  ui_story_5043_50430401_64_dialog_content = "전 이제 더는 됐습니다...",
  ui_story_5043_50430401_65_dialog_content = "쳇, 위자료를 청구하지 않는 게 내가 베풀 수 있는 최대의 자비인 줄 알아라.",
  ui_story_5043_50430401_66_dialog_content = "그나저나 뢰베 이 자식은 어디 갔어...?",
  ui_story_5043_50430401_67_dialog_content = "아무래도 나만 귀찮은 일을 피한 모양이네.",
  ui_story_5043_50430401_68_dialog_content = "방금 바깥에서 딱 봐도 살롱 참가자가 아닌 수상한 사람을 봤어.",
  ui_story_5043_50430401_69_dialog_content = "상황을 보러 갔더니 카렌 전하가 계셨어.",
  ui_story_5043_50430401_70_dialog_content = "안내해 줘서 고마워. 음, 당신이 말한 수상한 사람은 사실 내가 보낸 수하였어.",
  ui_story_5043_50430401_71_dialog_content = "앗? 카렌 전하도 오셨군요~",
  ui_story_5043_50430401_72_dialog_content = "카렌! 어땠어? 암귀 조사 결과는?",
  ui_story_5043_50430401_73_dialog_content = "아직 결과는 나오지 않았지만, 가능성의 범위는 좁혀졌어.",
  ui_story_5043_50430401_74_dialog_content = "통행증에는 문제가 없었어.\n그러니까 암귀가 남의 이름으로 백야성에 숨어 들어왔을 가능성은 낮아.",
  ui_story_5043_50430401_75_dialog_content = "야간 경비에도 허점은 없었고, 백야성 상공의 보호막도 문제없었어.",
  ui_story_5043_50430401_76_dialog_content = "하지만 최근 기념일이 많아서, 물자를 운반하는 무역상이나 용병들도\n백야성에 많이 출입하고 있으니까...",
  ui_story_5043_50430401_77_dialog_content = "화물 속에 암귀가 섞여 있는 걸 경비병이 검사하지 못했을 가능성이 있어.",
  ui_story_5043_50430401_78_dialog_content = "어라? 카렌 전하께선 백야성에 들어온 암귀에 대한 조사를 하고 계신 건가요?",
  ui_story_5043_50430401_79_dialog_content = "역시... 그럼 어서 그를 찾아야겠어요...",
  ui_story_5043_50430401_80_dialog_content = "걱정할 필요 없습니다. 분명히 무사할 테니까요.",
  ui_story_5043_50430401_81_dialog_content = "저, 정말인가요...",
  ui_story_5043_50430401_82_dialog_content = "(티나, 뭘 걱정하고 있는 거지? 뭔가 이상한데...)",
  ui_story_5043_50430401_83_dialog_content = "어쨌든 호위대의 조사를 피할 수 있다는 건, 놈들을 이끌고 있는 녀석이\n모종의 <color=#FFB400>변장 기술</color>을 사용해서 인파 속에 섞여 들게 했을 가능성이 있어.",
  ui_story_5043_50430401_84_dialog_content = "하지만 백성들의 불필요한 동요를 막기 위해 전수 조사는 아직 명령하지 않았어.",
  ui_story_5043_50430401_85_dialog_content = "대신 대원들을 사복으로 갈아입히고, 예상 밖의 사태가 일어나지 않도록\n사람들이 많이 모이는 곳을 둘러보게 하고 있어.",
  ui_story_5043_50430401_86_dialog_content = "왠지... 관월제의 후속 대책만 놓고 보면 카렌과 성주님의 생각이 비슷한 것 같네.",
  ui_story_5043_50430401_87_dialog_content = "...그거 칭찬으로는 들리지 않는걸.",
  ui_story_5043_50430401_88_dialog_content = "아하하하... 미안, 아니면 나도 좀 도와줄까?",
  ui_story_5043_50430401_89_dialog_content = "적어도 사람들이 모이는 이런 곳에 암귀가 있으면 안 되니까...",
  ui_story_5043_50430401_90_option_content = "(강제 감응!)",
  ui_story_5043_50430401_91_dialog_content = "고마워, PlayerName.",
  ui_story_5043_50430401_92_dialog_content = "어때? 이상은 없어?",
  ui_story_5043_50430401_93_dialog_content = "음...",
  ui_story_5043_50430401_94_dialog_content = "안 돼. 주변이 너무 떠들썩해서 전혀 효과가 없어...",
  ui_story_5043_50430401_95_dialog_content = "카렌 전하, PlayerName!",
  ui_story_5043_50430401_96_dialog_content = "거기 멀뚱하게 서 있을 때가 아닙니다! 얼른 이리 오세요!",
  ui_story_5043_50430401_97_dialog_content = "음, 이왕 왔으니까 우리도 보러 가자.",
  ui_story_5043_50430401_98_dialog_content = "저 달 열기구, 가까이서 보니까 꽤 훌륭하네.",
  ui_story_5043_50430401_99_dialog_content = "전하께서도 그렇게 생각하시나요?",
  ui_story_5043_50430401_100_dialog_content = "봄의 숨결이 넘치는 잔디밭, 사랑에 빠진 남녀, 어디선가 들려오는 성가대의 노랫소리...",
  ui_story_5043_50430401_101_dialog_content = "평소 가까이서 볼 수 없는 아름다운 달 아래,\n계급을 넘어 마음껏 서로의 생각을 이야기하는 사람들...",
  ui_story_5043_50430401_102_dialog_content = "마치 어떤 신화나 전설 속에나 있을 법한 모습 같아요~",
  ui_story_5043_50430401_103_dialog_content = "훗, 「생각」은 무슨, 저들은 그저 가벼운 마음으로 사랑이니 뭐니 떠들고 있을 뿐이라고.",
  ui_story_5043_50430401_104_dialog_content = "이렇게 많은 서민을 한 번에 보는 건 정말 처음이군.\n다운타운의 냄새가 공기 중에 가득 차 있잖아, 우욱...",
  ui_story_5043_50430401_105_dialog_content = "이제 와서 후회해도 늦었어.",
  ui_story_5043_50430401_106_dialog_content = "그나저나 서민 신입, 넌 뭘 멍하니 있는 거냐?",
  ui_story_5043_50430401_107_dialog_content = "저 달 말인데요... 뭔가 신기하다는 생각이 들어서요.",
  ui_story_5043_50430401_108_dialog_content = "밧줄로 묶은 것도 아닌데 날아가지도 않고 같은 곳에 떠 있습니다...\n설마 루미나틱스로 제어하고 있는 걸까요...?",
  ui_story_5043_50430401_109_dialog_content = "뭐, 됐습니다. 어디까지나 서민의 상식에서 비롯된 걱정일 뿐이니까요.\n저 같은 서민의 의견에 관심 가지실 필요는 없습니다.",
  ui_story_5043_50430401_110_dialog_content = "짐작하신 대로랍니다. 그리고...",
  ui_story_5043_50430401_111_dialog_content = "이 루미나틱스는 안에 든 <color=#FFB400>옛 기념일의 선물</color>을 보호하는 데도 쓰이고 있어요.",
  ui_story_5043_50430401_112_dialog_content = "누구시죠?",
  ui_story_5043_50430401_113_dialog_content = "백야성의 평범한 수녀랍니다. 그냥 수녀님이라고 불러주시면 돼요.",
  ui_story_5043_50430401_114_dialog_content = "최근 달의 살롱은 모두 제가 주최한 거예요.",
  ui_story_5043_50430401_115_dialog_content = "처음 오신 것 같은데, 어떠신가요? 달의 살롱은 마음에 드시나요?",
  ui_story_5043_50430401_116_dialog_content = "저, 전 이제 막 와서 잘 모르겠지만... 뭔가 색다른 느낌이 들긴 하네요...",
  ui_story_5043_50430401_117_dialog_content = "제가 아는 백야성과는 분위기가 많이 달라서요.",
  ui_story_5043_50430401_118_dialog_content = "후훗, 말씀 감사드려요. 부디 빛의 신의 축복이 있기를. 그럼 더는 방해하지 않을게요.",
  ui_story_5043_50430401_119_dialog_content = "테이블에 있는 차와 간식은 자유롭게 드세요. 성가대의 찬송가도 들으시면 좋을 것 같네요.",
  ui_story_5043_50430401_120_dialog_content = "(성가대라니, 설마...)",
  ui_story_5043_50430401_121_dialog_content = "달의 살롱에 왔구나~♪",
  ui_story_5043_50430401_122_dialog_content = "정말 왔네~♪",
  ui_story_5043_50430401_123_dialog_content = "살롱에서 아무것도 못 하고 한가한 모습~♪",
  ui_story_5043_50430401_124_dialog_content = "아직 솔로지? 솔로야~♪",
  ui_story_5043_50430401_125_dialog_content = "보세요. 정말 사랑스러운 아이들이죠?",
  ui_story_5043_50430401_126_dialog_content = "어디가 사랑스러운데요?!",
  ui_story_5043_50430401_127_dialog_content = "찌르면 터질 것처럼 통통한 몸~♪",
  ui_story_5043_50430401_128_dialog_content = "높은 하늘에 살고 있지~♪",
  ui_story_5043_50430401_129_dialog_content = "무엇을 찬양하려는 걸까~♪",
  ui_story_5043_50430401_130_dialog_content = "시시한 귀족과 달의 열기구~♪",
  ui_story_5043_50430401_131_dialog_content = "음, 여명 아카데미 성가대까지 불러왔구나.",
  ui_story_5043_50430401_132_dialog_content = "저 애들 찬송가는 여전하네...",
  ui_story_5043_50430401_133_dialog_content = "남자와 여자가 달 아래에서 즐겁게 이야기해~♪",
  ui_story_5043_50430401_134_dialog_content = "평민과 귀족이 같은 테이블에 둘러앉아 케이크를 먹지~♪",
  ui_story_5043_50430401_135_dialog_content = "존경하는 귀여운 수녀님~♪",
  ui_story_5043_50430401_136_dialog_content = "달의 살롱은 정말 좋아~♪",
  ui_story_5043_50430401_137_dialog_content = "얼핏 들어서는 무슨 내용인지 잘 모르겠지만, 자세히 곱씹어 보면 꽤 좋은 가사군요...",
  ui_story_5043_50430401_138_dialog_content = "어머, 이런 곳에서 성가대를 만나다니, 역시 기도하는 게 좋겠네요.",
  ui_story_5043_50430401_139_dialog_content = "만물은 백야 아래에. 빛의 신이시여, 부디 그와 만날 수 있게 해주세요.",
  ui_story_5043_50430401_140_dialog_content = "그건 빛의 신의 관할 범위가 아니잖아...",
  ui_story_5043_50430401_141_dialog_content = "백야성에서는 모두가 빛의 신을 믿어~♪",
  ui_story_5043_50430401_142_dialog_content = "하지만 귀족과 평민은 자유롭게 결혼할 수 없어~♪",
  ui_story_5043_50430401_143_dialog_content = "존경하는 불쌍한 수녀님~♪",
  ui_story_5043_50430401_144_dialog_content = "어리석은 높은 분들을 화나게 하면 곧 큰 재앙이 올 거예요~♪",
  ui_story_5043_50430401_145_dialog_content = "뭐, 뭐라고?",
  ui_story_5043_50430401_146_dialog_content = "이 일대를 전부 진압하라. 불법 집회 참가자들을 모두 체포하라!",
  ui_story_5043_50430401_147_dialog_content = "주모자를 반드시 잡아야 한다!",
  ui_story_5043_50430401_148_dialog_content = "으아악!",
  ui_story_5043_50430401_149_dialog_content = "하이가든 호위대다! 도망쳐!",
  ui_story_5043_50430401_150_dialog_content = "나, 난 하이가든에 사는 귀족이다! 누가 감히 날...",
  ui_story_5043_50430401_151_dialog_content = "으악?!",
  ui_story_5043_50430401_152_dialog_content = "앗... 내 <color=#FFB400>쿠키</color>!",
  ui_story_5043_50430401_153_dialog_content = "그에게 줄 쿠키를 <color=#FFB400>잃어버렸어요</color>!",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5043_50430401_155_dialog_content = "(그럴 리 없어. 내 호위대가 아니잖아!)",
  ui_story_5043_50430401_156_dialog_content = "누가 감히 내 명령도 없이...",
  ui_story_5043_50430401_157_dialog_content = "호위대장님!",
  ui_story_5043_50430401_158_dialog_content = "저들은 하이가든 호위대 소속 병사들이 아닙니다.",
  ui_story_5043_50430401_159_dialog_content = "하지만 하이가든 귀족이 아니라면 사병을 가지고 있는 경우는 드뭅니다.",
  ui_story_5043_50430401_160_dialog_content = "살롱에 참가한 이 사람들은 분명히 이번 단속을 하이가든의 뜻이라 생각할 겁니다!",
  ui_story_5043_50430401_161_dialog_content = "...무슨 뜻인지 알겠어. 하지만 지금은 혼란을 가라앉히는 게 먼저야!",
  ui_story_5043_50430401_162_dialog_content = "여러분, 당황하지 말고 절 따라오세요!",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50430401_164_dialog_content = "(무슨 소리지?!)",
  ui_story_5043_50430401_165_dialog_content = "PlayerName, 그리고 선창의 기사, 두 사람의 힘이 필요해.",
  ui_story_5043_50430401_166_dialog_content = "주변에 있는 사복 호위병들과 함께 백성들을 체포하는 저 병사들을 제압해 줘!",
  ui_story_5043_50430401_167_dialog_content = "알겠어!",
  ui_story_5043_50430401_168_dialog_content = "분부대로.",
  ui_story_5043_50430501_1_dialog_content = "빨리도 도망치는군요!",
  ui_story_5043_50430501_2_dialog_content = "카렌 전하, 계속 추격할까요?",
  ui_story_5043_50430501_3_dialog_content = "...됐어. 이제 당신이 맡은 일을 하면 돼.",
  ui_story_5043_50430501_4_dialog_content = "정말 유감입니다. 살롱도 엉망이 되었고, 찾으려던 사람도 만나지 못했군요.",
  ui_story_5043_50430501_5_dialog_content = "찾으려던 사람? 누굴 찾고 있었지?",
  ui_story_5043_50430501_6_dialog_content = "제가 아니라 티나가 찾던 중이었습니다.\n슈와브 심판관에게 관월제의 답례 선물을 주고 싶다더군요.",
  ui_story_5043_50430501_7_dialog_content = "아, 그 두 사람이 그런 사이였구나.",
  ui_story_5043_50430501_8_dialog_content = "그것도 관월제의 영향인가.\n일족 간 약혼 약속도 없는 청년들이 자유연애를 결정하다니.",
  ui_story_5043_50430501_9_dialog_content = "다만... 솔직히 말하자면, 그런 경박한 남자의 어디가 좋은 거지?",
  ui_story_5043_50430501_10_dialog_content = "그러게...",
  ui_story_5043_50430501_11_dialog_content = "근데 다들 뢰베 못 봤어?",
  ui_story_5043_50430501_12_dialog_content = "경비병들이 도망간 뒤부터 안 보이던데.",
  ui_story_5043_50430501_13_dialog_content = "내가 저 경비병들의 정체를 알아보라고 보냈어. 너흰 사건 조사를 계속해 줘.",
  ui_story_5043_50430501_14_dialog_content = "사실 조사하지 않아도 어느 정도 예상은 되지만, 그래도 확실하게 해 두고 싶어.",
  ui_story_5043_50430501_15_dialog_content = "무, 문제가 생겼어요!",
  ui_story_5043_50430501_16_dialog_content = "알고 있어요. 준비해 온 쿠키를 잃어버린 거죠?",
  ui_story_5043_50430501_17_dialog_content = "저 남은 음식들 중에 없는지 좀 더 찾아봅시다.",
  ui_story_5043_50430501_18_dialog_content = "아니에요! 쿠키만 없어졌으면 다행이죠!",
  ui_story_5043_50430501_19_dialog_content = "저 광장 입구에 서 있던 조각상이...",
  ui_story_5043_50430501_20_dialog_content = "방금 전 소동으로 <color=#FFB400>부서졌다</color>...",
  ui_story_5043_50430501_21_dialog_content = "뭐?!",
  ui_story_5043_50430501_22_dialog_content = "안 그래도 군중들이 도망칠 때 뭔가 깨지는 듯한 소리가 나긴 했었지.",
  ui_story_5043_50430501_23_dialog_content = "게다가 더 기묘한 건, 이 조각상이 파괴된 방식은 심판소의 그 조각상과 거의 똑같다는 사실이다.",
  ui_story_5043_50430501_24_dialog_content = "마치 「조각상 머리 수집가」에게 「살해」당한 것처럼 말이야.",
  ui_story_5043_50430501_25_dialog_content = "이렇게 된 이상... 역시 임시 대심판관인 그 사람에게 상황을 보고하는 게 좋겠군요.",
  ui_story_5043_50430501_26_dialog_content = "마침 지금 달의 살롱에 없는 걸 보면, 분명히...",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>하이가든, 슈와브의 사무실</color>",
  ui_story_5043_50430501_28_dialog_content = "음... 그렇군요. 알겠습니다.",
  ui_story_5043_50430501_29_dialog_content = "마침 때맞춰 잘 돌아왔습니다.\n조각상 일은 우선 접어둡시다. 원고가 다음 절차를 밟을 때까지 기다리죠.",
  ui_story_5043_50430501_30_dialog_content = "그것보다 이제 곧 새로운 연애 소송이 개정될 겁니다.\n자, 재판을 준비해 주세요. 제 사랑스러운 부하들.",
  ui_story_5043_50430501_31_dialog_content = "이렇게 갑자기?",
  ui_story_5043_50430501_32_dialog_content = "여긴 연애 지부니까요. 루미나틱스로 움직이는 마차처럼 한시도 멈추지 않아요~",
  ui_story_5043_50430501_33_dialog_content = "대심판관 자리에 앉아 본 적 없는 당신은 모르시겠죠. 꼬마 민.들.레 군~",
  ui_story_5043_50430501_34_dialog_content = "꼬, 꼬마 민들레???",
  ui_story_5043_50430501_35_dialog_content = "(...지금 나 부른 거야...? 토할 것 같아!)",
  ui_story_5043_50430501_36_dialog_content = "곧 익숙해질 겁니다, PlayerName 씨...",
  ui_story_5043_50430501_37_dialog_content = "참, 슈와브 대심판관님. 사실 티나가 드릴 말씀이 있다고...",
  ui_story_5043_50430501_38_dialog_content = "어이, 그건 지금 꺼낼 얘기가 아니잖아?",
  ui_story_5043_50430501_39_dialog_content = "(레인 씨도 참... 슈와브 대심판관님한테 보고할 필요는 없는데...)",
  ui_story_5043_50430501_40_dialog_content = "호오? 제 사랑스러운 부하들이 벌써 비밀을 공유할 정도로 친해진 겁니까?",
  ui_story_5043_50430501_41_dialog_content = "아무튼, 공소장과 관련 자료는 여기 있습니다.\n아주 단순한 사건이에요. 그럼 조금 뒤에 연애 지부에서 봅시다.",
  ui_story_5043_50430501_42_dialog_content = "확실히 복잡한 사건은 아닌 것 같네요.\n이것도 아까 그 달의 살롱과 관련이 있는 것 같은데요...",
  ui_story_5043_50430501_43_dialog_content = "...어라?! 잠시만요! 다들 여기 소송 제기 사유 좀 보세요...!",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>심판소 연애 지부</color>",
  ui_story_5043_50430501_45_dialog_content = "성주님은 추진력도 참 대단하다니까. 꽤 대단한 규모로 건물을 지었잖아.",
  ui_story_5043_50430501_46_dialog_content = "맞아. 하지만 하루에 접수하는 소송 건수로 따진다면,\n이 정도 예산을 들인 것도 낭비는 아니야.",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5043_50430501_48_dialog_content = "지금부터 재판을 시작하겠습니다!",
  ui_story_5043_50430501_49_dialog_content = "우선 소송 당사자와 기타 증인의 정보를 확인하겠습니다!",
  ui_story_5043_50430501_50_dialog_content = "원고, 백야성 다운타운 거주, 남성.\n개인정보 보호를 위해 성명은 공개하지 않습니다.",
  ui_story_5043_50430501_51_dialog_content = "피고, 백야성 다운타운 거주, 여성.\n개인정보 보호를 위해 성명은 공개하지 않습니다.",
  ui_story_5043_50430501_52_dialog_content = "(공개를 안 하면 정보를 어떻게 알아?!)",
  ui_story_5043_50430501_53_dialog_content = "본 재판은 저 슈와브 살라르가 대심판관을 맡습니다.",
  ui_story_5043_50430501_54_dialog_content = "심판관으로는 마티외 소이어, 티나 캠벨, 레인...",
  ui_story_5043_50430501_55_dialog_content = "그리고 약간 명으로 구성된 배심원단이 합의체를 구성하여 재판을 진행합니다.",
  ui_story_5043_50430501_56_dialog_content = "(오! 사람이 진지해지니까 꽤 그럴싸하잖아...)",
  ui_story_5043_50430501_57_dialog_content = "양측이 심판소 구성원에 대해 이의가 없다면, 즉시 본건의 심리를 시작할 수 있습니다.",
  ui_story_5043_50430501_58_dialog_content = "기다려라! 왜 우리 배심원들은 「약간 명」 따위로 소개하고 마는 것이냐!",
  ui_story_5043_50430501_59_dialog_content = "좋습니다~ 그럼 본건의 심리 절차를 개시하겠습니다.",
  ui_story_5043_50430501_60_dialog_content = "원고는 이 소를 제기하는 청구취지 및 청구원인을 진술하세요.",
  ui_story_5043_50430501_61_dialog_content = "흑흑... 그게 말이죠...",
  ui_story_5043_50430501_62_dialog_content = "저와 제 약혼녀, 그러니까 피고는...\n오늘 미드가든 초원 광장에서 열린 달의 살롱에 참가했습니다...",
  ui_story_5043_50430501_63_dialog_content = "그, 그런데... 저 사람은...",
  ui_story_5043_50430501_64_dialog_content = "원고, 울지 말고 제대로 말씀해 주세요~",
  ui_story_5043_50430501_65_dialog_content = "전 정말 저 사람을 좋아합니다... 올해로 교제한 지 4년째입니다...\n평소엔 초콜릿을 먹으면서 커피를 마시는 걸 좋아하고...",
  ui_story_5043_50430501_66_dialog_content = "원고, 본 소송과 관련 있는 내용만 진술하세요.",
  ui_story_5043_50430501_67_dialog_content = "죄, 죄송합니다... 역시 전... 뭐 하나 제대로 못 하는 사람입니다...",
  ui_story_5043_50430501_68_dialog_content = "처음에 저흰 달의 살롱에서 즐거운 시간을 보내고 있었습니다...\n그런데 갑자기 저 사람의 안색이 확 바뀌더니... 저와 헤어지겠다고 하는 겁니다!",
  ui_story_5043_50430501_69_dialog_content = "이제 가족들에게 뭐라고 설명해야 할지... 흑흑흑...",
  ui_story_5043_50430501_70_dialog_content = "알겠습니다. 이어서 피고 측 진술하세요.",
  ui_story_5043_50430501_71_dialog_content = "물론 제가 그랬던 이유가 있어요.",
  ui_story_5043_50430501_72_dialog_content = "저 남자, 즉 원고는 저와 데이트하는 중임에도 불구하고...",
  ui_story_5043_50430501_73_dialog_content = "살롱에서 다른 여자한테 선물을 받았어요!",
  ui_story_5043_50430501_74_dialog_content = "(뭐야, 이 소송, 오히려 저 여자가 원고 같은데?)",
  ui_story_5043_50430501_75_dialog_content = "나, 난 그런 적 없어...",
  ui_story_5043_50430501_76_dialog_content = "그럼 설명해 봐. 바구니에 든 <color=#FFB400>쿠키</color>는 대체 뭐였어?",
  ui_story_5043_50430501_77_dialog_content = "(...바구니에 든 쿠키? 설마...)",
  ui_story_5043_50430501_78_dialog_content = "이거예요, 이게 바로 증거예요!",
  ui_story_5043_50430501_79_dialog_content = "이 쿠키는 저 사람 자리에 놓여 있었어요. 안에는 카드까지 들어있었고요.",
  ui_story_5043_50430501_80_dialog_content = "더 끔찍한 건 이 카드에 우리밖에 모르는 서로의 <color=#FFB400>애칭</color>이 쓰여 있었다는 거예요!",
  ui_story_5043_50430501_81_dialog_content = "망했네요...",
  ui_story_5043_50430501_82_dialog_content = "역시 그랬군요. 소장에 쓰인 내용대로 저 커플이 티나의 쿠키를 주웠던 거군요.",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>탕! 탕! 탕!</color>",
  ui_story_5043_50430501_84_dialog_content = "정숙하세요~",
  ui_story_5043_50430501_85_dialog_content = "심판소를 모독하는 백야성 주민은 대심판관인 제가 사형을 선고하겠어요...\n...농담이에요~",
  ui_story_5043_50430501_86_dialog_content = "<size=32>티나. 저거 네가 잃어버린 쿠키 맞지?</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>어머? PlayerName 씨?</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>안 돼요. 재판 중에는 잡담을 하면 안 돼요.</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>그렇구나. 그럼...</size>",
  ui_story_5043_50430501_90_option_content = "(강제 감응!)",
  ui_story_5043_50430501_91_dialog_content = "우와, 대단해요! 이게 바로 아이테르의 그 능력이군요? 저도 드디어 체험하게 됐네요!",
  ui_story_5043_50430501_92_dialog_content = "지금은 그런 얘길 할 때가 아냐... 아무튼 저 쿠키, 네 거 맞지?",
  ui_story_5043_50430501_93_dialog_content = "네, 맞아요! 정말... 제가 덤벙댄 탓에 무고한 연인 사이에 저런 오해가 생겨 버렸네요...",
  ui_story_5043_50430501_94_dialog_content = "PlayerName 씨, 어떻게 하면 좋을까요?",
  ui_story_5043_50430501_95_option_content = "사실대로 말하는 게 좋겠어.",
  ui_story_5043_50430501_96_dialog_content = "네가 준비했다는 것도 인정하고, 다른 사람한테 주려고 했던 것도 털어놓는 거야.",
  ui_story_5043_50430501_97_dialog_content = "...다만, 그렇게 돼버리면 아무래도 가장 좋은 고백 타이밍은 아니게 되겠지.",
  ui_story_5043_50430501_98_dialog_content = "중요한 건 네 생각이야. 네가 그러고 싶지 않다면 물론 이해할 수 있어...",
  ui_story_5043_50430501_99_dialog_content = "네? 고백이요...? 무슨 고백 말이죠?",
  ui_story_5043_50430501_100_option_content = "좀 더 지켜보자.",
  ui_story_5043_50430501_101_dialog_content = "우선 아무것도 하지 말고, 상황이 어떻게 흘러가는지 보는 거야!",
  ui_story_5043_50430501_102_dialog_content = "지금 멋대로 발언했다간 「심판소 모독죄」를 뒤집어쓸 수도 있잖아.",
  ui_story_5043_50430501_103_dialog_content = "심리 절차대로라면 이다음 순서는 뭔데?",
  ui_story_5043_50430501_104_dialog_content = "음, 이제 원고와 피고 양측이 변론을 할 차례예요.",
  ui_story_5043_50430501_105_dialog_content = "사실 PlayerName 씨가 왜 쿠키를 신경 쓰시는지는 모르겠지만...\n그럼 일단은 슈와브 씨한테 맡기고 재판을 지켜볼게요.",
  ui_story_5043_50430501_106_dialog_content = "아무래도 양측 모두 기다릴 수가 없는 모양이군요. 그럼 변론을 시작하세요.",
  ui_story_5043_50430501_107_dialog_content = "<size=32>어이, 서민 신입. 이대로 놔두면 안 되잖아?</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>뭐라도 해야 되지 않겠어? 물론 티나의 체면도 생각해야겠지만 말이야.</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>저도 같은 생각입니다. 하지만... 우린 티나가 어떻게 생각하는지 아직 모르지 않습니까.</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>티나 본인은 말할 생각이 없는 것 같은데... 아니면 슈와브 쪽에서 먼저 알아채게 만드는 건 어떨까요?</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>오! 너 이 자식 꽤 하잖아!</size>",
  ui_story_5043_50430501_112_dialog_content = "이어서 심판관은 양측에 대한 심문을 진행하세요.",
  ui_story_5043_50430501_113_dialog_content = "크흠... 그럼 원고에게 질문하겠습니다.\n쿠키가 원고 것이 아니라면, 누구 것이라고 생각하십니까?",
  ui_story_5043_50430501_114_dialog_content = "그건... 저도 모르겠습니다... 갑자기 제 테이블 앞에 나타난 거라...",
  ui_story_5043_50430501_115_dialog_content = "<color=#FFB400>누군가 떨어트린</color> 건 아닐까요?",
  ui_story_5043_50430501_116_dialog_content = "호오? 만약 그 말이 맞다면, 쿠키는 달의 살롱 행사 중에 나타났고,\n동일한 장소에서 누군가 잃어버렸다는 셈이 되겠군요.",
  ui_story_5043_50430501_117_dialog_content = "그렇다면 그 쿠키를 잃어버린 주인의 목적이 무엇인지는\n제가 말하지 않아도 이 자리의 모두가 알 겁니다.",
  ui_story_5043_50430501_118_dialog_content = "네, 물론... 누군가한테 <color=#FFB400>선물</color>하려던 거겠죠.",
  ui_story_5043_50430501_119_dialog_content = "하지만 저한테 주려던 선물이 아닌 건 확실해요! 저랑은 아무 상관 없다고요!",
  ui_story_5043_50430501_120_dialog_content = "그럼 이어서 피고에게 묻겠습니다.\n피고는 왜 원고가 쿠키를 받은 것이 피고에게 충실하지 않은 행위라고 생각하십니까?",
  ui_story_5043_50430501_121_dialog_content = "그걸 꼭 말로 해야 알아요? 이 쿠키는 누가 봐도 <color=#FFB400>여자애</color>가 준비한 거잖아요!",
  ui_story_5043_50430501_122_dialog_content = "그런데도 넙죽 받은 걸 보면, 진작부터 저랑 헤어지고 싶었던 거겠죠.",
  ui_story_5043_50430501_123_dialog_content = "그게 바로 양측의 분쟁 원인입니다.\n원고는 분명히 받지 않았다고 하는데, 피고는 계속 원고 것이라고 주장하고 있죠.",
  ui_story_5043_50430501_124_dialog_content = "하지만 <color=#FFB400>카드</color>에 분명히 그런 내용이...",
  ui_story_5043_50430501_125_dialog_content = "...알겠어요! 어쩌면 제가 넘겨짚은 걸 수도 있겠죠.\n그럼 이 쿠키의 주인은 대체 누구에게 이걸 선물하려던 거죠?",
  ui_story_5043_50430501_126_dialog_content = "바로 그것이 이 사건의 핵심입니다!",
  ui_story_5043_50430501_127_dialog_content = "진짜로 이 쿠키를 받을 사람은 사실 피고의 눈앞에 있습니다!",
  ui_story_5043_50430501_128_dialog_content = "제... 눈앞이요?",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>탕! 탕! 탕!</color>",
  ui_story_5043_50430501_130_dialog_content = "레인 심판관, 마티외 심판관! 유도신문을 하지 마세요!",
  ui_story_5043_50430501_131_dialog_content = "여긴 심판소입니다. 죄가 있으면 유죄가 되는 겁니다.",
  ui_story_5043_50430501_132_dialog_content = "이런 이런~ 수많은 소녀들이 연모하는 준수한 슈와브 대심판관님께서\n숙녀의 발언을 저지하다니, 이게 무슨 일이죠?",
  ui_story_5043_50430501_133_dialog_content = "당신에 대한 마음이 담긴 물증이 지금 눈앞에 있는데도,\n그것이 어느 소녀의 것인지도 알아채지 못하시는군요.",
  ui_story_5043_50430501_134_dialog_content = "앗...! 이해했어요... 설마 이 쿠키를 받을 진짜 상대는... 바로...",
  ui_story_5043_50430501_135_dialog_content = "으엑...?",
  ui_story_5043_50430501_136_dialog_content = "정숙하세요!!!",
  ui_story_5043_50430501_137_dialog_content = "여러분, 조용히 해주세요. 할 말이 있어요.",
  ui_story_5043_50430501_138_dialog_content = "티나 심판관, 심리 절차를 방해하는 발언을 삼가세요!",
  ui_story_5043_50430501_139_dialog_content = "슈와브 대심판관님, 저는 저 쿠키 증거물의 주인입니다.\n제가 본 재판에 <color=#FFB400>증인</color> 신분으로 출석하는 것을 허용해 주세요.",
  ui_story_5043_50430501_140_dialog_content = "(티나, 좋습니다! 바로 그 기세입니다!)",
  ui_story_5043_50430501_141_dialog_content = "조, 좋습니다... 대심판관으로서 허락합시다. 증인은 발언하세요.",
  ui_story_5043_50430501_142_dialog_content = "저 쿠키는 제가 만들었어요.",
  ui_story_5043_50430501_143_dialog_content = "저건 두근거림과 불안감으로 가득한 마음으로 제가 손수 만든 쿠키예요.",
  ui_story_5043_50430501_144_dialog_content = "버터크림을 짜서 모양을 만들고, 예쁜 것만 골라서 노릇노릇하게 구웠죠.",
  ui_story_5043_50430501_145_dialog_content = "오직 세상에서 가장 멋진 선물로 보답하려는 마음뿐이었어요.",
  ui_story_5043_50430501_146_dialog_content = "그런데 실수로 그걸 아까 달의 살롱에서 잃어버렸어요.",
  ui_story_5043_50430501_147_dialog_content = "그리고 그 카드가 바로 증거입니다!",
  ui_story_5043_50430501_148_dialog_content = "카드도 제가 직접 만든 거예요.\n그 안에 쓰인 내용과 상대방의 이름을 한 글자도 틀리지 않고 진술할 수 있어요!",
  ui_story_5043_50430501_149_dialog_content = "어머! 이런 식으로 진짜 주인을 만나게 되다니...",
  ui_story_5043_50430501_150_dialog_content = "이것도 정말 멋진 러브스토리네요...",
  ui_story_5043_50430501_151_dialog_content = "...정말 곤란하군요. 아름다운 백합꽃은 언제나 제게 달콤한 부담을 선사한단 말이죠.",
  ui_story_5043_50430501_152_dialog_content = "그렇다면 판결을 내리기 전에, 증인은 피고와 함께 증거를 검증해 주세요.",
  ui_story_5043_50430501_153_dialog_content = "그럼 그 카드에 적힌 이름을 동시에 말하는 걸로 해요.",
  ui_story_5043_50430501_154_dialog_content = "좋아요. 그럼... 셋, 둘, 하나...",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>복슬이</color>!</size>",
  ui_story_5043_50430501_X156_dialog_content = "하아아?",
  ui_story_5043_50430501_156_dialog_content = "...하아?!",
  ui_story_5043_50430501_157_dialog_content = "슈와브 대심판관님... 명문가 출신이면서도 소탈한 분이라고 들은 적은 있지만...",
  ui_story_5043_50430501_158_dialog_content = "남들 모르게 이런... 「친근한」 별명으로 불리고 계셨던 거군요.",
  ui_story_5043_50430501_159_dialog_content = "다운타운 출신으로서 전 대심판관님이 존경스러워졌어요!",
  ui_story_5043_50430501_160_dialog_content = "아, 달링! 이제야 날 의심하지 않는 거구나... 흑흑...",
  ui_story_5043_50430501_161_dialog_content = "「복슬이」라니... 허허허, 꽤나 귀여운 이름이군.",
  ui_story_5043_50430501_162_dialog_content = "슈와브, 「복슬이」는 그대의 아명인가? 아니면 별명 같은 건가?",
  ui_story_5043_50430501_163_dialog_content = "하하하하하하...",
  ui_story_5043_50430501_164_dialog_content = "그...그건...",
  ui_story_5043_50430501_165_dialog_content = "잠시만요, 이게 대체 뭐가 어떻게 된 겁니까?",
  ui_story_5043_50430501_166_dialog_content = "그래요. 대체 무슨 상황인 거죠?",
  ui_story_5043_50430501_167_dialog_content = "이 쿠키랑 카드가... 슈와브 대심판관님과 무슨 상관인데요?",
  ui_story_5043_50430601_1_dialog_content = "그러니까... 이렇게 된 거예요.",
  ui_story_5043_50430601_2_dialog_content = "쿠키는 확실히 제가 복슬 씨를 위해 준비한 거예요.\n하지만 방금 전 피고는 아무래도 오해해 버린 것 같았어요...",
  ui_story_5043_50430601_3_dialog_content = "일이 이렇게 될 줄은 정말 몰랐네요...\n그래도 원고와 피고 사이의 오해가 풀린 건 다행이지만요.",
  ui_story_5043_50430601_4_dialog_content = "하아아?",
  ui_story_5043_50430601_5_dialog_content = "그러니까 원고와 피고뿐만 아니라, 우리도 오해하고 있었다는 겁니까?",
  ui_story_5043_50430601_6_dialog_content = "그래서 그 「복슬이」는 대체 누구야?\n네가 좋아하는 사람이 이 멍청한 대심판관이 아니었다고?!",
  ui_story_5043_50430601_7_dialog_content = "확실히 좀 이상한 점이 있긴 했지만... 우리 전부 대체 어디서부터 착각해 버린 거지?",
  ui_story_5043_50430601_8_dialog_content = "미안해요. 남한테 쉽게 꺼낼 말은 아니어서, 확실하게 설명하질 못했어요.",
  ui_story_5043_50430601_9_dialog_content = "여러분한테 도와달라고 부탁해 놓고, 제대로 말하지 않은 건 제 잘못이에요...!",
  ui_story_5043_50430601_10_dialog_content = "하지만... 아까 심판소에서는 왜 슈와브 대심판관님까지 오해하셨을까요?",
  ui_story_5043_50430601_11_dialog_content = "저희 두 사람은 일상적인 업무나 사교적인 대면 외엔 별다른 접촉이 없었잖아요?",
  ui_story_5043_50430601_12_dialog_content = "누가 자신을 정말로 좋아하는지는 자신이 가장 확실하게 알 수 있는 거 아닌가요?",
  ui_story_5043_50430601_13_dialog_content = "그만해요... 그 얘긴 됐어요...",
  ui_story_5043_50430601_14_dialog_content = "...지금 문제는... 그런 게 아니란 말입니다... 정말 문제인 건...",
  ui_story_5043_50430601_15_dialog_content = "<size=45>이제 심판소의 모든 사람이 제 별명을 복슬이라고 생각하게 됐잖아요!</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>하급 재판관과 다른 심판관들은 지금쯤 이 소문을 사방에 퍼트렸겠죠!</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>이 소문은 이제 곧 하이가든 사교계에서 빅뉴스로 떠돌게 될 겁니다!</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>이게 전부 당신들, 그리고 저 역겨운 쿠키와 카드 때문이 아닙니까!</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>당신들처럼 머릿속에 연애밖에 없는 빌어먹을 남녀들...\n그리고 항상 끈질기게 따라다니는 여자들까지...</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>전부 똑같은 족속들이라고!!!</size>",
  ui_story_5043_50430601_21_dialog_content = "저, 정말 죄송해요!",
  ui_story_5043_50430601_22_dialog_content = "잠시만요, 티나가 실수를 한 건 맞지만, 말이 너무 심하지 않습니까?",
  ui_story_5043_50430601_23_dialog_content = "도중에 대체 무슨 일이 있었는지는 모르겠지만...\n티나가 마음에 두고 있는 게 다른 사람이라서 다행이라고 생각해.",
  ui_story_5043_50430601_24_dialog_content = "......",
  ui_story_5043_50430601_25_dialog_content = "후우우...",
  ui_story_5043_50430601_26_dialog_content = "그럼 아까 당신들이 보고하던 내용 얘기로 돌아갈까요.",
  ui_story_5043_50430601_27_dialog_content = "미드가든 초원 광장의 조각상이 훼손된 일은...\n「목 없는 조각상 사건」의 원고 바이런과는 아무 관계도 없습니다.",
  ui_story_5043_50430601_28_dialog_content = "하지만 이번엔 당신들이 운이 좋았을 뿐이에요.\n더는 원고를 자극해서 새로운 소장을 가져오게 만들지 마세요.",
  ui_story_5043_50430601_29_dialog_content = "이제 당신들 사건의 재판 준비나 하러 가시죠. 얼른 가버리세요.",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>하이가든, 심판소 밖</color>",
  ui_story_5043_50430601_31_dialog_content = "푸...푸하하!",
  ui_story_5043_50430601_32_dialog_content = "너희도 봤겠지! 저 녀석 얼굴 말이다!",
  ui_story_5043_50430601_33_dialog_content = "티나 양, 꽤 하잖아! 아까 그 대사, 치명타였겠어.",
  ui_story_5043_50430601_34_dialog_content = "하하, 여자한테 그런 말을 들은 건 아마 처음이겠죠.",
  ui_story_5043_50430601_35_dialog_content = "아... 두 분 다 그만 놀리세요...",
  ui_story_5043_50430601_36_dialog_content = "정말 미안해요. 저 때문에 여러분까지 같이 혼나고 말았네요.",
  ui_story_5043_50430601_37_dialog_content = "괜찮아. 그런 건 상관없어. 그것보다 지금 신경 쓰이는 건...",
  ui_story_5043_50430601_38_dialog_content = "전에 그랬잖아? 살라르 가문의 장원에서 「그」를 만났다고.",
  ui_story_5043_50430601_39_dialog_content = "그게 슈와브가 아니면 대체 누구였던 거야?",
  ui_story_5043_50430601_40_dialog_content = "역시 제가 말도 안 되는 오해를 만들어 버린 모양이네요.",
  ui_story_5043_50430601_41_dialog_content = "다시 처음부터 말씀드릴게요...",
  ui_story_5043_50430601_42_dialog_content = "그날 제가 살라르 가문의 화원에서 혼자 차를 마시며 독서를 하는 슈와브 씨를 본 건 맞아요.",
  ui_story_5043_50430601_43_dialog_content = "슈와브 씨도 곧 저를 발견했죠. 정원 안쪽까지 외지인이 들어온 걸 보고 놀란 듯했어요.",
  ui_story_5043_50430601_44_dialog_content = "하지만 슈와브 씨는 저만 발견했을 뿐...\n이곳에 있을 리 없는 다른 한 존재는 전혀 눈치채지 못했죠.",
  ui_story_5043_50430601_45_dialog_content = "슈와브 씨 뒤쪽 덤불 속에서 복슬 씨는 겁에 질린 모습으로\n복슬복슬한 머리만 살짝 내민 채 저와 눈이 마주쳤어요.",
  ui_story_5043_50430601_46_dialog_content = "그는 제가 자신이 숨어 있는 걸 말해버리진 않을지 걱정하는 것 같았어요.\n애초에 그런 곳에 암귀가 존재해선 안 되는 거였으니까요.",
  ui_story_5043_50430601_47_dialog_content = "하지만 복슬 씨는 정말 귀여웠고, 공격성도 전혀 없었어요.\n그저 복잡한 화원에서 길을 잃은 작고 불쌍한 존재였죠.",
  ui_story_5043_50430601_48_dialog_content = "게다가 슈와브 씨가 절 보기 전까지, 그는 독서 중인 슈와브 씨 대신\n찻잔에 날아드는 벌레를 쫓고 있었어요.",
  ui_story_5043_50430601_49_dialog_content = "무도회가 끝나자 전 즉시 화원으로 돌아갔고,\n그의 손을 잡고 살라르 가문의 장원에서 데리고 나왔어요.",
  ui_story_5043_50430601_50_dialog_content = "우리의 루미나와 다크매터가 서로 영향을 주지 않도록, 전 새로 산 장갑을 꼈어요.",
  ui_story_5043_50430601_51_dialog_content = "그는 오로리안의 통용어를 이해하고, 간단한 말도 할 수 있었어요.\n그리고 그와 헤어진 후 얼마 뒤, 관월제에 전 그의 감사 인사와 선물을 받게 됐어요.",
  ui_story_5043_50430601_52_dialog_content = "여기까지가 이번 일의 전부예요.",
  ui_story_5043_50430601_53_dialog_content = "(그런 평범한 암귀도 자기 이름을 가질 수 있었던 거구나...)",
  ui_story_5043_50430601_54_dialog_content = "잠시만요. 그럼 그가 「전혀 답장을 하지 않는다」고 말했던 건 무슨 뜻이었죠?",
  ui_story_5043_50430601_55_dialog_content = "복슬 씨는 백야성에 정해진 거처가 없었으니까요.\n전 그가 선물을 부쳤을 때의 발신 주소로 답장을 보냈지만, 아무 소식이 없었죠.",
  ui_story_5043_50430601_56_dialog_content = "그럼 「몰래 만날 수도 없다」는 건 또 뭐였는데?",
  ui_story_5043_50430601_57_dialog_content = "말 그대로예요. 그날 이후로 우린 몰래 만나지도 못했고,\n애초에 어디 있는지도 못 찾았으니까요.",
  ui_story_5043_50430601_58_dialog_content = "「어딜 가나 사람들의 주의를 끈다」...",
  ui_story_5043_50430601_59_dialog_content = "맞아요. 그건 여러분도 이해하시겠죠.\n백야성에 나타난 암귀는 길바닥에 나온 생쥐 같은 존재잖아요.",
  ui_story_5043_50430601_60_dialog_content = "그래서 그때 넌 「사랑」이 아니라고 말했던 거구나...",
  ui_story_5043_50430601_61_dialog_content = "하지만 암귀는 오로리안을 해치기 위해 태어난 생물입니다.\n무해한 암귀라는 게 정말 세상에 존재할 수 있는 겁니까?",
  ui_story_5043_50430601_62_dialog_content = "만약 그게 사실이라면, 저도 제 눈으로 꼭 보고 싶군요.",
  ui_story_5043_50430601_63_dialog_content = "확실히 이런 감정은 오로리안으로서는 불필요한 것이겠지만,\n적어도 「사랑」이라고 부르기엔 적합하지 않은 것 같네요.",
  ui_story_5043_50430601_64_dialog_content = "그런 애매모호한 말보다는, 차라리 그를 돌봐주고 싶다는 편이 맞을 거예요.",
  ui_story_5043_50430601_64X1_dialog_content = "하지만 누가 뭐라 해도 암귀 같은 생물은 역겹단 말이다.",
  ui_story_5043_50430601_64X2_dialog_content = "킁킁, 킁킁...",
  ui_story_5043_50430601_64X3_dialog_content = "티나 양, 이건 겁주려고 하는 소리가 아냐.\n지금 당신 몸에서조차 암귀 냄새가 나는 것 같다고.",
  ui_story_5043_50430601_64X4_dialog_content = "네? 이렇게 한참이나 안 만났는데도 냄새가 나는 건가요... 미안해요...",
  ui_story_5043_50430601_65_dialog_content = "먼저 말해두겠어. 법은 백야성을 지키는 철벽이야. 내가 봐줄 거라고 생각하지 마.",
  ui_story_5043_50430601_66_dialog_content = "호위대의 체포 명단에는 당신이 말한 암귀는 아직 없어.",
  ui_story_5043_50430601_67_dialog_content = "하지만 이번 일은 여기서 마무리 지어야 하지 않을까?",
  ui_story_5043_50430601_68_dialog_content = "음... 감사해요, 카렌 전하.\n심판소의 일원으로서 이 일의 중대성은 저도 잘 알고 있어요...",
  ui_story_5043_50430601_69_dialog_content = "오로리안이 암귀를 기른다는 건 애초에 황당한 이야기겠죠.",
  ui_story_5043_50430601_69X1_dialog_content = "모두에게 큰 폐를 끼쳤네요... 지금부터는 다시 소송 사건 조사에 전념할게요.",
  ui_story_5043_50430601_69X2_dialog_content = "폐만 끼쳤다곤 할 수 없겠죠. 재밌는 일도 있었잖아요?",
  ui_story_5043_50430601_70_dialog_content = "티나, 당신 정말... 이번엔 제대로 한 건 했군요.",
  ui_story_5043_50430601_71_dialog_content = "하하하하! 그러게 말이야. 역시 너희들하고 일하길 잘했어!",
  ui_story_5043_50430601_72_dialog_content = "덕분에 생각보다 더 재미있는 구경을 했잖아.",
  ui_story_5043_50430601_74_dialog_content = "아하하... 사건 조사엔 진척도 없고, 선물 때문에 엉뚱한 웃음거리가 됐지만...",
  ui_story_5043_50430601_75_dialog_content = "그래도... 저도 여러분과 같은 마음이에요!",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>콰당──</color>",
  ui_story_5043_50430601_77_dialog_content = "티나?! 티나!",
  ui_story_5043_50430601_78_dialog_content = "어떻게 된 거야...? 너희들 왜 가만히 보고만 있어? 어서 도와줘!",
  ui_story_5043_50430601_79_dialog_content = "휴~ 안심하시죠, 공주 전하. 그냥 잠들었을 뿐이니까요.",
  ui_story_5043_50430601_80_dialog_content = "오늘은 많은 일이 있었으니, 지금쯤 한계였을 겁니다.",
  ui_story_5043_50430601_81_dialog_content = "하인을 불러 마차로 티나를 집까지 데려다주도록 하지요.",
  ui_story_5043_50430601_82_dialog_content = "휴, 휴우... 카렌 전하...",
  ui_story_5043_50430601_83_dialog_content = "호오~ 뢰베. 우리 집 하인이 되고 싶어진 거냐?\n이거 어쩌나, 우린 고용 조건이 꽤 깐깐한데 말이지~",
  ui_story_5043_50430601_84_dialog_content = "빨리 말해 봐.",
  ui_story_5043_50430601_85_dialog_content = "전하의 짐작대로였습니다.",
  ui_story_5043_50430601_86_dialog_content = "그 경비병들은 트로이 가문의 문장을 달고 있었습니다.",
  ui_story_5043_50430601_87_dialog_content = "그리고 살롱에도 이상한 점이 있었습니다.",
  ui_story_5043_50430601_88_dialog_content = "뭐라고요?",
  ui_story_5043_50430601_89_dialog_content = "매번 달의 살롱이 끝날 때마다, 암귀의 습격이 발생했습니다.",
  ui_story_5043_50430601_90_dialog_content = "그리고 살롱 주변에 있는 조각상의 머리도 함께 사라졌죠.",
  ui_story_5043_50430601_91_dialog_content = "죄송합니다. 제가 조사한 건 여기까지입니다.",
  ui_story_5043_50430601_92_dialog_content = "......",
  ui_story_5043_50430601_93_dialog_content = "수고했어, 뢰베.",
  ui_story_5043_50430601_94_dialog_content = "이제 조금만 더 있으면 쉴 수 있을 거야.",
  ui_story_5043_50430702_1_dialog_content = "경비병의 정체가 밝혀진 이상, 나도 더는 보고만 있진 않겠어.",
  ui_story_5043_50430702_2_dialog_content = "PlayerName, 난 하이가든 호위대로 돌아가서 회의를 열고 다음 대책을 세워야 해.",
  ui_story_5043_50430702_3_dialog_content = "그리고 최근 암귀의 소동에 대해 성주님께 보고해야겠어.",
  ui_story_5043_50430702_4_dialog_content = "알겠어, 얼른 가 봐. 우리 쪽은 걱정하지 말고.",
  ui_story_5043_50430702_5_dialog_content = "응, 늦어도 개정일까진 돌아올게.",
  ui_story_5043_50430702_6_dialog_content = "몸조심해.",
  ui_story_5043_50430702_7_dialog_content = "다들 힘드실 텐데, 오늘은 이만 돌아가도록 하죠.",
  ui_story_5043_50430702_8_dialog_content = "내일 업무 계획은...",
  ui_story_5043_50430702_9_dialog_content = "내일 뭘 해야 할지는 다들 알고 있을 거잖아?",
  ui_story_5043_50430702_10_dialog_content = "이렇게 의심스러운 살롱이라면, 물론 주최자한테 소환장을 보내야지.",
  ui_story_5043_50430702_11_dialog_content = "확실히 지금까지의 상황으로 보자면 달의 살롱은 수상한 점이 한두가지가 아니야...",
  ui_story_5043_50430702_12_dialog_content = "자, 그럼 내일은 달 열기구의 방향을 따라 그 수녀님을 만나러 갑시다.",
  ui_story_5043_50430702_13_dialog_content = "그럼 방금 무슨 일이 있었는지 누가 설명 좀 해 줄래?",
  ui_story_5043_50430702_14_dialog_content = "그리고 티나는 왜 또 잠들었어?",
  ui_story_5043_50430702_15_dialog_content = "쳇, 귀찮은 녀석. 가면서 설명해 줄 테니까 좀 기다려 봐.",
  ui_story_5043_50430702_16_dialog_content = "마차가 왔군. 우린 티나를 데려다 줄 테니까, PlayerName, 레인, 내일 보자고.",
  ui_story_5043_50430702_17_dialog_content = "...네?",
  ui_story_5043_50430702_18_dialog_content = "뭐냐?",
  ui_story_5043_50430702_19_dialog_content = "왜 「서민 신입」이라고 안 부릅니까?",
  ui_story_5043_50430702_20_dialog_content = "...잔말도 많네!",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5043_50430702_22_dialog_content = "으음... 그랬군요.",
  ui_story_5043_50430702_23_dialog_content = "말씀하신 대로예요. 달의 살롱 회장은 매번 제가 신중하게 고르고 있어요.",
  ui_story_5043_50430702_24_dialog_content = "전 문화나 예술의 공기가 감도는 장소를 좋아하거든요.\n그래서 항상 조각상이 있는 장소를 특히 선호해 왔어요.",
  ui_story_5043_50430702_25_dialog_content = "「노인」이나 「남성」, 「어린이」...\n그리고 방금 여러분이 말씀하신 두 구의 「여성」 조각상...",
  ui_story_5043_50430702_26_dialog_content = "모두 백야성 문명의 기초가 되는 것들이죠.",
  ui_story_5043_50430702_27_dialog_content = "하지만 살롱의 회장이 된 자리에 있던 조각상이 모두 부서져 버린 것도 사실입니다.",
  ui_story_5043_50430702_28_dialog_content = "네, 살롱이 혼란을 초래했다는 걸 부정할 생각은 없어요.\n소동이 발생했을 때 제가 그 자리에 없었다는 증거도 없죠. 하지만...",
  ui_story_5043_50430702_29_dialog_content = "만물은 백야 아래에.\n부서진 조각상이든, 암귀의 습격이든, 저와는 상관없는 일이에요.",
  ui_story_5043_50430702_30_dialog_content = "(이 사람, 무척 평온한 표정을 하고 있어. 부드러운 말투랑 마찬가지로 아무 흔들림도 없어.)",
  ui_story_5043_50430702_31_dialog_content = "(게다가 정말 당당하네. 이런 게 신앙의 힘이라는 건가...)",
  ui_story_5043_50430702_32_dialog_content = "(왠지... 이 사람은 정말로 사건과는 관계가 없을 것 같아.)",
  ui_story_5043_50430702_33_dialog_content = "쳇... 또 단서가 끊어졌잖아. 혐의만 가지고 사람을 잡을 순 없어.",
  ui_story_5043_50430702_34_dialog_content = "수녀님, 빛의 신께서는 모든 것을 보고 계십니다. 만약 지금 하신 말씀이 모두 진실이라면...",
  ui_story_5043_50430702_35_dialog_content = "심판소에 증인으로 출석해 주실 수 있겠습니까?",
  ui_story_5043_50430702_36_dialog_content = "최근 살롱 일로 계속 바쁘긴 하지만, 그게 심판소의 뜻이라면...",
  ui_story_5043_50430702_37_dialog_content = "최대한 협조해 드릴게요.",
  ui_story_5043_50430702_38_dialog_content = "하지만...!",
  ui_story_5043_50430702_39_dialog_content = "(이 수녀님을 심판소로 데려간다면... 괜히 곤란하게 만드는 거잖아요...)",
  ui_story_5043_50430702_40_dialog_content = "...어머? 그쪽 아가씨도 뭔가 하실 말씀이 있으신가요?",
  ui_story_5043_50430702_41_dialog_content = "궁금한 게 있어요. 수녀님은 어떻게 그렇게 침착하실 수 있는 거죠?",
  ui_story_5043_50430702_42_dialog_content = "전 달의 살롱을 싫어하지 않아요. 오히려 그 분위기가 무척 마음에 들어요.\n달의 살롱은 백야성에 새로운 모습을 가져다주었으니까요.",
  ui_story_5043_50430702_43_dialog_content = "하지만 백야성의 규칙이나 상식으론 자유연애는커녕 이혼조차도 용납되지 않아요.",
  ui_story_5043_50430702_44_dialog_content = "그럼에도 불구하고 성직자이자 독실한 신자인 당신은...",
  ui_story_5043_50430702_45_dialog_content = "어떻게 백야성에 이런 살롱을 만들 결심을 하신 건가요?",
  ui_story_5043_50430702_46_dialog_content = "게다가 심판소 같은 곳에 가는 것도 두려워하지 않다니...\n그런 태도에 전 정말 감탄했어요.",
  ui_story_5043_50430702_47_dialog_content = "티나...",
  ui_story_5043_50430702_48_dialog_content = "후훗... 아가씨, 지금 그건 당신 스스로의 고민이나 생각이 담긴 이야기인가요?",
  ui_story_5043_50430702_49_dialog_content = "제 나이 정도가 되면, 앞뒤 일을 그렇게 고민하지 않게 돼요.",
  ui_story_5043_50430702_50_dialog_content = "전 그저 빛의 신을 믿는 제 마음을 따르고 있을 뿐이에요.",
  ui_story_5043_50430702_51_dialog_content = "백야성은 그 오랜 역사 속에서 금욕에 기초한 계급 제도와,\n수많은 복잡한 예절과 의례를 만들어 냈죠.",
  ui_story_5043_50430702_52_dialog_content = "하지만 그런 백야성도 처음엔 그저 노인, 남성, 여성, 어린이와 같은\n평범하면서도 고결한 오로리안들이 세운 도시였어요.",
  ui_story_5043_50430702_53_dialog_content = "빛의 신의 교리 또한 오랜 시간의 역사적 흐름과 함께 변화해 왔죠.",
  ui_story_5043_50430702_54_dialog_content = "그러나 그 교리 역시 처음 탄생했을 땐 그저 단순하고 선한 것만을 담고 있었어요.",
  ui_story_5043_50430702_55_dialog_content = "그것들은 모두 빛의 신께서 주신 축복이자 가르침이에요.",
  ui_story_5043_50430702_56_dialog_content = "제가 지금 하는 모든 일은 그저 오로리안의 기원으로 돌아가,\n본연의 마음을 따르고 있을 뿐이에요.",
  ui_story_5043_50430702_57_dialog_content = "이것들은 애초에 죄가 되지 않아요. 그저 규칙이나 제도에 이해받지 못할 뿐이죠.",
  ui_story_5043_50430702_58_dialog_content = "신앙도, 연애도... 모든 것은 같은 이치랍니다.",
  ui_story_5043_50430702_59_dialog_content = "왜, 왠지 조금은 알 것 같아요. 질문에 답해 주셔서 고마워요.",
  ui_story_5043_50430702_60_dialog_content = "그럼 먼저 실례할게요.",
  ui_story_5043_50430702_61_dialog_content = "앞으로의 조사엔 계속 협조해 드릴게요.",
  ui_story_5043_50430702_62_dialog_content = "하지만 심판관 여러분, 지금 만약 어려움에 처해 있다면,\n제 조언을 들어 보시는 건 어떨까요?",
  ui_story_5043_50430702_63_dialog_content = "음...?",
  ui_story_5043_50430702_64_dialog_content = "만약 여러분이 단순히 업무의 절차를 밟고 있는 게 아니라,\n정말로 개정 전까지 유의미한 정보를 얻고 싶은 마음이라면...",
  ui_story_5043_50430702_65_dialog_content = "목적만 염두에 둔 형식적인 조사 대신, 원고의 진짜 생각이 무엇인지를 알아야 해요.",
  ui_story_5043_50430702_66_dialog_content = "충고 감사드립니다. 참고하도록 하죠...",
  ui_story_5043_50430702_67_dialog_content = "네, 그럼 또 만나요.",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5043_50430801_2_dialog_content = "어이, 조사 결과가 이게 다라는 거냐?",
  ui_story_5043_50430801_3_dialog_content = "첫 번째 사건도 해결을 못 했는데, 또 다른 조각상이 부서졌다고?!",
  ui_story_5043_50430801_4_dialog_content = "정말 죄송합니다. 사건은 아직 조사 중입니다만, 아직까지는 결정적인 진전이 없는 상황입니다...",
  ui_story_5043_50430801_5_dialog_content = "「결정적」이고 뭐고 그냥 진전 자체가 없잖아!",
  ui_story_5043_50430801_6_dialog_content = "백야성의 심판소가 이거밖에 안 되는 거였냔 말이다!",
  ui_story_5043_50430801_7_dialog_content = "차라리 눈먼 개한테 부탁하는 게 더 낫겠네. 적어도 범인 냄새는 맡을 거 아냐!",
  ui_story_5043_50430801_8_dialog_content = "죄송합니다. 조사에 더 매진하도록 하겠습니다...",
  ui_story_5043_50430801_9_dialog_content = "됐어! 심판소는 애초에 백성들의 사랑 같은 건 안중에도 없었던 거겠지!",
  ui_story_5043_50430801_10_dialog_content = "이 「연애 심판소」니 뭐니 하는 것도 죄다 월급 도둑들 아냐?!",
  ui_story_5043_50430801_11_dialog_content = "돈도 많이 받으면서, 하는 일이라곤 허구한 날 매일 잠만 퍼자고 말이야!",
  ui_story_5043_50430801_12_dialog_content = "반박할 수가 없군요. 확실히 그런 사람이 있거든요.",
  ui_story_5043_50430801_13_dialog_content = "자, 잠은 업무 능률에 도움이 되는걸요...",
  ui_story_5043_50430801_14_dialog_content = "더는 못 참아! 모레면 개정일이라고!",
  ui_story_5043_50430801_15_dialog_content = "잘 들어라. 만약 내일까지 아무 성과도 없다면, 난 계속해서 그 이웃을 고소할 거다.",
  ui_story_5043_50430801_16_dialog_content = "그래도 안 되면 이리돈 대심판관님께 민원을 넣을 것이다!",
  ui_story_5043_50430801_17_dialog_content = "고액 연봉을 받는 심판관이 백성들의 문제도 해결해 주지 않는다면,\n이런 심판소는 차라리 없애버리는 게 낫다고!",
  ui_story_5043_50430801_18_dialog_content = "없앤다구요?!",
  ui_story_5043_50430801_19_dialog_content = "아니, 그렇게 심하게 나올 건 없잖아요?",
  ui_story_5043_50430801_20_dialog_content = "바이런 씨, 일단 진정하세요...",
  ui_story_5043_50430801_21_dialog_content = "흥, 그러니까 알아서 잘들 해!",
  ui_story_5043_50430801_22_dialog_content = "가, 가버렸어...",
  ui_story_5043_50430801_23_dialog_content = "큰일이네. 연애 심판소... 생각보다 더 곤란한 상황 같은데?",
  ui_story_5043_50430801_24_dialog_content = "뭐, 됐어. 이제 끝장이야.",
  ui_story_5043_50430801_25_dialog_content = "이리돈 대심판관님은 백성들의 목소리를 가장 신경 쓰시는 분이다. 민원이 들어온다면...",
  ui_story_5043_50430801_26_dialog_content = "맞아요. 대심판관님이 분명히 크게 화내실 거예요.",
  ui_story_5043_50430801_27_dialog_content = "연애 심판소는 임시로 설치된 심판소입니다.\n상부에서 우리가 제구실을 못 하고 있다고 판단한다면...",
  ui_story_5043_50430801_28_dialog_content = "정말로 폐지될 가능성이 있어요.",
  ui_story_5043_50430801_29_dialog_content = "뭐야, 정말 내가 말한 대로 됐잖아.",
  ui_story_5043_50430801_30_dialog_content = "이렇게 된 이상, 다들 해임돼도 이상할 게 없겠어.",
  ui_story_5043_50430801_31_dialog_content = "해임?!",
  ui_story_5043_50430801_32_dialog_content = "그건 절대 안 돼!",
  ui_story_5043_50430801_33_dialog_content = "그, 그런 무서운 말은 하지 말아주세요...",
  ui_story_5043_50430801_34_dialog_content = "해임되면 지루하게 집에만 있어야 한다고! 재미라곤 하나도 없잖아!",
  ui_story_5043_50430801_35_dialog_content = "아니... 신경 쓰는 포인트가 이상하잖아!",
  ui_story_5043_50430801_36_dialog_content = "낮에도 잠을 잘 수 있는 직업을 또 어디 가서 찾아야 할까요...",
  ui_story_5043_50430801_37_dialog_content = "지금 하는 일도 낮에 자면 안 되잖아!",
  ui_story_5043_50430801_38_dialog_content = "새로운 일자리를 못 구하면... 집에서 절 잡아갈 거예요.",
  ui_story_5043_50430801_39_dialog_content = "그럼 전 억지로 가업을 계승하게 되겠죠...",
  ui_story_5043_50430801_40_dialog_content = "아, 맞아. 우리 집 고집불통들도 똑같은 짓을 하겠지.",
  ui_story_5043_50430801_41_dialog_content = "난 집에서 돈이나 세는 일 따윈 관심 없단 말이다!",
  ui_story_5043_50430801_42_dialog_content = "...제일 쓸데없는 게 귀족 걱정이라더니... 역시 내가 걱정할 필요가 전혀 없었잖아.",
  ui_story_5043_50430801_43_dialog_content = "그럼 뭐 다들 잘려도 별문제 없는 거잖아! 너무 풀 죽지 마!",
  ui_story_5043_50430801_44_dialog_content = "그렇습니다. 진짜로 일자리를 잃는다 해도 삶은 계속돼야 합니다.",
  ui_story_5043_50430801_45_dialog_content = "하지만 월급이 없어진다면... 감자와 야채를 좀 비축해 둬야겠군요.",
  ui_story_5043_50430801_46_dialog_content = "내일부터 1일 1식을 하는 게 좋겠습니다.",
  ui_story_5043_50430801_47_dialog_content = "뭐야... 레인 씨만 너무 현실적이잖아!",
  ui_story_5043_50430801_48_dialog_content = "백야성에서 살아간다는 현실은 원래 그런 겁니다.",
  ui_story_5043_50430801_49_dialog_content = "매일 지출하는 식비, 사회생활을 위한 최소한의 사교 지출...\n살아있는 한 매일 돈을 써야 하죠.",
  ui_story_5043_50430801_50_dialog_content = "그러니 수입원이 사라진다면 반드시 면밀한 계획을 세워야 합니다.",
  ui_story_5043_50430801_51_dialog_content = "무거워... 삶의 무게가 너무 무겁다고...",
  ui_story_5043_50430801_52_dialog_content = "아직 포기하긴 일러요. 우리에겐 아직 하루가 남아 있잖아요. 지금이라도 뭔가 해야죠!",
  ui_story_5043_50430801_53_dialog_content = "그렇습니다. 뭔가 행동을 취한다면 조사에 진전이 있을지도 모릅니다.",
  ui_story_5043_50430801_54_dialog_content = "하지만 지금 가장 큰 문제는 우리가 가진 단서가 하나도 없다는 겁니다.",
  ui_story_5043_50430801_55_dialog_content = "어떤 쪽으로 노력해야 할지...",
  ui_story_5043_50430801_56_dialog_content = "자, 신사 숙녀 여러분, 나한테 생각이 있어!",
  ui_story_5043_50430801_57_dialog_content = "생각해 봤는데, 우린 그동안 고정관념에 사로잡혀 있었어.",
  ui_story_5043_50430801_58_dialog_content = "「목 없는 조각상 연쇄 사건」은 결코 평범한 형사사건이 아니야.",
  ui_story_5043_50430801_59_dialog_content = "피해자는 조각상이야. 그러니 인간관계 같은 문제로 범인의 동기를 조사할 수 없지.",
  ui_story_5043_50430801_60_dialog_content = "그리고 조각상이기 때문에 혈흔을 찾아 범인의 행적을 추적할 수도 없어.",
  ui_story_5043_50430801_61_dialog_content = "그렇습니다. 그게 지금 우리 앞을 가로막고 있는 장애물입니다.",
  ui_story_5043_50430801_62_dialog_content = "하지만 고정관념을 없애고 다시 한번 잘 생각해 보자고~",
  ui_story_5043_50430801_63_dialog_content = "조각상 파괴 행위가 사건으로서 수리된 결정적 요인은...",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>사랑</color>이에요!",
  ui_story_5043_50430801_65_dialog_content = "바로 그거야~ 연애 감정이 달린 문제니까 우리 연애 지부로 배당된 거지.",
  ui_story_5043_50430801_66_dialog_content = "어떤 일이든 일단 애정 문제가 얽히게 되면,\n더는 단순하게 이성적인 관점만으로는 대할 수 없게 되지.",
  ui_story_5043_50430801_67_dialog_content = "다시 말해서 우리가 지금 상대하고 있는 건 사건이 아닌 감정의 갈등이다!",
  ui_story_5043_50430801_68_dialog_content = "으음... 왠지 갈피가 잡히는 것 같아요!",
  ui_story_5043_50430801_69_dialog_content = "잠깐만요, 전 아직 아무것도 모르겠습니다만...",
  ui_story_5043_50430801_70_dialog_content = "...다들 자기가 지금 뭐라고 했는지 들어볼래?",
  ui_story_5043_50430801_71_dialog_content = "우린 단서를 찾지 못했다. 하지만 이 문제의 해결에 꼭 단서가 필요한 건 아니라고.",
  ui_story_5043_50430801_72_dialog_content = "사랑 앞에선 모든 원인과 결과를 따질 필요가 없어!",
  ui_story_5043_50430801_73_dialog_content = "중요한 건 마음이니까.",
  ui_story_5043_50430801_74_dialog_content = "그 수녀가 했던 말을 떠올려 봐.",
  ui_story_5043_50430801_75_dialog_content = "만약 여러분이 단순히 업무의 절차를 밟고 있는 게 아니라,\n정말로 개정 전까지 유의미한 정보를 얻고 싶은 마음이라면...",
  ui_story_5043_50430801_76_dialog_content = "목적만 염두에 둔 형식적인 조사 대신, 원고의 진짜 생각이 무엇인지를 알아야 해요.",
  ui_story_5043_50430801_77_dialog_content = "...마음으로 해결한다는 겁니까?",
  ui_story_5043_50430801_78_dialog_content = "자, 이제 움직일 시간이야, 친구들.",
  ui_story_5043_50430801_79_dialog_content = "원고를 위해 사랑이 가득한 답을 찾아주자고!",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5043_50430801_81_dialog_content = "어이, 왜 날 막는 거지?",
  ui_story_5043_50430801_82_dialog_content = "얼른 들어가게 해 줘!",
  ui_story_5043_50430801_83_dialog_content = "바이런 씨, 잠시만 기다려 주세요.",
  ui_story_5043_50430801_84_dialog_content = "지금 심판관님들은 공무를 처리하는 중이에요.",
  ui_story_5043_50430801_85_dialog_content = "시간이 되면 바로 안내해 드릴게요.",
  ui_story_5043_50430801_86_dialog_content = "공무? 무슨 헛소리야? 내 사건이야말로 공무다!",
  ui_story_5043_50430801_87_dialog_content = "안에 틀어박혀 있으면 나한테서 도망칠 줄 알았나! 좀 더 그럴듯한 이유라도 만들었어야지!",
  ui_story_5043_50430801_88_dialog_content = "바이런 씨, 심판관님들은 지금 정말로...",
  ui_story_5043_50430801_89_dialog_content = "저들이 뭘 하고 있든 난 상관 안 해. 어차피 지금은 업무 시간이잖아?",
  ui_story_5043_50430801_90_dialog_content = "자, 잠시만요... 바이런 씨...",
  ui_story_5043_50430801_91_dialog_content = "비켜!",
  ui_story_5043_50430801_92_dialog_content = "아, 정말...",
  ui_story_5043_50430801_93_dialog_content = "<size=45>마티외 심판관님! 들어가셨어요!</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>팡──! 팡──! 팡──!</color>",
  ui_story_5043_50430801_95_dialog_content = "축하드립니다, 바이런 씨!",
  ui_story_5043_50430801_96_dialog_content = "축하드려요~",
  ui_story_5043_50430801_97_dialog_content = "평범했을 일상에 다시 돌아온 사랑! 축하드립니다!",
  ui_story_5043_50430801_98_dialog_content = "하아? 이건...",
  ui_story_5043_50430801_99_dialog_content = "저희가 하루 꼬박 일해서 그녀의 머리를 다시 만들었어요.",
  ui_story_5043_50430801_100_dialog_content = "조금만 더 늦게 오셨으면... 더 아름다웠겠지만요!",
  ui_story_5043_50430801_101_dialog_content = "그렇습니다~ 저흰 사랑에 대해 다시 한번 생각해 보았고, 이러한 해결 방법을 찾아냈습니다.",
  ui_story_5043_50430801_102_dialog_content = "중요한 건 「무엇을 잃었느냐」가 아니라, 「무엇을 얻을 수 있느냐」입니다.",
  ui_story_5043_50430801_103_dialog_content = "애인의 머리가 부서졌다 해서 당신의 사랑을 막을 수 있습니까?",
  ui_story_5043_50430801_104_dialog_content = "아니죠, 당신은 그래도 사랑할 겁니다.\n다만 그녀의 불완전함에 안타까움을 느끼고 있을 뿐이죠.",
  ui_story_5043_50430801_105_dialog_content = "그 슬픔을 해결할 유일한 방법은 바로 그녀를 온전한 모습으로 되돌리는 겁니다.",
  ui_story_5043_50430801_106_dialog_content = "하하, 잃어버린 것을 되찾는 이야기는 항상 아름다운 법입니다...",
  ui_story_5043_50430801_107_dialog_content = "다, 당신들...",
  ui_story_5043_50430801_108_dialog_content = "<size=45>대체 이게 무슨 짓거리야?!</size>",
  ui_story_5043_50430801_109_dialog_content = "갈라테아의 목 위에 올려둔 이 추한 쓰레기는 뭐냔 말이다!\n지금 날 모욕할 셈이냐!",
  ui_story_5043_50430801_110_dialog_content = "이게... 추하단 말입니까...?",
  ui_story_5043_50430801_111_dialog_content = "마음에 안 드시는 모양이네요...",
  ui_story_5043_50430801_112_dialog_content = "쳇, 내가 말했잖아. 서민 신입의 미적 감각은 믿을 수 없다고.",
  ui_story_5043_50430801_113_dialog_content = "지금 모습이 마음에 안 드신다면 다시 만들어 드리겠습니다...",
  ui_story_5043_50430801_114_dialog_content = "웃기지 마라! 이런 어리석은 행동은 사랑에 대한 모독이다!",
  ui_story_5043_50430801_115_dialog_content = "애송이들, 니들이 사랑을 알아?!",
  ui_story_5043_50430801_116_dialog_content = "사랑이란 유일무이한 것이다! 한번 사랑하면 그 선택은 평생 변하지 않아!",
  ui_story_5043_50430801_117_dialog_content = "갈라테아가 부서진 그 순간부터, 내 사랑은 이미 죽은 거란 말이다!",
  ui_story_5043_50430801_118_dialog_content = "설령 똑같은 머리를 다시 만들어 낸들, 그건 이미 갈라테아가 아니야!",
  ui_story_5043_50430801_119_dialog_content = "더는 내 마음속 유일한 사랑이 아니라고!",
  ui_story_5043_50430801_120_dialog_content = "아, 그런 거였군요...!",
  ui_story_5043_50430801_121_dialog_content = "으엑... 그럼 어제 내가 잘못 이해했다는 건가?",
  ui_story_5043_50430801_122_dialog_content = "역시 실패인가요. 아무래도 재판은 피할 수 없을 것 같군요...",
  ui_story_5043_50430801_123_dialog_content = "됐다. 이 건은 일단 미뤄두자고.",
  ui_story_5043_50430801_124_dialog_content = "오늘은 더 중요한 일이 있어서 찾아왔다.",
  ui_story_5043_50430801_125_dialog_content = "지금 이 순간에도 나의 「<color=#FFB400>아내</color>」가 생명의 위험에 처해 있다!",
  ui_story_5043_50430801_126_dialog_content = "우리의 사랑을 지킬 수 있도록 지금 즉시 사람을 보내서 내 아내의 안전을 확보해라!",
  ui_story_5043_50430801_127_dialog_content = "자, 잠시만요! 부인께서 생명의 위험에 처해 있다고요?",
  ui_story_5043_50430801_128_dialog_content = "부인께선 지금 여기 계시잖아요?",
  ui_story_5043_50430801_129_dialog_content = "틀렸어. 갈라테아는 내 「<color=#FFB400>애인</color>」이다.",
  ui_story_5043_50430801_130_dialog_content = "지금 위기에 처한 건 내 「<color=#FFB400>아내</color>」라고.",
  ui_story_5043_50430801_131_dialog_content = "하아?!",
  ui_story_5043_50430801_132_dialog_content = "아내와 애인이 다르다고?!",
  ui_story_5043_50430801_133_dialog_content = "당연하지. 내 아내 또한 아름다운 조각상이다. 이름은 「아프로디테」라고 하지.",
  ui_story_5043_50430801_134_dialog_content = "어떻게 그럴 수 있죠? 방금 사랑은 유일무이한 거라면서요!",
  ui_story_5043_50430801_135_dialog_content = "물론 유일무이하지!",
  ui_story_5043_50430801_136_dialog_content = "그럼 어떻게 동시에 두 조각상을 사랑하실 수가 있죠?",
  ui_story_5043_50430801_137_dialog_content = "사랑은 유일무이한 동시에 드넓은 것이기 때문이지.",
  ui_story_5043_50430801_138_dialog_content = "난 내 아내를 사랑하고, 내 애인도 사랑한다. 두 사랑 모두 유일무이한 것이다.",
  ui_story_5043_50430801_139_dialog_content = "비유를 하자면, 어머니를 사랑한다고 해서 동시에 아버지를 사랑할 수 없는 건 아니잖나.",
  ui_story_5043_50430801_140_dialog_content = "그렇게 말하니까 왠지 일리가 있는 것 같기도...",
  ui_story_5043_50430801_141_dialog_content = "...아니죠! 전혀 안 맞는 비유잖아요!",
  ui_story_5043_50430801_142_dialog_content = "됐어! 지금 너희 같은 애송이들에게 사랑이 뭔지 가르치고 있을 시간은 없다!",
  ui_story_5043_50430801_143_dialog_content = "방금 전에 달 열기구가 「천성의 계단」 위쪽에 뜬 걸 봤다.",
  ui_story_5043_50430801_144_dialog_content = "거긴 내 아내가 있는 곳이다.",
  ui_story_5043_50430801_145_dialog_content = "너희도 알고 있겠지? 달 열기구는 달의 살롱이 개최된다는 신호다.\n그리고 조각상은 항상 그 살롱 도중에 파괴되고 있지.",
  ui_story_5043_50430801_146_dialog_content = "만약 내 아내에게까지 무슨 일이 생긴다면... 나...난 이제 모든 사랑을 잃고 만단 말이다...",
  ui_story_5043_50430801_147_dialog_content = "백성들의 사랑을 지키는 게 너희들이 해야 할 일 아닌가?",
  ui_story_5043_50430801_148_dialog_content = "기왕 이 사건을 맡은 이상, 물론 당신의 사랑을 지킬 겁니다.",
  ui_story_5043_50430801_149_dialog_content = "쳇, 「2분의 1의 사랑」이겠지.",
  ui_story_5043_50430801_150_dialog_content = "게다가 사건이 일어날 가능성이 있다는 건, 단서를 찾을 수 있을지도 모른다는 뜻이죠.",
  ui_story_5043_50430801_151_dialog_content = "이 「목 없는 조각상 연쇄 사건」을 해결하려면 꼭 가야 합니다!",
  ui_story_5043_50430801_152_dialog_content = "그럼 뭘 기다리고 있어? 빨리 가!",
  ui_story_5043_50430801_153_dialog_content = "달 열기구 아래에서 곧 살롱이 열릴 거다!",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>미드가든, 천성의 계단 근처</color>",
  ui_story_5043_50430801_155_dialog_content = "자, 바로 저기다.",
  ui_story_5043_50430801_156_dialog_content = "바이런 씨는 부인이 여기 있다고 했어. 그럼...",
  ui_story_5043_50430801_157_dialog_content = "찾았습니다! 이 조각상이 맞을 겁니다!",
  ui_story_5043_50430801_158_dialog_content = "오! 아직 안 부서졌네!",
  ui_story_5043_50430801_159_dialog_content = "이걸 지키고 있으면 되는 거지?",
  ui_story_5043_50430801_160_dialog_content = "맞아, 범인은 아마 살롱이 진행되는 중에 범행을 저지르겠지.",
  ui_story_5043_50430801_161_dialog_content = "근데 살롱 참가자들은 어디 있지?",
  ui_story_5043_50430801_162_dialog_content = "저기 보여요! 다들 계단 밑에 모여있어요!",
  ui_story_5043_50430801_163_dialog_content = "그렇네. 안 올라오나?",
  ui_story_5043_50430801_164_dialog_content = "오, 그럼 우린 운이 좋군.",
  ui_story_5043_50430801_165_dialog_content = "살롱이 계단 밑에서 열린다면, 계단 위에 있는 조각상을 지키는 건 쉽잖아.",
  ui_story_5043_50430801_166_dialog_content = "다행이네요, 이제 바이런 씨한테도 체면이 서겠어요...",
  ui_story_5043_50430801_167_dialog_content = "어머, 심판관 여러분, 여기 계셨네요.",
  ui_story_5043_50430801_168_dialog_content = "수녀님! 이렇게 금방 다시 만날 줄은 몰랐네요.",
  ui_story_5043_50430801_169_dialog_content = "여긴 달 열기구 아래니까요. 절 만나게 되는 건 당연한 일이죠.",
  ui_story_5043_50430801_170_dialog_content = "모처럼 와주셨으니까 여러분도 행사에 참석해 주세요.",
  ui_story_5043_50430801_171_dialog_content = "계단 아래에서 개최되는 살롱에 말입니까?",
  ui_story_5043_50430801_172_dialog_content = "초대해 주셔서 기쁩니다만, 오늘은 다른...",
  ui_story_5043_50430801_173_dialog_content = "아뇨, 오늘 활동은 살롱이 아니에요.",
  ui_story_5043_50430801_174_dialog_content = "네? 그럼...",
  ui_story_5043_50430801_175_dialog_content = "<size=45>여러분, 준비되셨나요?</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>시위를 시작하죠!</size>",
  ui_story_5043_50430901_1_dialog_content = "사랑은 우리가 찬미해야 하는 것~♪",
  ui_story_5043_50430901_2_dialog_content = "신성한 백야성에서 찬미해~♪",
  ui_story_5043_50430901_3_dialog_content = "연인이 서로 사랑할 때 찬미해~♪",
  ui_story_5043_50430901_4_dialog_content = "사랑이 주는 아름다움을 찬미해~♪",
  ui_story_5043_50430901_5_dialog_content = "맞아, 사랑은 우리가 찬미해야 하는 것~♪",
  ui_story_5043_50430901_6_dialog_content = "사랑을 찬미하자!",
  ui_story_5043_50430901_7_dialog_content = "시위대, 출발!",
  ui_story_5043_50430901_8_dialog_content = "으악! 사람들이 무리 지어 계단을 올라온다!",
  ui_story_5043_50430901_9_dialog_content = "이거 불길한데?",
  ui_story_5043_50430901_10_dialog_content = "그러게요, 만약 시위대가 조각상을 지나간다면...\n저 난리 통에 조각상을 지키긴 힘들 거예요...",
  ui_story_5043_50430901_11_dialog_content = "조각상이 눈앞에서 부서지기라도 하면 너희 일자리는...",
  ui_story_5043_50430901_12_dialog_content = "이대론 안 됩니다. 어떻게든 시위대를 막아야 합니다!",
  ui_story_5043_50430901_13_dialog_content = "시위를 막는다고요? 무슨 일이죠? 시위대에 무슨 문제라도 있나요?",
  ui_story_5043_50430901_14_dialog_content = "좀처럼 있기 힘든 활동인데, 막아야겠다면 충분한 이유를 제시해 주세요.",
  ui_story_5043_50430901_15_dialog_content = "행진 속도가 빠릅니다. 더는 시간이 없어요.",
  ui_story_5043_50430901_16_dialog_content = "제가 막으러 갈 테니 여러분은 수녀님께 설명해 주세요!",
  ui_story_5043_50430901_17_dialog_content = "휴... 역시 서민은 막무가내란 말이지...",
  ui_story_5043_50430901_18_dialog_content = "크흠, 수녀 아가씨, 저희도 할 수 있다면 막고 싶진 않습니다.",
  ui_story_5043_50430901_19_dialog_content = "하지만 이것도 사랑을 위한 것입니다.",
  ui_story_5043_50430901_20_dialog_content = "사랑을 위해서라고요?",
  ui_story_5043_50430901_21_dialog_content = "시위의 어수선함을 틈타 나쁜 짓을 하려는 자가 있습니다.",
  ui_story_5043_50430901_22_dialog_content = "당신도 주최자로서 자신이 준비한 활동이\n「사랑을 깨트렸다」는 오명을 쓰는 걸 원하진 않겠죠?",
  ui_story_5043_50430901_23_dialog_content = "사랑을 찬미하자!",
  ui_story_5043_50430901_24_dialog_content = "자! 유! 연! 애!",
  ui_story_5043_50430901_25_dialog_content = "저기, 다들 잠깐만!",
  ui_story_5043_50430901_26_dialog_content = "아무래도 행진 방향이 틀린 것 같아.",
  ui_story_5043_50430901_27_dialog_content = "행진 목적지는 미드가든의 주거 구역이라는데?",
  ui_story_5043_50430901_28_dialog_content = "전부 돌아가야 해!",
  ui_story_5043_50430901_29_dialog_content = "맞아! 돌아가자!",
  ui_story_5043_50430901_30_dialog_content = "뭐? 방향이 틀렸다고?",
  ui_story_5043_50430901_31_dialog_content = "그럴 리가 없잖아! 천성의 계단을 오르기로 한 거 아니었어?",
  ui_story_5043_50430901_32_dialog_content = "전달 실수겠지. 사람이 많아서 정보가 엇갈린 것 같아.",
  ui_story_5043_50430901_33_dialog_content = "네? 주거 구역이라고요?",
  ui_story_5043_50430901_34_dialog_content = "전 미드가든 광장이라고 들었는데요!",
  ui_story_5043_50430901_35_dialog_content = "여기서 가려면 좀 머니까, 얼른 돌아가죠!",
  ui_story_5043_50430901_36_dialog_content = "그래! 얼른 가자!",
  ui_story_5043_50430901_37_dialog_content = "돌아간다고...? 여기까지 왔는데...?",
  ui_story_5043_50430901_38_dialog_content = "그래!",
  ui_story_5043_50430901_39_dialog_content = "하지만 원래 목적지는 주거 구역이라고.",
  ui_story_5043_50430901_40_dialog_content = "아니에요, 광장이에요!",
  ui_story_5043_50430901_41_dialog_content = "잠깐만, 오늘 시위는 분명히 천성의 계단을 오르는 거였어.",
  ui_story_5043_50430901_42_dialog_content = "맞아! 아니면 왜 계단 밑에서 집합했겠어?",
  ui_story_5043_50430901_43_dialog_content = "주거 구역이니 광장이니... 그 정보는 대체 누구한테 들은 거야?",
  ui_story_5043_50430901_44_dialog_content = "백발에 꽁지머리를 묶은 녀석이었어. 믿을 만해 보였고,",
  ui_story_5043_50430901_45_dialog_content = "꽤 믿음직하게 생긴 사람이었어요. 백발에 꽁지머리를 묶고 있었죠.",
  ui_story_5043_50430901_46_dialog_content = "뭐야, 그럼 같은 사람이잖아?! 너희 속은 거야!",
  ui_story_5043_50430901_47_dialog_content = "하?!",
  ui_story_5043_50430901_48_dialog_content = "백발에 꽁지머리를 묶은 녀석... 여기 있잖아!",
  ui_story_5043_50430901_49_dialog_content = "아니요, 전 그냥 지나가던 사람입니다만...",
  ui_story_5043_50430901_50_dialog_content = "저 사람 맞아!",
  ui_story_5043_50430901_51_dialog_content = "저 사람한테 들었어요!",
  ui_story_5043_50430901_52_dialog_content = "처음 보는 얼굴인데? 감히 사랑의 이름으로 행진하는 시위를 방해하다니!",
  ui_story_5043_50430901_53_dialog_content = "잡아서 연애 심판소에 회부합시다!",
  ui_story_5043_50430901_54_dialog_content = "...그, 그럴 필요 없습니다. 안 그래도 거기 갈 겁니다...",
  ui_story_5043_50430901_55_dialog_content = "가자! 이대로 천성의 계단을 올라가자!",
  ui_story_5043_50430901_56_dialog_content = "녀석이 도망치지 못하게 막아!",
  ui_story_5043_50430901_57_dialog_content = "(이런... 역시 임시방편으로 떠올린 방법은 통하질 않잖아.)",
  ui_story_5043_50430901_58_dialog_content = "(행렬이 더 전진하고 있어. 대체 어떻게 해야...)",
  ui_story_5043_50430901_59_dialog_content = "이런~ 이거 큰일이네. 우유통이랑 꿀통을 엎어버렸어!",
  ui_story_5043_50430901_60_dialog_content = "나도 참, 왜 이렇게 덤벙대는 건지~",
  ui_story_5043_50430901_61_dialog_content = "뭐야?! 우유가 계단에서 잔뜩 흘러 내려오고 있어!",
  ui_story_5043_50430901_62_dialog_content = "도대체 우유통을 몇 개나 쏟아야 이렇게 되는 거야?!",
  ui_story_5043_50430901_63_dialog_content = "꿀까지 섞여 있잖아?!",
  ui_story_5043_50430901_64_dialog_content = "(이, 이건... 마티외식 돌직구인가?!)",
  ui_story_5043_50430901_65_dialog_content = "(어처구니없긴 하지만 효과는 있는 것 같아... 시위대의 행진이 멈췄어!)",
  ui_story_5043_50430901_66_dialog_content = "오늘은 정말 운이 없네.",
  ui_story_5043_50430901_67_dialog_content = "포기하면 안 됩니다! 빛의 신께서도 말씀하셨습니다!\n시련을 이겨내야만 행복을 얻을 수 있습니다!",
  ui_story_5043_50430901_68_dialog_content = "맞아요! 젖과 꿀이 흐르는 길이라면 올바른 방향일 겁니다!",
  ui_story_5043_50430901_69_dialog_content = "다들 조심해서 갑시다! 넘어지지 않게 조심하세요!",
  ui_story_5043_50430901_70_dialog_content = "(또 전진하는 건가?!)",
  ui_story_5043_50430901_71_dialog_content = "(정말 무서운 의지네...)",
  ui_story_5043_50430901_72_dialog_content = "<size=45>아얏...!</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>이 계단, 너무 미끄럽잖아요!</size>",
  ui_story_5043_50430901_74_dialog_content = "무슨 일이야?!",
  ui_story_5043_50430901_75_dialog_content = "선두에서 누가 넘어진 것 같은데?!",
  ui_story_5043_50430901_76_dialog_content = "으으... 아파, 너무 아파요...",
  ui_story_5043_50430901_77_dialog_content = "너무 아파서 낮인데 별이 보이는 것 같아요...",
  ui_story_5043_50430901_78_dialog_content = "크게 다친 모양이에요!",
  ui_story_5043_50430901_79_dialog_content = "계단이 미끄러우면 확실히 위험하지...",
  ui_story_5043_50430901_80_dialog_content = "...역시 오늘은 날이 아닌 건가?",
  ui_story_5043_50430901_81_dialog_content = "그래요. 시위는 다른 곳에 가서 해도 되잖아요.",
  ui_story_5043_50430901_82_dialog_content = "이대로 천성의 계단을 막고 있는 것도 곤란하겠네요.\n얼른 누가 저 여자애를 병원에 좀 데려다주세요.",
  ui_story_5043_50430901_83_dialog_content = "시위대가 돌아간다!",
  ui_story_5043_50430901_84_dialog_content = "대단해, 티나!",
  ui_story_5043_50430901_85_dialog_content = "정말 실감 나는 연기였어!",
  ui_story_5043_50430901_86_dialog_content = "헤헷, 심판소를 그만두면 배우에 도전하는 건 어떨까요?",
  ui_story_5043_50430901_87_dialog_content = "내 방법은 어땠냐?",
  ui_story_5043_50430901_88_dialog_content = "마티외 씨도 대단했어!",
  ui_story_5043_50430901_89_dialog_content = "다들 정말... 당돌한 젊은이들이군요.",
  ui_story_5043_50430901_90_dialog_content = "뭐, 그래요. 저희 활동의 취지도 해치지 않았으니, 당신들 뜻대로 할게요.",
  ui_story_5043_50430901_91_dialog_content = "모든 사랑은 지켜져야만 해요.\n설령 그 대상이 조각상일지라도 그 점은 변하지 않아요.",
  ui_story_5043_50430901_92_dialog_content = "역시 살롱의 주최자님답군요. 넓은 아량에 감사드리죠~",
  ui_story_5043_50430901_93_dialog_content = "그럼 전 먼저 실례할게요. 이제 가서 시위대를 다른 곳으로 이끌어야 하니까요.",
  ui_story_5043_50430901_94_dialog_content = "여러분도 힘내세요.",
  ui_story_5043_50430901_95_dialog_content = "안 돼! 뒤로 물러서지 마!",
  ui_story_5043_50430901_96_dialog_content = "빨리 계단 위로 올라가!",
  ui_story_5043_50430901_97_dialog_content = "무슨 일이야?! 갑자기 왜 시끄러워졌어?!",
  ui_story_5043_50430901_98_dialog_content = "암귀다! 어떻게 암귀가 저기서 나타났지?!",
  ui_story_5043_50430901_99_dialog_content = "다들 어서 계단을 올라가!",
  ui_story_5043_50430901_100_dialog_content = "뭐야? 암귀가 어디서 튀어나왔어?!",
  ui_story_5043_50430901_101_dialog_content = "저기 보여! 수가 그리 많지는 않아!",
  ui_story_5043_50430901_102_dialog_content = "레인은 벌써 암귀랑 싸우고 있어!",
  ui_story_5043_50430901_103_dialog_content = "우리도 도우러 가요!",
  ui_story_5043_50430901_104_dialog_content = "다들 조각상을 잊은 건 아니겠지? 시위대가 이쪽으로 몰려올 거야.",
  ui_story_5043_50430901_105_dialog_content = "암귀는 얼마 없는 것 같으니까 한 사람 정도만 도우러 가면 될 것 같아.",
  ui_story_5043_50430901_106_dialog_content = "티나, 레인 씨를 도우러 가 줘. 나머지 사람들은 여기서 조각상을 지키자.",
  ui_story_5043_50430901_107_dialog_content = "암귀와 싸우게 되면 내가 감응 능력으로 도와줄게!",
  ui_story_5043_50430901_108_dialog_content = "알겠어요, 그렇게 할게요!",
  ui_story_5043_50430901_109_dialog_content = "그럼 조각상은 여러분께 부탁할게요. 꼭 지켜주세요!",
  ui_story_5043_50431001_1_dialog_content = "저게 마지막 한 마리예요!",
  ui_story_5043_50431001_2_dialog_content = "제가 맡겠습니다!",
  ui_story_5043_50431001_3_dialog_content = "좋아요! 이걸로 적은 다 쓰러트렸어요.",
  ui_story_5043_50431001_4_dialog_content = "하지만... 시위대는 모두 계단을 올라가 버린 것 같군요.",
  ui_story_5043_50431001_5_dialog_content = "PlayerName 씨 쪽은 어떻게 됐을까요?",
  ui_story_5043_50431001_6_dialog_content = "다들 조심하세요!",
  ui_story_5043_50431001_7_dialog_content = "여긴 엄청 비싼 조각상이 있어요! 부수면 변상해야 한다구요!",
  ui_story_5043_50431001_8_dialog_content = "암귀다! 빨리 도망쳐!",
  ui_story_5043_50431001_9_dialog_content = "다들 당황하지 마세요! 암귀는 이미 다 처치했어요!",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431001_11_dialog_content = "뭐야?!",
  ui_story_5043_50431001_12_dialog_content = "이런! 누가 조각상에 부딪혔어!",
  ui_story_5043_50431001_13_dialog_content = "다행히 조각상은 무사한 것 같긴 한데...",
  ui_story_5043_50431001_14_dialog_content = "으아아아아악!",
  ui_story_5043_50431001_15_dialog_content = "또 왔어!",
  ui_story_5043_50431001_16_dialog_content = "마티외 씨, 사람들을 막아줘!",
  ui_story_5043_50431001_17_dialog_content = "나보고 뭘 어쩌...",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431001_19_dialog_content = "으악!",
  ui_story_5043_50431001_20_dialog_content = "괜찮아?",
  ui_story_5043_50431001_21_dialog_content = "그런 거 물어볼 시간에 부축부터 좀 하지 그래?!",
  ui_story_5043_50431001_22_dialog_content = "이런! 암귀가 인파 속에 뒤섞였다!",
  ui_story_5043_50431001_23_dialog_content = "암귀가?!",
  ui_story_5043_50431001_24_dialog_content = "진짜네! 사람들 사이에 암귀 몇 마리가 있어!",
  ui_story_5043_50431001_25_dialog_content = "대체 어디서 온 거지?",
  ui_story_5043_50431001_26_dialog_content = "당황하지 마! 내가 신발로 때려잡을 테니까!",
  ui_story_5043_50431001_27_dialog_content = "신발로 암귀를 쓰러트릴 수 있어?!",
  ui_story_5043_50431001_28_dialog_content = "잠깐만! 왜 신발을 조각상 쪽으로 던지는 거냐고!",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431001_30_dialog_content = "바이런 씨가 신발 자국을 신경 쓰지 않았으면 좋겠는데 말이야...",
  ui_story_5043_50431001_31_dialog_content = "나도 간다! 받아라!",
  ui_story_5043_50431001_32_dialog_content = "또야?!",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431001_34_dialog_content = "어이, 조각상은 괜찮나?",
  ui_story_5043_50431001_35_dialog_content = "아직까진 괜찮은데... 이대로 계속 가다간...",
  ui_story_5043_50431001_36_dialog_content = "다들 신발 좀 그만 던져요! 신발을 던져봤자 석고상 하나 못 부순다구요!",
  ui_story_5043_50431001_37_dialog_content = "그런 걸로 암귀를 쓰러트릴 수 있을 리가 없잖아요!",
  ui_story_5043_50431001_38_dialog_content = "그것도 그렇네! 다른 더 좋은 무기는 없나?",
  ui_story_5043_50431001_39_dialog_content = "있어! 여기 돌처럼 딱딱한 치즈를 가져왔어!",
  ui_story_5043_50431001_40_dialog_content = "치즈를 가지고 다니는 사람이 어디 있어!",
  ui_story_5043_50431001_41_dialog_content = "...망했어... 치즈를 던졌다간 조각상이 정말로...",
  ui_story_5043_50431001_42_dialog_content = "다들 진정하세요! 더는 물건을 던지지 마세요!",
  ui_story_5043_50431001_43_dialog_content = "이쪽으로 물건 던지지 마세요!",
  ui_story_5043_50431001_44_dialog_content = "수녀님이다!",
  ui_story_5043_50431001_45_dialog_content = "다들 멈춰! 막 던지다 수녀님이 맞으면 어떡하려고 그래?",
  ui_story_5043_50431001_46_dialog_content = "휴, 어떻게든 진정됐네요.",
  ui_story_5043_50431001_47_dialog_content = "수녀님, 고마워요!",
  ui_story_5043_50431001_48_dialog_content = "천만에요. 해야 할 일을 했을 뿐인걸요.",
  ui_story_5043_50431001_49_dialog_content = "이 활동이 관월제의 사랑을 계승하는 이상,\n누군가의 사랑을 망쳤다는 오명을 쓰게 만들 순 없어요!",
  ui_story_5043_50431001_50_dialog_content = "(이렇게 조각상을 지켜주는 걸 보면...\n이 사람은 확실히 「목 없는 조각상 연쇄 사건」과는 관계가 없겠어.)",
  ui_story_5043_50431001_51_dialog_content = "드디어 사람들이 자리를 떠나기 시작했군.",
  ui_story_5043_50431001_52_dialog_content = "이제야 한숨 돌릴 수 있겠네.",
  ui_story_5043_50431001_53_dialog_content = "그러게.",
  ui_story_5043_50431001_54_dialog_content = "당황한 군중들이 암귀보다 더 무서울 줄은 몰랐다니까.",
  ui_story_5043_50431001_55_dialog_content = "정말, 이럴 줄 진작 알았으면 암귀나 처리하러 갔을 거라고.",
  ui_story_5043_50431001_56_dialog_content = "거기 다들 뭘 멍하니 있는 겁니까!",
  ui_story_5043_50431001_57_dialog_content = "레인 씨! 돌아왔구나...",
  ui_story_5043_50431001_58_dialog_content = "뒤를 보세요!",
  ui_story_5043_50431001_59_dialog_content = "암귀가 또 있단 말입니다!",
  ui_story_5043_50431002_1_dialog_content = "깜짝 놀래키는 것밖에 모르는 이 빌어먹을 자식들...",
  ui_story_5043_50431002_2_dialog_content = "막상 싸우면 한 주먹거리도 안 되면서 말이야!",
  ui_story_5043_50431002_3_dialog_content = "방심하면 안 됩니다. 아직 다 쓰러트리지 않았잖습니까.",
  ui_story_5043_50431002_4_dialog_content = "같이 깨끗하게 해치워 버리자고!",
  ui_story_5043_50431002_5_dialog_content = "...잠깐!",
  ui_story_5043_50431002_6_dialog_content = "PlayerName, 네 옆에 그건 뭐냐...",
  ui_story_5043_50431002_7_dialog_content = "내 옆?!",
  ui_story_5043_50431002_8_dialog_content = "웬 팔이...",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5043_50431002_10_dialog_content = "이런! 조각상이...",
  ui_story_5043_50431002_11_dialog_content = "대체 누구야?!",
  ui_story_5043_50431002_12_dialog_content = "제가 범인의 손을 잡았습니다!",
  ui_story_5043_50431002_13_dialog_content = "암귀들 사이에 끼어 있습니다! 빨리 끌어내야 합니다!",
  ui_story_5043_50431002_14_dialog_content = "성가신 자식들! 저리 꺼져!",
  ui_story_5043_50431002_15_dialog_content = "음? 아무도 없는데?",
  ui_story_5043_50431002_16_dialog_content = "죄송합니다. 놓쳐 버렸군요...",
  ui_story_5043_50431002_17_dialog_content = "장갑만 남기고 도망치다니, 이런 도마뱀 같은 수작을...",
  ui_story_5043_50431002_18_dialog_content = "제길! 눈앞에서 조각상을 부수게 놔두다니!",
  ui_story_5043_50431002_19_dialog_content = "이래가지고 돌아가서 뭐라고 보고하겠냔 말이다!",
  ui_story_5043_50431002_20_dialog_content = "그래도... 우리한텐 범인의 장갑이 있잖아?",
  ui_story_5043_50431002_21_dialog_content = "이거 중요한 단서 아냐?",
  ui_story_5043_50431002_22_dialog_content = "조사에 있어서는 중요한 돌파구가 되겠죠.",
  ui_story_5043_50431002_23_dialog_content = "하지만... 바이런 씨에겐 받아들이기 힘든 결과일 겁니다...",
  ui_story_5043_50431002_24_dialog_content = "참, 티나는 어디 갔지?",
  ui_story_5043_50431002_25_dialog_content = "레인 씨랑 같이 있던 거 아니었어?",
  ui_story_5043_50431002_26_dialog_content = "급하게 돌아오느라 제가 미처 신경 쓰지 못했습니다.\n아마 도중에 뒤처진 것 같습니다.",
  ui_story_5043_50431002_27_dialog_content = "여러분, 다들 괜찮으신가요?!",
  ui_story_5043_50431002_28_dialog_content = "미안해요. 계단을 올라오다가 암귀를 만나서 늦었네요.",
  ui_story_5043_50431002_29_dialog_content = "...조각상의 머리가 없어졌잖아요?!",
  ui_story_5043_50431002_30_dialog_content = "하아...",
  ui_story_5043_50431002_31_dialog_content = "아무튼 돌아가서 보고하도록 하죠.",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>하이가든, 심판소</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>아! 아내가...! 내 아내가!</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>나의 아프로디테여──!</size>",
  ui_story_5043_50431002_35_dialog_content = "......",
  ui_story_5043_50431002_36_dialog_content = "아, 망했네.",
  ui_story_5043_50431002_37_dialog_content = "대체 왜... 이런 일이 벌어진 것인가...",
  ui_story_5043_50431002_38_dialog_content = "내 사랑은 그리도 간절했고, 그 사랑을 지키려고 미리 준비했건만...",
  ui_story_5043_50431002_39_dialog_content = "어째서... 사랑은 하나둘씩 날 떠나가는 것이란 말이냐...",
  ui_story_5043_50431002_40_dialog_content = "난 내가 사랑하는 조각상을 구하지 못했다... 하나도 구하지 못했어...",
  ui_story_5043_50431002_41_dialog_content = "바이런 씨, 상황은 모두 이해했습니다.",
  ui_story_5043_50431002_42_dialog_content = "이해했다고?",
  ui_story_5043_50431002_43_dialog_content = "무슨 소리야! 이미 다 끝났는데!",
  ui_story_5043_50431002_44_dialog_content = "이 세상엔 더는 내가 사랑할 만한 존재가 없단 말이다!",
  ui_story_5043_50431002_45_dialog_content = "빛의 신이시여, 어찌 제게 이런 시련을 주시나이까...",
  ui_story_5043_50431002_46_dialog_content = "일단 진정하세요.",
  ui_story_5043_50431002_47_dialog_content = "이미 벌어진 일은 돌이킬 수 없겠죠.",
  ui_story_5043_50431002_48_dialog_content = "하지만 심판소는 당신을 위해 정의를 실현할 겁니다.",
  ui_story_5043_50431002_49_dialog_content = "심판소? 흥!",
  ui_story_5043_50431002_50_dialog_content = "너희들이 무능해서 내 아내가 이런 봉변을 당한 거다!",
  ui_story_5043_50431002_51_dialog_content = "심판관이 셋이나 모였는데 진범도 못 찾았고, 조각상도 지키지 못했잖아!",
  ui_story_5043_50431002_52_dialog_content = "기다려라. 이제 곧 이리돈 대심판관님께서 너희들의 「찬란한 업적」을 알게 되실 거다!",
  ui_story_5043_50431002_53_dialog_content = "대심판관님께선 심판소의 명성에 먹칠을 한 너희의 무능함을 결코 용납하지 않으시겠지!",
  ui_story_5043_50431002_54_dialog_content = "바이런 씨, 실망하게 해드려 죄송합니다.",
  ui_story_5043_50431002_55_dialog_content = "저흰 범인이 조각상을 부수는 걸 막지 못했고, 범인을 잡지도 못했습니다.",
  ui_story_5043_50431002_56_dialog_content = "하지만... 적어도 범인이 범행 시 끼고 있던 장갑은 확보할 수 있었습니다.",
  ui_story_5043_50431002_57_dialog_content = "세상에, 내 아내의 아름다운 머리를 대가로 얻은 게 고작 장갑 한 짝이라는 거냐!",
  ui_story_5043_50431002_58_dialog_content = "너희 설마 지금 자기들이 큰 성과라도 냈다고 생각하는 건 아니겠지?",
  ui_story_5043_50431002_59_dialog_content = "백야성에 얼마나 많은 주민이 사는지, 장갑이 몇 개나 있는지 알고 있나?",
  ui_story_5043_50431002_60_dialog_content = "그 장갑이 있다고 해서, 너희 연애 심판소의 비참한 업무 능률로 뭘 할 수 있지?!",
  ui_story_5043_50431002_61_dialog_content = "바이런 씨, 일부 실수가 있었다고 해서 연애 지부 전체를 매도하시는 건 곤란합니다.",
  ui_story_5043_50431002_62_dialog_content = "제 부하의 일 처리가 다소 미흡했던 건 사실입니다.\n하지만 전 대심판관으로서 모든 사건에 반드시 공정한 심판을 내릴 겁니다.",
  ui_story_5043_50431002_63_dialog_content = "공정한 심판? 그런 훌륭한 말은 이리돈 대심판관님께 변명할 때나 쓰라고!",
  ui_story_5043_50431002_64_dialog_content = "내가 사랑하는 애인과 아내가 잇따라 화를 입었는데,\n범인은 법의 심판을 피해서 유유히 도망쳤다.",
  ui_story_5043_50431002_65_dialog_content = "그게 대체 어디가 공정하다는 거냐!",
  ui_story_5043_50431002_66_dialog_content = "그러니까~ 그렇게 흥분하지 마시라니까요, 바이런 씨.",
  ui_story_5043_50431002_67_dialog_content = "아직 개정도 안 했는데 「법의 심판을 피했다」는 말은 시기상조 아닌가요?",
  ui_story_5043_50431002_68_dialog_content = "흥, 개정 전까지 범인을 잡기라도 할 수 있다는 건가?",
  ui_story_5043_50431002_69_dialog_content = "레인 심판관, 장갑을 증거물로 제출해 주세요.",
  ui_story_5043_50431002_70_dialog_content = "네.",
  ui_story_5043_50431002_71_dialog_content = "이 장갑은 범행 현장에서 당신이 범인의 손에서 벗겨낸 게 확실한가요?",
  ui_story_5043_50431002_72_dialog_content = "네. 범인을 거의 다 잡은 상황이었지만, 범인은 장갑을 버리고 도주했습니다.",
  ui_story_5043_50431002_73_dialog_content = "그렇다면 이 단서의 의미는 매우 단순하군요.\n이 장갑의 주인이 곧 조각상 사건의 진범입니다.",
  ui_story_5043_50431002_74_dialog_content = "그리고 마침 제 부하가 <color=#FFB400>나머지 한쪽 장갑</color>을 찾아냈습니다.",
  ui_story_5043_50431002_75_dialog_content = "보세요. 이 두 장갑은 한 쌍이 맞죠?",
  ui_story_5043_50431002_76_dialog_content = "나머지 장갑을 찾았다고?",
  ui_story_5043_50431002_77_dialog_content = "?!",
  ui_story_5043_50431002_78_dialog_content = "정말이군요!",
  ui_story_5043_50431002_79_dialog_content = "이걸 어디서 찾은 겁니까? 대체 이게 누구 거죠?",
  ui_story_5043_50431002_80_dialog_content = "이것으로...사건의 진상은 밝혀졌습니다.",
  ui_story_5043_50431002_81_dialog_content = "경비병, 명령입니다!",
  ui_story_5043_50431002_82_dialog_content = "티나 캠벨을 체포하세요!",
  ui_story_5043_50431002_83_dialog_content = "뭐? 티나를 체포해?!",
  ui_story_5043_50431002_84_dialog_content = "예!",
  ui_story_5043_50431101_1_dialog_content = "잠깐만요! 뭔가 잘못된 게 아닙니까?!",
  ui_story_5043_50431101_2_dialog_content = "티나가 범인일 리가 없잖습니까!",
  ui_story_5043_50431101_3_dialog_content = "그래! 티나일 리가 없잖아!",
  ui_story_5043_50431101_4_dialog_content = "슈와브 대심판관, 너 바보야?",
  ui_story_5043_50431101_5_dialog_content = "무능한 심판관 여러분... 제 추론 근거는 아까 명확하게 진술했을 텐데요.",
  ui_story_5043_50431101_6_dialog_content = "레인 심판관이 입수한 장갑이야말로 결정적인 증거입니다.\n그 장갑의 주인이 곧 진범이죠.",
  ui_story_5043_50431101_7_dialog_content = "제 부하는 사건 발생 직후, 범행 현장에서 입수한 장갑과\n짝을 이루는 다른 장갑을 발견했습니다.",
  ui_story_5043_50431101_8_dialog_content = "그리고 그 장갑은 티나 심판관의 책상 서랍에 숨겨져 있었습니다.",
  ui_story_5043_50431101_9_dialog_content = "뭐라고요?!",
  ui_story_5043_50431101_10_dialog_content = "티나, 이 장갑... 정말 당신 겁니까?",
  ui_story_5043_50431101_11_dialog_content = "화...확실히 제가 그 디자인의 장갑을 갖고 있는 건 맞아요.",
  ui_story_5043_50431101_12_dialog_content = "하지만 어째서 그게 범행 현장에서 발견된 거죠...?",
  ui_story_5043_50431101_13_dialog_content = "티나 심판관, 자신이 처한 상황을 아직 모르겠습니까?",
  ui_story_5043_50431101_14_dialog_content = "지금 당신은 용의자입니다. 그 질문은 당신이 우리에게 답해야죠.",
  ui_story_5043_50431101_15_dialog_content = "당신처럼 아름다운 백합꽃이 이처럼 추악한 일을 저지를 줄은 몰랐습니다.",
  ui_story_5043_50431101_16_dialog_content = "정말 가슴이 아프네요.",
  ui_story_5043_50431101_17_dialog_content = "그럴 리가 없습니다! 멋대로 모함하지 마시죠!",
  ui_story_5043_50431101_18_dialog_content = "사건 당시 티나는 저희와 함께 암귀를 처단하고 있었습니다.",
  ui_story_5043_50431101_19_dialog_content = "저희가 모두 증인입니다. 티나는 범인이 아닙니다!",
  ui_story_5043_50431101_20_dialog_content = "레인, 심판관으로서 자신의 말에 책임을 져야 할 겁니다.",
  ui_story_5043_50431101_21_dialog_content = "위증의 대가가 어떤지는 제가 굳이 설명할 필요도 없겠죠?",
  ui_story_5043_50431101_22_dialog_content = "녀석이 한 말은 틀림없는 사실이야. 나도 증명할 수 있다고!",
  ui_story_5043_50431101_23_dialog_content = "그런가요? 잘 생각해 보세요.",
  ui_story_5043_50431101_24_dialog_content = "사건이 일어나는 그 순간, 티나 심판관이 정말 당신들과 함께 싸우고 있었나요?",
  ui_story_5043_50431101_25_dialog_content = "티나는...",
  ui_story_5043_50431101_26_dialog_content = "참, 티나는 어디 갔지?",
  ui_story_5043_50431101_27_dialog_content = "레인 씨랑 같이 있던 거 아니었어?",
  ui_story_5043_50431101_28_dialog_content = "급하게 돌아오느라 제가 미처 신경 쓰지 못했습니다.\n아마 도중에 뒤처진 것 같습니다.",
  ui_story_5043_50431101_29_dialog_content = "여러분, 다들 괜찮으신가요?!",
  ui_story_5043_50431101_30_dialog_content = "(이런... 티나는 그때 확실히 우리랑 같이 있지 않았어!)",
  ui_story_5043_50431101_31_dialog_content = "떠오른 모양이군요.",
  ui_story_5043_50431101_32_dialog_content = "증언을 진술할 때는 모든 한 마디 한 마디를 신중하게 해야 합니다.",
  ui_story_5043_50431101_33_dialog_content = "그 점을 배우지 못하면 어엿한 심판관이라고 할 수 없지요.",
  ui_story_5043_50431101_34_dialog_content = "......",
  ui_story_5043_50431101_35_dialog_content = "자, 범인도 잡혔으니, 이 바보 같은 소동은 이만 끝내도록 하죠.",
  ui_story_5043_50431101_36_dialog_content = "바이런 씨, 결과에 만족하셨는지요.",
  ui_story_5043_50431101_37_dialog_content = "세상에! 범인이 심판관 중에 있었다니!",
  ui_story_5043_50431101_38_dialog_content = "뭘 하든 그렇게 무능했던 이유가 있었어!",
  ui_story_5043_50431101_39_dialog_content = "바이런 씨, 이건 뭔가 잘못된 겁니다...",
  ui_story_5043_50431101_40_dialog_content = "너희들에게 희망을 건 내가 바보였지.",
  ui_story_5043_50431101_41_dialog_content = "입으로는 사랑을 지킨다고 하면서, 실제로는 박살 내고 있었잖아!",
  ui_story_5043_50431101_42_dialog_content = "대심판관, 이 비열한 범인에게 꼭 엄벌을 내려 주게!",
  ui_story_5043_50431101_43_dialog_content = "범인에겐 반드시 심판을 내리겠습니다. 하지만 그게 지금은 아닙니다.",
  ui_story_5043_50431101_44_dialog_content = "여러분, 잊으신 건 아니겠죠? 「목 없는 조각상 연쇄 사건」의 개정일은 내일입니다.",
  ui_story_5043_50431101_45_dialog_content = "개정 후 원고는 심판소에 출석해 진술해야 합니다.",
  ui_story_5043_50431101_46_dialog_content = "알겠네.",
  ui_story_5043_50431101_47_dialog_content = "내 애인과 아내는 이 사건 때문에 비참한 일을 당했네.",
  ui_story_5043_50431101_48_dialog_content = "대심판관, 반드시 공정하게 재판해 주시게!",
  ui_story_5043_50431101_49_dialog_content = "물론이죠~ 연애 심판소는 이 세상의 모든 죄 없는 사랑에\n공정한 재판을 내리기 위해 존재하는 거니까요.",
  ui_story_5043_50431101_50_dialog_content = "경비병, 용의자를 데려가세요.",
  ui_story_5043_50431101_51_dialog_content = "잠시만요!",
  ui_story_5043_50431101_52_dialog_content = "슈와브 대심판관님, 다시 한번 증거물을 조사해 봐도 되겠습니까?",
  ui_story_5043_50431101_53_dialog_content = "티나는 절대 범인이 아닙니다. 증거물의 귀속 판단에 착오가 있었을지도 모릅니다.",
  ui_story_5043_50431101_54_dialog_content = "이렇게 티나를 체포하는 건 경솔한 처사입니다!",
  ui_story_5043_50431101_55_dialog_content = "그래! 디자인이 똑같다고 무조건 한 쌍인 물건인 건 아니잖아!",
  ui_story_5043_50431101_56_dialog_content = "색이나 디자인이 같은 장갑이라면 나도 일곱 쌍은 가지고 있다고!",
  ui_story_5043_50431101_57_dialog_content = "여러분...",
  ui_story_5043_50431101_58_dialog_content = "심판관 여러분, 오늘 이 소동은 이 정도로 충분합니다. 더는 계속하고 싶지 않군요.",
  ui_story_5043_50431101_59_dialog_content = "하고 싶은 말이나 할 일이 있다면 개정 후에 하세요.",
  ui_story_5043_50431101_60_dialog_content = "왜죠? 그저 증거물을...",
  ui_story_5043_50431101_61_dialog_content = "제가 오늘은. 이 정도로. 됐다고. 하지 않았습니까.",
  ui_story_5043_50431101_62_dialog_content = "잠시 후 용의자를 구금실로 보낼 겁니다. 개정 전까지 일체의 면회를 금합니다.",
  ui_story_5043_50431101_63_dialog_content = "구금실?! 미쳤습니까?!",
  ui_story_5043_50431101_64_dialog_content = "적법하지 않은 구금은 위법이다. 너한테 그런 권한은 없잖아!",
  ui_story_5043_50431101_65_dialog_content = "연애 지부 심판소에서 「유죄」 판결을 내리는 건 제 권한이에요.",
  ui_story_5043_50431101_66_dialog_content = "용의자를 구금하는 것도 필요한 절차입니다만, 지금 심판소의 법률에 의문을 품는 건가요?",
  ui_story_5043_50431101_67_dialog_content = "큭...",
  ui_story_5043_50431101_68_dialog_content = "다, 다들 진정하세요!",
  ui_story_5043_50431101_69_dialog_content = "전 슈와브 대심판관님의 지시에 따를게요. 혐의는 개정한 뒤에 반박하면 되는 거잖아요.",
  ui_story_5043_50431101_70_dialog_content = "티나...",
  ui_story_5043_50431101_71_dialog_content = "전 심판관이에요.\n전 백야성의 사법제도가 결코 무고한 자를 억울하게 만들지 않을 거라 믿어요.",
  ui_story_5043_50431101_72_dialog_content = "내일 개정하고 나면 진상은 반드시 밝혀질 거예요.",
  ui_story_5043_50431101_73_dialog_content = "전 연애 심판소를 믿어요.",
  ui_story_5043_50431101_74_dialog_content = "그리고 여러분을 믿어요.",
  ui_story_5043_50431101_75_dialog_content = "......",
  ui_story_5043_50431101_76_dialog_content = "......",
  ui_story_5043_50431101_77_dialog_content = "경비병, 용의자를 데려가세요.",
  ui_story_5043_50431101_78_dialog_content = "예!",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>하이가든, 심판소 밖</color>",
  ui_story_5043_50431101_80_dialog_content = "어떡하지... 티나가 잡혀가다니...",
  ui_story_5043_50431101_81_dialog_content = "내일 재판에서 유죄 판결을 받는 건 아니겠지?",
  ui_story_5043_50431101_82_dialog_content = "이 상태로 개정한다면... 그렇게 될 겁니다.",
  ui_story_5043_50431101_83_dialog_content = "그, 그럴 순 없어! 티나는 무죄가 확실하잖아!",
  ui_story_5043_50431101_84_dialog_content = "그것보다... 슈와브 그 녀석... 뭔가 이상해 보이지 않았습니까?",
  ui_story_5043_50431101_85_dialog_content = "어?",
  ui_story_5043_50431101_86_dialog_content = "전부터 이상한 사람이라고는 생각하긴 했지만, 그러고 보니까...",
  ui_story_5043_50431101_87_dialog_content = "오늘 심판소에서의 태도는 확실히 좀 지나쳤어.",
  ui_story_5043_50431101_88_dialog_content = "그 녀석, 분명히 우리에게 적의를 가지고 있었다.",
  ui_story_5043_50431101_89_dialog_content = "티나에게 불리한 정보만 과장하고, 반박 의견은 전부 무시했지.",
  ui_story_5043_50431101_90_dialog_content = "네, 모든 전개가 너무 공교로웠습니다.",
  ui_story_5043_50431101_91_dialog_content = "이제 막 발생한 사건인데, 곧바로 증거물과 짝이 되는 장갑을\n부하들에게 찾도록 한 것도 그렇고 말입니다...",
  ui_story_5043_50431101_92_dialog_content = "마치 장갑이 어떤 디자인인지 처음부터 알고 있었던 것처럼 말이죠...",
  ui_story_5043_50431101_93_dialog_content = "게다가 현장의 상황도 잘 알고 있는 것 같았지.",
  ui_story_5043_50431101_94_dialog_content = "아까 자신하던 그 얄미운 표정, 너도 봤겠지?",
  ui_story_5043_50431101_95_dialog_content = "그런가요? 잘 생각해 보세요.",
  ui_story_5043_50431101_96_dialog_content = "사건이 일어나는 그 순간, 티나 심판관이 정말 당신들과 함께 싸우고 있었나요?",
  ui_story_5043_50431101_97_dialog_content = "현장에 가본 적도 없었으면서, 어떻게 그런 질문을 할 수 있지?",
  ui_story_5043_50431101_98_dialog_content = "맞아!",
  ui_story_5043_50431101_99_dialog_content = "확실히... 아까 티나를 용의자로 특정하는 과정은 이상할 정도로 순조로웠어.",
  ui_story_5043_50431101_100_dialog_content = "모든 정황이 순식간에 티나가 유죄라는 결론을 향해 전개됐어...",
  ui_story_5043_50431101_101_dialog_content = "하지만 가장 이상한 건 그런 추측들이 아니라...",
  ui_story_5043_50431101_102_dialog_content = "녀석의 마지막 조치였지.",
  ui_story_5043_50431101_103_dialog_content = "그렇습니다.",
  ui_story_5043_50431101_104_dialog_content = "장갑을 발견한 점이나, 현장의 상황을 알고 있던 점 같은 건\n운이 좋았다거나 수하를 많이 보냈다고 하면 설명이 되겠죠.",
  ui_story_5043_50431101_105_dialog_content = "증거를 제시하는 과정도 합리적이었고, 조금의 허점도 없었습니다.",
  ui_story_5043_50431101_106_dialog_content = "그래, 하지만 마지막엔 참지 못했던 거다.",
  ui_story_5043_50431101_107_dialog_content = "우리의 증거물 조사를 허락하지 않고, 티나를 강제로 구금해 버렸으니 말이야.",
  ui_story_5043_50431101_108_dialog_content = "그건 뭔가를 남에게 보이고 싶지 않았던 게 분명해.",
  ui_story_5043_50431101_109_dialog_content = "특히 우리한테 말이야.",
  ui_story_5043_50431101_110_dialog_content = "네, 규칙을 깨트려서라도 숨기고 싶은 단서가 있는 거겠죠.",
  ui_story_5043_50431101_111_dialog_content = "티나에게 죄를 덮어씌운 이유도 분명히 거기 숨겨져 있을 겁니다.",
  ui_story_5043_50431101_112_dialog_content = "우와! 굉장한 추리네!",
  ui_story_5043_50431101_113_dialog_content = "말조심해.",
  ui_story_5043_50431101_114_dialog_content = "여긴 심판소 입구라고.",
  ui_story_5043_50431101_115_dialog_content = "아, 그렇지. 조용히 해야지.",
  ui_story_5043_50431101_116_dialog_content = "...그럼 슈와브가 숨기고 있는 단서를 우리가 찾아내면 티나의 혐의를 벗길 수 있는 거지?",
  ui_story_5043_50431101_117_dialog_content = "확실히 그렇습니다만, 아마 찾을 수 없을 겁니다.",
  ui_story_5043_50431101_118_dialog_content = "뭐?",
  ui_story_5043_50431101_119_dialog_content = "슈와브는 반드시 개정 전까지 모든 증거를 인멸할 테니까요.",
  ui_story_5043_50431101_120_dialog_content = "그리고 그게 뭔지 녀석은 알지만, 우린 모르죠.",
  ui_story_5043_50431101_121_dialog_content = "게다가 동원할 수 있는 수단은 저쪽이 더 많습니다.",
  ui_story_5043_50431101_122_dialog_content = "이건 우리가 만회하기 어려운 열세입니다.",
  ui_story_5043_50431101_123_dialog_content = "그, 그럼 어떡해? 이대로 개정을 기다리는 수밖에 없는 거야?",
  ui_story_5043_50431101_124_dialog_content = "지금의 정보만으로 개정한다면, 티나는 유죄 판결을 받게 될 겁니다.",
  ui_story_5043_50431101_125_dialog_content = "반드시 개정 전까지 다른 단서를 수집해야 합니다.",
  ui_story_5043_50431101_126_dialog_content = "녀석이 숨기려는 핵심은 건드리지 않고, 대신 주변에서 단서가 될 만한 것들을 찾는 겁니다.",
  ui_story_5043_50431101_127_dialog_content = "하하하! 그거 재밌겠는데!",
  ui_story_5043_50431101_128_dialog_content = "이미 뭔가 생각이 있는 모양이지?",
  ui_story_5043_50431101_129_dialog_content = "너희들, 바보짓 하지 마.",
  ui_story_5043_50431101_130_dialog_content = "뢰베, 넌 융통성을 좀 가질 필요가 있어.",
  ui_story_5043_50431101_131_dialog_content = "난 다른 조사 업무가 많아서 같이 어울려 줄 수 없어.",
  ui_story_5043_50431101_132_dialog_content = "너희가 하려는 바보짓을 돕진 않을 거야. 대신 못 들은 걸로 해 줄게.",
  ui_story_5043_50431101_133_dialog_content = "쳇...",
  ui_story_5043_50431101_134_dialog_content = "괜찮아요. 인원이 많으면 오히려 번거로워질 뿐이니까요.",
  ui_story_5043_50431101_135_dialog_content = "그럼... 두 분, 잠깐 좀 가까이 와 주세요.",
  ui_story_5043_50431101_136_dialog_content = "응, 뭔데?",
  ui_story_5043_50431101_137_dialog_content = "슈와브는 비밀을 숨기기 위해 규칙을 깼습니다.",
  ui_story_5043_50431101_138_dialog_content = "그렇다면 우리도 규칙을 깨야 녀석을 이길 수 있습니다.",
  ui_story_5043_50431101_139_dialog_content = "어떻게?",
  ui_story_5043_50431101_140_dialog_content = "슈와브의 저택에 잠입할 겁니다.",
  ui_story_5043_50431101_141_dialog_content = "뭐?!",
  ui_story_5043_50431101_142_dialog_content = "증거물과 용의자 접촉이 허용되지 않는다면, 슈와브 본인을 노리는 수밖에 없습니다.",
  ui_story_5043_50431101_143_dialog_content = "자택은 비밀을 지킬 수 있는 가장 안전한 장소입니다.",
  ui_story_5043_50431101_144_dialog_content = "녀석이 다른 사람에게 말할 수 없는 비밀을 가지고 있다면,\n그 단서는 집에 있다고 생각하는 게 타당할 겁니다.",
  ui_story_5043_50431101_145_dialog_content = "근데... 그거 불법 아냐?",
  ui_story_5043_50431101_146_dialog_content = "재미있군! 정말 재미있겠어!",
  ui_story_5043_50431101_147_dialog_content = "좋아, 그 방법으로 하자고! 녀석의 장원을 보러 가는 거다!",
  ui_story_5043_50431101_148_dialog_content = "...여기 법을 지키는 사람은 나밖에 없는 건가...",
  ui_story_5043_50431101_149_dialog_content = "당신도 봤겠죠. 상대방의 불법 행위가 우릴 이 지경으로 몰아붙인 겁니다.",
  ui_story_5043_50431101_150_dialog_content = "전 모든 게 끝나고 나면 자진해서 주거침입죄에 대한 처벌을 받겠습니다.",
  ui_story_5043_50431101_151_dialog_content = "하지만 지금은 티나의 누명을 벗겨주는 게 가장 중요합니다.",
  ui_story_5043_50431101_152_dialog_content = "자진해서 처벌을 받겠다고?",
  ui_story_5043_50431101_153_dialog_content = "휴.. 너처럼 정직한 바보는 앞으로 손해만 보고 살 거다.",
  ui_story_5043_50431101_154_dialog_content = "응... 역시 가장 중요한 건 티나의 무죄겠지!",
  ui_story_5043_50431101_155_dialog_content = "그럼 지금 바로 출발할 거야?",
  ui_story_5043_50431101_156_dialog_content = "그 전에 할 일이 좀 있습니다.",
  ui_story_5043_50431101_157_dialog_content = "두 분은 눈치채셨는지 모르겠군요.\n조금 전부터 경비병들이 계속 우릴 따라오고 있었습니다.",
  ui_story_5043_50431101_158_dialog_content = "아마 슈와브 녀석의 짓이겠죠. 우리가 자유롭게 움직이게 놔두진 않을 겁니다.",
  ui_story_5043_50431101_159_dialog_content = "그럼 저 사람들부터 뿌리쳐야겠네?",
  ui_story_5043_50431101_160_dialog_content = "네, 지금 방법을 생각하는 중입니다.",
  ui_story_5043_50431101_161_dialog_content = "그거야 쉽지. 내가 제일 잘하는 게 도망치는 거거든.",
  ui_story_5043_50431101_162_dialog_content = "잊지 마. 나한텐 다른 「눈」이 있다는 거.",
  ui_story_5043_50431101_163_dialog_content = "아, 그렇죠! 아이테르의 감응 능력을 활용하면 되겠군요!",
  ui_story_5043_50431101_164_dialog_content = "정말 잘됐네요. 그럼 도주 전문가님, 우선 뭘 하면 됩니까?",
  ui_story_5043_50431101_165_dialog_content = "아주 간단해.",
  ui_story_5043_50431101_166_dialog_content = "도망의 첫 단계는 당연히...",
  ui_story_5043_50431101_167_dialog_content = "일단 뛰어!",
  ui_story_5043_50431102_1_dialog_content = "저 앞에서 오른쪽으로!",
  ui_story_5043_50431102_2_dialog_content = "크윽, 힘들단 말이다!",
  ui_story_5043_50431102_3_dialog_content = "어때? 아직도 따라오고 있나?",
  ui_story_5043_50431102_4_dialog_content = "경비병? 하나도 없는데?",
  ui_story_5043_50431102_5_dialog_content = "그럼 왜 아직도 계속 달리는 거야?!",
  ui_story_5043_50431102_6_dialog_content = "아, 슈와브네 집에 가야 한다며?",
  ui_story_5043_50431102_7_dialog_content = "지금 그쪽으로 가고 있는 거야.",
  ui_story_5043_50431102_8_dialog_content = "미행을 뿌리쳤으면 달릴 필요도 없잖아!",
  ui_story_5043_50431102_9_dialog_content = "게다가 네가 어떻게 슈와브 녀석 집을 아는 거지?",
  ui_story_5043_50431102_10_dialog_content = "아까 제가 알려드렸습니다.",
  ui_story_5043_50431102_11_dialog_content = "시간이 없습니다. 달리면 그만큼 빨리 도착하겠죠.",
  ui_story_5043_50431102_12_dialog_content = "그럼 적어도 놈들을 뿌리쳤다는 말 정도는 해줬어야지!\n계속 긴장한 채로 달리느라 힘들었다고!",
  ui_story_5043_50431102_13_dialog_content = "자, 자. 거의 다 왔습니다. 조용히 해 주세요.",
  ui_story_5043_50431102_14_dialog_content = "이 자식...",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>하이가든, 살라르 가문 장원 밖</color>",
  ui_story_5043_50431102_16_dialog_content = "입구에 호위병이랑 하인들이 꽤 있는 것 같아.",
  ui_story_5043_50431102_17_dialog_content = "저 사람들한테 들키지 않으면서 단서도 찾아야 한다니...",
  ui_story_5043_50431102_18_dialog_content = "네, 매우 위험한 계획입니다.",
  ui_story_5043_50431102_19_dialog_content = "만약 발각된다면, 내일 개정 때 우리도 피고석에 서게 될 테니까요.",
  ui_story_5043_50431102_20_dialog_content = "각오는 되셨습니까?",
  ui_story_5043_50431102_21_dialog_content = "티나의 누명을 벗길 수 있는 유일한 방법이잖아...",
  ui_story_5043_50431102_22_dialog_content = "위험해도 할 수밖에 없어!",
  ui_story_5043_50431102_23_dialog_content = "그나마 다행인 건 이 장원이 정말 넓다는 거지. 숨을 곳이라면 얼마든지 있다고.",
  ui_story_5043_50431102_24_dialog_content = "게다가 PlayerName의 감응 능력이라면 많은 위기를 피할 수 있을 거다.",
  ui_story_5043_50431102_25_dialog_content = "그래! 평소보다 훨씬 더 열심히 할게!",
  ui_story_5043_50431102_26_dialog_content = "근데 어떻게 들어가지?",
  ui_story_5043_50431102_27_dialog_content = "호위병 교대 시간을 기다릴 여유가 있을지 모르겠군...",
  ui_story_5043_50431102_28_dialog_content = "괜찮습니다. 정면으로 들어갈 건 아니니까요.",
  ui_story_5043_50431102_29_dialog_content = "음? 이 장원에 다른 문도 있는 거냐?",
  ui_story_5043_50431102_30_dialog_content = "보세요, 저쪽에 화원이 있습니다. 저긴 관목을 많이 심어 놔서 몸을 숨기기 좋겠죠.",
  ui_story_5043_50431102_31_dialog_content = "우린 화원 쪽 벽을 넘어서 들어갈 겁니다.",
  ui_story_5043_50431102_32_dialog_content = "벽을 넘어?!",
  ui_story_5043_50431102_33_dialog_content = "오! 확실히 저쪽이 좋을 것 같네. 벽도 별로 안 높잖아!",
  ui_story_5043_50431102_34_dialog_content = "자, 그럼 갑시다.",
  ui_story_5043_50431102_35_dialog_content = "응!",
  ui_story_5043_50431102_36_dialog_content = "어이, 기다려! 벽을 넘는다니, 그게 무슨 체통 없는 짓이냔 말이다!",
  ui_story_5043_50431102_37_dialog_content = "이 몸은 소이어 가문의 도련...",
  ui_story_5043_50431102_38_dialog_content = "휴, 됐다. 정말 못 말리는 서민들이란 말이지.",
  ui_story_5043_50431201_1_dialog_content = "아아... 왜 내가 이런 멍청한 짓을 해야 하는 거냐...",
  ui_story_5043_50431201_2_dialog_content = "티나의 누명을 벗기 위해서잖아, 조금만 참아.",
  ui_story_5043_50431201_3_dialog_content = "봐, 아무튼 이렇게 무사히 들어왔잖아.",
  ui_story_5043_50431201_4_dialog_content = "근데... 여기 정말 예쁜 곳이네.",
  ui_story_5043_50431201_5_dialog_content = "여기가 슈와브네 집이야?",
  ui_story_5043_50431201_6_dialog_content = "그렇습니다, 정말 부럽네요.",
  ui_story_5043_50431201_7_dialog_content = "살라르 가문은 백야성에서 상당한 영향력을 가지고 있으니까.",
  ui_story_5043_50431201_8_dialog_content = "이 장원도 살라르 가문의 재산 중 극히 일부일 뿐이라고.",
  ui_story_5043_50431201_9_dialog_content = "쉿! 조용히, 앞에 누가 있어요.",
  ui_story_5043_50431201_10_dialog_content = "가서 살펴봅시다.",
  ui_story_5043_50431201_11_dialog_content = "아! 나도 보여!",
  ui_story_5043_50431201_12_dialog_content = "저건... 슈와브?",
  ui_story_5043_50431201_13_dialog_content = "죄송합니다, 슈와브 님... 놈들을 놓쳤습니다.",
  ui_story_5043_50431201_14_dialog_content = "그 두 심판관과 아이테르는 생각보다 빠르게 도망쳤습니다.\n게다가 온갖 곳을 자꾸 돌아서 가는 바람에 따라잡을 수가 없었습니다.",
  ui_story_5043_50431201_15_dialog_content = "그렇게나 경비병을 보냈는데 놓쳤다는 건가?",
  ui_story_5043_50431201_16_dialog_content = "정말 쓸모없구나!",
  ui_story_5043_50431201_17_dialog_content = "죄송합니다!",
  ui_story_5043_50431201_18_dialog_content = "됐어, 그냥 넘어가자고.",
  ui_story_5043_50431201_19_dialog_content = "녀석들이 초조해지면 실수를 저지를 거다. 그럼 이쪽에 유리하게 작용하겠지.",
  ui_story_5043_50431201_20_dialog_content = "그만 돌아가라.",
  ui_story_5043_50431201_21_dialog_content = "예, 슈와브 님!",
  ui_story_5043_50431201_22_dialog_content = "역시 경비병을 보내서 우릴 감시하고 있었나. 흥, 뜻대로 될 줄 알고!",
  ui_story_5043_50431201_23_dialog_content = "잠입하자마자 슈와브를 찾아내서 정말 다행입니다.",
  ui_story_5043_50431201_24_dialog_content = "놓쳐선 안 됩니다. 녀석이 뭘 하려고 하는지 확인해야 합니다.",
  ui_story_5043_50431201_25_dialog_content = "어떤 이상한 행동을 하든지 모두 중요한 단서가 될 테니까요.",
  ui_story_5043_50431201_26_dialog_content = "응, 알겠어!",
  ui_story_5043_50431201_27_dialog_content = "하지만 방심해선 안 된다. 슈와브는 상식으로 이해할 수 없는 녀석이니까.",
  ui_story_5043_50431201_28_dialog_content = "심판소에서조차 당당하게 규칙을 깨트리는 녀석이라고.\n집에서는 더 무서운 일을 하고 있어도 이상하지 않겠지.",
  ui_story_5043_50431201_29_dialog_content = "...그, 그렇게 말하니까 좀 무서워졌잖아.",
  ui_story_5043_50431201_30_dialog_content = "두려움은 마음의 준비를 도울 수 있지.",
  ui_story_5043_50431201_31_dialog_content = "자, 가서 확인해 보자고.",
  ui_story_5043_50431201_32_dialog_content = "슈와브 님, 차를 가져왔습니다.",
  ui_story_5043_50431201_33_dialog_content = "그래, 거기 둬라.",
  ui_story_5043_50431201_34_dialog_content = "주방에서 다과를 만드는 중입니다. 바로 가져다드리겠습니다.",
  ui_story_5043_50431201_35_dialog_content = "필요 없어. 난 할 일이 있어.",
  ui_story_5043_50431201_36_dialog_content = "당분간은 방해하지 마.",
  ui_story_5043_50431201_37_dialog_content = "아, 알겠습니다!",
  ui_story_5043_50431201_38_dialog_content = "하인을 내보냈군요.",
  ui_story_5043_50431201_39_dialog_content = "흠... 그렇다면 지금부터 자기 사람들에게도 보이고 싶지 않은 일을 하려는 거겠지.",
  ui_story_5043_50431201_40_dialog_content = "...그냥 혼자 있고 싶은 건 아닐까?",
  ui_story_5043_50431201_41_dialog_content = "방심하지 마라, PlayerName.",
  ui_story_5043_50431201_42_dialog_content = "내가 한 말 잊었나? 슈와브는 상식으로 이해할 수 없는 녀석이다.",
  ui_story_5043_50431201_43_dialog_content = "그래그래, 알겠다니까.",
  ui_story_5043_50431201_44_dialog_content = "근데 아무리 그렇다 해도, 자기 집 화원에서 무슨 특별한 일을 할 수 있는데?",
  ui_story_5043_50431201_45_dialog_content = "보세요! 손을 들었습니다!",
  ui_story_5043_50431201_46_dialog_content = "손에 뭘 들고 있는 것 같은데요?",
  ui_story_5043_50431201_47_dialog_content = "바늘이다! 손에 바늘을 들고 있어!",
  ui_story_5043_50431201_48_dialog_content = "바늘?!",
  ui_story_5043_50431201_49_dialog_content = "뭘 하려는 거지? 자기 손이라도 찌르려는 건가?",
  ui_story_5043_50431201_50_dialog_content = "아뇨, 녀석이 찌르려고 하는 건...",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>푹──</color>",
  ui_story_5043_50431201_52_dialog_content = "손에 들고 있는 인형입니다...",
  ui_story_5043_50431201_53_dialog_content = "왜, 왜 인형을 찌르는 거지?",
  ui_story_5043_50431201_54_dialog_content = "...너희 혹시 인형을 쓰는 저주에 대해 알고 있냐?",
  ui_story_5043_50431201_55_dialog_content = "저주?",
  ui_story_5043_50431201_56_dialog_content = "먼저 상대방의 신체 일부... 보통은 혈액이나 머리카락이 되겠지.\n그걸 인형 속에 넣는 거다.",
  ui_story_5043_50431201_57_dialog_content = "그러면 인형은 그 상대방과 연결된다.",
  ui_story_5043_50431201_58_dialog_content = "그렇게 된 인형을 바늘로 찌르면 그 상대방에게 통증을 느끼게 하고,\n심지어 상처를 입힐 수도 있는 거다.",
  ui_story_5043_50431201_59_dialog_content = "그리고 끝내 고통스럽게 죽게 되는 거지.",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>푹──</color>",
  ui_story_5043_50431201_61_dialog_content = "큭, 또 찔렀군!",
  ui_story_5043_50431201_62_dialog_content = "그런 저주가 있다고 들은 적은 있습니다만,\n설마 녀석이 저런 음험한 면이 있을 줄이야...",
  ui_story_5043_50431201_63_dialog_content = "이상할 것도 없지. 녀석의 그 다정하고 상냥한 남자 이미지는 애초에 연기의 일부니까.",
  ui_story_5043_50431201_64_dialog_content = "그래도 인형으로 저주를 한다거나 그런 건 그냥 사람들을 겁주려는 거리의 전설 아닙니까?",
  ui_story_5043_50431201_65_dialog_content = "게다가 백야성의 교리에 따르면 그런 행위는...",
  ui_story_5043_50431201_66_dialog_content = "이해했어. 지금 중요한 건 저주가 진짜냐 아니냐가 아니라, 사람들이 그걸 믿느냐 마느냐야.",
  ui_story_5043_50431201_67_dialog_content = "그리고 슈와브는 그걸 믿고 있겠지.",
  ui_story_5043_50431201_68_dialog_content = "그러니까 지금 이 순간, 세상에는 슈와브가 원망하는 사람,\n죽이고 싶을 만큼 원망하는 사람이 있다는 거잖아...",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>푹──</color>",
  ui_story_5043_50431201_70_dialog_content = "저 녀석... 정말 죽일 작정일까요?!",
  ui_story_5043_50431201_71_dialog_content = "대체 누가 녀석에게 그렇게 큰 원망을 받고 있는 거지?\n죽음까지 바랄 정도의 원한이라니!",
  ui_story_5043_50431201_72_dialog_content = "음... 그건 확실히 생각해 볼 만한 문제네.",
  ui_story_5043_50431201_73_dialog_content = "저 녀석의 인생은 항상 화려하고 빛나서, 아무도 방해하거나 하지 않았을 것처럼 보이는데.",
  ui_story_5043_50431201_74_dialog_content = "아니면... 저 증오는 사람들이 알지 못하는 부분에서 비롯된 걸지도 몰라.",
  ui_story_5043_50431201_75_dialog_content = "아, 그렇게 말하니까 이제야 알 것 같군.",
  ui_story_5043_50431201_76_dialog_content = "녀석은 분명히 아무도 모르는, 잊을 수 없는 <color=#FFB400>연애</color> 경험이 있는 거다.",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>푹──</color>",
  ui_story_5043_50431201_78_dialog_content = "만약 그렇다면 저희도 가만히 있을 수 없습니다.\n지금 이건 사람 목숨이 걸린 사건입니다!",
  ui_story_5043_50431201_79_dialog_content = "충동적으로 굴지 마라. 실제로 범법 행위가 발생하기 전까진 우리도 손을 쓸 수 없다고.",
  ui_story_5043_50431201_80_dialog_content = "지금 우리가 뭘 할 수 있지? 인형을 찌르는 걸 막자는 거냐?",
  ui_story_5043_50431201_81_dialog_content = "잠깐만... 만약 그 전설이 진짜라면?",
  ui_story_5043_50431201_82_dialog_content = "인형으로 사람을 저주하는 것 말입니까?",
  ui_story_5043_50431201_83_dialog_content = "그래...",
  ui_story_5043_50431201_84_dialog_content = "만약 그 전설이 사실이라면, 우린 지금...",
  ui_story_5043_50431201_85_dialog_content = "「살인 사건」 현장을 보고 있는 거잖아...",
  ui_story_5043_50431201_86_dialog_content = "이걸로 마지막이다.",
  ui_story_5043_50431201_87_dialog_content = "자, 하나의 생명이 마침내...",
  ui_story_5043_50431201_88_dialog_content = "어서 막읍시다! 빨리!",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>푹──</color>",
  ui_story_5043_50431201_90_dialog_content = "탄생했다!",
  ui_story_5043_50431201_91_dialog_content = "아가야, 정말 귀엽구나.",
  ui_story_5043_50431201_92_dialog_content = "이름을 지어 주는 게 좋겠어... 그래... 「밤톨이」로 하자!",
  ui_story_5043_50431201_93_dialog_content = "저건... 고슴도치 인형인가?",
  ui_story_5043_50431201_94_dialog_content = "네, 확실히 고슴도치처럼 보이는군요.",
  ui_story_5043_50431201_95_dialog_content = "진짜 밤처럼 생기긴 했네. 이름 좀 지을 줄 아는 녀석이군.",
  ui_story_5043_50431201_96_dialog_content = "<size=45>그럼 방금 전까지 우린 왜 긴장한 건데에에!</size>",
  ui_story_5043_50431201_97_dialog_content = "쉿! 조용히 해라, PlayerName.",
  ui_story_5043_50431201_98_dialog_content = "휴, 정말 바보같네... 누군가를 저주로 죽인다는 얘길 진지하게 생각하고 있었다니...",
  ui_story_5043_50431201_99_dialog_content = "크흠... 사건 조사 중에는 늘 시행착오를 겪기 마련입니다.",
  ui_story_5043_50431201_100_dialog_content = "모든 가능성에 신중하게 대처해 나가야만 진상을 맞이할 준비를 할 수 있는 겁니다.",
  ui_story_5043_50431201_101_dialog_content = "그런 진지한 이유로 자길 설득할 수 있는 거냐고...",
  ui_story_5043_50431201_102_dialog_content = "자, 방금 일은 잊고 티나를 생각합시다.",
  ui_story_5043_50431201_103_dialog_content = "슈와브가 안으로 들어가려고 합니다. 내일 재판 준비를 하려는 건지도 모릅니다.",
  ui_story_5043_50431201_104_dialog_content = "어서 따라갑시다.",
  ui_story_5043_50431201_105_dialog_content = "휴, 실험은 아직 끝나지 않았어. 오늘은 진전이 좀 있었으면 좋겠는데...",
  ui_story_5043_50431201_106_dialog_content = "들었어? 방금 「실험」이라고 했지?",
  ui_story_5043_50431201_107_dialog_content = "네, 대체 무슨 연구를 하고 있는 걸까요?",
  ui_story_5043_50431201_108_dialog_content = "흥, 좋은 일이 아닐 게 뻔해. 상식으로 이해할 수 없는 녀석이니까.",
  ui_story_5043_50431201_109_dialog_content = "또 시작이네. 「상식으로 이해할 수 없는 녀석」.",
  ui_story_5043_50431201_110_dialog_content = "방금 일 잊었어? 이번엔 선입견을 버리고 관찰해 보자.",
  ui_story_5043_50431201_111_dialog_content = "그냥 실험일 뿐이잖아. 무슨 취미 같은 걸지도 몰라...",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5043_50431201_113_dialog_content = "으아악!",
  ui_story_5043_50431201_114_dialog_content = "폭발? 대체 뭘 하고 있는 거지?!",
  ui_story_5043_50431201_115_dialog_content = "모, 모르겠어. 가까이 가 볼까?",
  ui_story_5043_50431201_116_dialog_content = "안 됩니다! 들어가면 숨을 곳이 없을지도 모릅니다.",
  ui_story_5043_50431201_117_dialog_content = "더 가까이 다가가면 들키고 말 겁니다...",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5043_50431201_119_dialog_content = "또 폭발했어! 저 녀석, 아무래도 폭약을 연구하고 있는 것 같군!",
  ui_story_5043_50431201_120_dialog_content = "폭약?! 그건 좀 비약이 심한 거 아닌가...",
  ui_story_5043_50431201_121_dialog_content = "아니! 폭약이 바로 살라르 가문의 가업이란 말이다!",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5043_50431201_123_dialog_content = "근데 폭약 같은 걸 연구해서 어디 쓰는데?",
  ui_story_5043_50431201_124_dialog_content = "백야성처럼 아름답고 정교하게 만들어진 거리일수록 폭약 같은 힘의 파괴에 취약합니다.",
  ui_story_5043_50431201_125_dialog_content = "생각해 보세요. 고작 조각상 하나 훼손된 것만으로 재판이 열립니다.",
  ui_story_5043_50431201_126_dialog_content = "만약 종탑이나 교회가 파괴되기라도 한다면, 엄청난 소동이 벌어질 겁니다.",
  ui_story_5043_50431201_127_dialog_content = "혹시라도 나쁜 뜻을 품은 자가 폭약을 손에 넣기라도 한다면,\n저들은 파괴에 대한 사람들의 두려움을 자신의 계획에 이용하겠죠.",
  ui_story_5043_50431201_128_dialog_content = "근데 저렇게 적은 양으로 뭘 할 수 있는데? 자기 집 하나도 못 날려버릴 정도잖아.",
  ui_story_5043_50431201_129_dialog_content = "그러니 지금은 그저 「실험」일 뿐인 겁니다.",
  ui_story_5043_50431201_130_dialog_content = "녀석이 원리를 이해하고 나면, 루미나틱스로 폭발의 위력을\n수십 배, 수백 배로 늘릴 수도 있습니다.",
  ui_story_5043_50431201_131_dialog_content = "저 연구 하나만으로도 슈와브는 지금의 백야성 사회를 완전히 바꿀 수 있을 겁니다.",
  ui_story_5043_50431201_132_dialog_content = "심지어 백야성의 통치를 전복시킬 수 있다고 해도 과언이 아닙니다...",
  ui_story_5043_50431201_133_dialog_content = "그, 그렇게 큰일이라고?!",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5043_50431201_135_dialog_content = "콜록, 콜록콜록...",
  ui_story_5043_50431201_136_dialog_content = "역시 안 되는 건가.",
  ui_story_5043_50431201_137_dialog_content = "「<color=#FFB400>캐러멜 푸딩</color>」을 만드는 게 이렇게 힘들 줄이야.",
  ui_story_5043_50431201_138_dialog_content = "......",
  ui_story_5043_50431201_139_dialog_content = "캐러멜... 푸딩으로... 백야성 통치를 전복시켜?",
  ui_story_5043_50431201_140_dialog_content = "저, 저놈 바보 아냐?! 간식 하나 만드는 데 저런 폭발음이 난다고?!",
  ui_story_5043_50431201_141_dialog_content = "당신들 추측도 똑같이 터무니없었잖아!",
  ui_story_5043_50431201_142_dialog_content = "쉿, 녀석이 나온다. 얼른 숨어.",
  ui_story_5043_50431201_143_dialog_content = "휴, 또 쓸데없이 시간을 낭비했잖아.",
  ui_story_5043_50431201_144_dialog_content = "역시 해야 할 일부터 해야겠어. 지하실 열쇠가 어디 있더라... 아, 찾았다.",
  ui_story_5043_50431201_145_dialog_content = "개정 전에 다시 한번 확인해 둬야겠어...",
  ui_story_5043_50431201_146_dialog_content = "슈와브 님, 저녁 식사 시간입니다.",
  ui_story_5043_50431201_147_dialog_content = "...내가 방해하지 말라고 했을 텐데.",
  ui_story_5043_50431201_148_dialog_content = "죄송합니다! 하지만... 저녁식사 준비가 끝났다고 말씀드려야 할 것 같아서...",
  ui_story_5043_50431201_149_dialog_content = "휴... 알겠어, 식사부터 하지. 안내하도록.",
  ui_story_5043_50431201_150_dialog_content = "슈와브가 식사하러 갔습니다. 식당 쪽은 하인이 많으니 미행은 잠시 멈춰야겠군요.",
  ui_story_5043_50431201_151_dialog_content = "너희들, 녀석이 가기 전에 뭐라고 했는지 들었어?",
  ui_story_5043_50431201_152_dialog_content = "또 상식으로 이해할 수 없는 녀석이라고 하려는 건 아니지?",
  ui_story_5043_50431201_153_dialog_content = "그 얘긴 일단 됐고, 저 녀석 방금 지하실 얘길 꺼냈잖아.",
  ui_story_5043_50431201_154_dialog_content = "방금 상황을 되짚어 봐...\n녀석이 열쇠를 꺼내 안으로 들어가려는 순간 하인이 녀석을 불렀어.",
  ui_story_5043_50431201_155_dialog_content = "봐, 저기 문에 열쇠가 그대로 꽂혀 있잖아.",
  ui_story_5043_50431201_156_dialog_content = "들어가 보고 싶지 않아? 저 안에 분명히 많은 비밀이 숨어 있을 거라고!",
  ui_story_5043_50431201_157_dialog_content = "확실히 다시는 없을 기회긴 한데...",
  ui_story_5043_50431201_158_dialog_content = "지금까지 티나에 관한 단서는 하나도 없었어.\n게다가 지하실에 들어갔다가 우리 계획이 틀어지면?",
  ui_story_5043_50431201_159_dialog_content = "티나가 무죄라면 문제는 반드시 슈와브에게 있을 겁니다.",
  ui_story_5043_50431201_160_dialog_content = "설령 녀석이 누군가에게 이용당한 거라 해도, 녀석에게 뭔가 단서가 남아 있겠죠.",
  ui_story_5043_50431201_161_dialog_content = "아직 발견하지 못한 건 우리가 더 깊게 찾지 못했기 때문입니다.",
  ui_story_5043_50431201_162_dialog_content = "...그것도 그래. 여기까지 와서 물러설 순 없어. 자, 들어가 보자.",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5043_50431201_164_dialog_content = "으앗! 엄청 어둡네! 아무것도 안 보이잖아!",
  ui_story_5043_50431201_165_dialog_content = "앞쪽에 내려가는 계단이 있는 것 같습니다. 주변을 더듬어서 내려가 봅시다...",
  ui_story_5043_50431201_166_dialog_content = "티나? 티나! 거기 있습니까?",
  ui_story_5043_50431201_167_dialog_content = "참, PlayerName 넌 감응 능력이 있잖아.",
  ui_story_5043_50431201_168_dialog_content = "네 능력으로 안쪽 상황을 조사해 보라고.",
  ui_story_5043_50431201_169_dialog_content = "응, 한번 해볼게.",
  ui_story_5043_50431201_170_option_content = "(강제 감응!)",
  ui_story_5043_50431201_171_dialog_content = "역시 아이테르가 있으니 꽤 편리하군.",
  ui_story_5043_50431201_172_dialog_content = "어때? 뭘 좀 찾았나?",
  ui_story_5043_50431201_173_dialog_content = "일단 불을 켤 촛불 같은 게 벽에 있는지부터 좀 찾아봐라.",
  ui_story_5043_50431201_174_dialog_content = "이 지하실, 꽤 깊은 모양이야...",
  ui_story_5043_50431201_175_dialog_content = "어? 뭔가 이쪽으로 오는 것 같아.",
  ui_story_5043_50431201_176_dialog_content = "이건...",
  ui_story_5043_50431201_177_dialog_content = "그어어──",
  ui_story_5043_50431201_178_dialog_content = "으아아아아악!",
  ui_story_5043_50431201_179_dialog_content = "왜 그래? 뭘 본 거냐?",
  ui_story_5043_50431201_180_dialog_content = "빠, 빨리 뒤로 도망쳐!",
  ui_story_5043_50431201_181_dialog_content = "암귀 무리가 올라오고 있어!",
  ui_story_5043_50431202_1_dialog_content = "그어어...",
  ui_story_5043_50431202_2_dialog_content = "대체 왜 여기 암귀가 있는 거지? 으, 최악이군!",
  ui_story_5043_50431202_3_dialog_content = "귀족의 저택엔 장식품도 모자라서 암귀도 있는 거였습니까?",
  ui_story_5043_50431202_4_dialog_content = "귀족을 모욕하지 마라! 우리 집엔 저런 역겨운 괴물 같은 건 없다고!",
  ui_story_5043_50431202_5_dialog_content = "빨리 뛰어! 또 덤벼들 거야!",
  ui_story_5043_50431202_6_dialog_content = "두 분 먼저 밖으로 도망치세요! 제가 암귀를 막겠습니다!",
  ui_story_5043_50431202_7_dialog_content = "괘, 괜찮겠어?",
  ui_story_5043_50431202_8_dialog_content = "백야성 심판관을 얕보면 안 됩니다.",
  ui_story_5043_50431202_9_dialog_content = "암귀들, 받아라...!",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>쨍그랑──!</color>",
  ui_story_5043_50431202_11_dialog_content = "어이쿠! 샹들리에가 깨졌잖아!",
  ui_story_5043_50431202_12_dialog_content = "북방의 수정으로 만든 것 같은데? 꽤 비싸 보이네.",
  ui_story_5043_50431202_13_dialog_content = "설마 저보고 변상하라고 하진 않겠죠...",
  ui_story_5043_50431202_14_dialog_content = "변상이고 뭐고 적부터 조심해!",
  ui_story_5043_50431202_15_dialog_content = "또인가...",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>콰지직──!</color>",
  ui_story_5043_50431202_17_dialog_content = "끝내주는군! 이번엔 티테이블인가!",
  ui_story_5043_50431202_18_dialog_content = "참으로 정교하게 만들어진 테이블이었는데, 쯧쯧. 슈와브가 속이 많이 타겠어.",
  ui_story_5043_50431202_19_dialog_content = "정말 죄송합니다. 하지만 변상의 주된 책임소재는 저한테 있지 않을 텐데요...",
  ui_story_5043_50431202_20_dialog_content = "됐으니까 조용히 좀 해! 조금만 더 가면 문이야!",
  ui_story_5043_50431202_21_dialog_content = "빨리 나가자고!",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>10분 후</color>",
  ui_story_5043_50431202_23_dialog_content = "슈와브 님, 저택 곳곳을 수색했지만 외부인의 흔적은 없었습니다.",
  ui_story_5043_50431202_24_dialog_content = "이 난장판은 대체... 어떻게 된 일인지...",
  ui_story_5043_50431202_25_dialog_content = "...침입자가 없었던 게 확실한가?",
  ui_story_5043_50431202_26_dialog_content = "예, 현재 상황에서는 그렇습니다.",
  ui_story_5043_50431202_27_dialog_content = "물론 침입자의 솜씨가 좋아 아무런 흔적도 남기지 않았을 가능성도 있습니다만...",
  ui_story_5043_50431202_28_dialog_content = "아니면... 심판소에 피해 신고를 하고 조사를 요청할까요?",
  ui_story_5043_50431202_29_dialog_content = "슈와브 님의 사건이라면 분명히 중요 사건으로 조사가 이루어질 겁니다!",
  ui_story_5043_50431202_30_dialog_content = "피해 신고라...",
  ui_story_5043_50431202_31_dialog_content = "아니, 그럴 필요 없어.",
  ui_story_5043_50431202_32_dialog_content = "있으나 마나 한 가구 몇 개일 뿐이야. 새로 사면 그만이지.",
  ui_story_5043_50431202_33_dialog_content = "사람을 불러서 깨끗하게 치우도록 해.",
  ui_story_5043_50431202_34_dialog_content = "예!",
  ui_story_5043_50431202_35_dialog_content = "(지하실 문이 열려 있었어...)",
  ui_story_5043_50431202_36_dialog_content = "(식사 전에 내가 열어두고 갔었나?)",
  ui_story_5043_50431202_37_dialog_content = "(말도 안 돼. 내가 이런 실수를 저지르다니.)",
  ui_story_5043_50431202_38_dialog_content = "(오늘은 일찍 쉬는 게 좋겠어. 개정일엔 맑은 정신을 유지해야 해.)",
  ui_story_5043_50431202_39_dialog_content = "아이고, 이게 웬 난리야...",
  ui_story_5043_50431202_40_dialog_content = "비싼 샹들리에랑 티테이블이 다 부서져 버렸네.",
  ui_story_5043_50431202_41_dialog_content = "이런 조각만 해도... 엄청 비싸겠지.",
  ui_story_5043_50431202_42_dialog_content = "후... 휴우...",
  ui_story_5043_50431202_43_dialog_content = "(드디어... 도망쳤다!)",
  ui_story_5043_50431202_44_dialog_content = "어때, 추격자는 없나?",
  ui_story_5043_50431202_45_dialog_content = "없어, 이젠 안전해.",
  ui_story_5043_50431202_46_dialog_content = "쳇, 이게 무슨 낭패냐. 오늘은 정말 재수도 없군.",
  ui_story_5043_50431202_47_dialog_content = "게다가 티나는커녕 쓸만한 단서 하나조차 못 찾았어.",
  ui_story_5043_50431202_48_dialog_content = "이제 내일 심판소에서 티나의 누명을 어떻게 벗기지...?",
  ui_story_5043_50431202_49_dialog_content = "해야 할 일은 이미 다 했습니다. 남은 건 심판관으로서의 책무를 끝까지 다하는 겁니다.",
  ui_story_5043_50431202_50_dialog_content = "개정 전까지 오늘 있었던 일을 자세히 검토해 보도록 하겠습니다.",
  ui_story_5043_50431202_51_dialog_content = "상황을 역전시킬 단서는 분명히 사소한 일 속에 숨어 있을 겁니다.",
  ui_story_5043_50431202_52_dialog_content = "직무야 물론 너나 나나 최선을 다해야겠지. 하지만...",
  ui_story_5043_50431202_53_dialog_content = "결정적인 단서가 없는 이상, 우리 손엔 비장의 카드가 없는 거나 마찬가지라고.",
  ui_story_5043_50431202_54_dialog_content = "반면에 슈와브 녀석이 쥐고 있는 비장의 카드가 뭔지 우린 전혀 모르잖아.",
  ui_story_5043_50431202_55_dialog_content = "이대로 심판소에서 녀석과 맞서는 건 도저히 안심이 되질 않는단 말이지.",
  ui_story_5043_50431202_56_dialog_content = "꼭 좋은 패를 가진 사람이 카드 게임에서 이기는 건 아닙니다.",
  ui_story_5043_50431202_57_dialog_content = "비장의 카드가 없다면 손기술로 보완하면 되는 겁니다.",
  ui_story_5043_50431202_58_dialog_content = "호오, 이런 상황에서 꽤 자신감이 넘치잖아?",
  ui_story_5043_50431202_59_dialog_content = "제가 믿는 건 진실입니다.",
  ui_story_5043_50431202_60_dialog_content = "한쪽은 진실을 숨기려 하고, 다른 한쪽은 진실을 밝히려 하죠.\n그 본질에서 우린 이미 우세합니다.",
  ui_story_5043_50431202_61_dialog_content = "게다가 슈와브 가문에 침입한 게 아무 수확도 없었던 건 아닙니다...",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5043_50431301_2_dialog_content = "(드디어...)",
  ui_story_5043_50431301_3_dialog_content = "(「목 없는 조각상 연쇄 사건」의 재판이 곧 개정된다.)",
  ui_story_5043_50431301_4_dialog_content = "(레인 씨, 마티외 씨, 그리고 티나... 과연 재판에서 진실을 밝힐 수 있을까...)",
  ui_story_5043_50431301_5_dialog_content = "PlayerName!",
  ui_story_5043_50431301_6_dialog_content = "아, 카렌! 뢰베도 왔네!",
  ui_story_5043_50431301_7_dialog_content = "돌아왔구나!",
  ui_story_5043_50431301_8_dialog_content = "응, 말했잖아. 개정일까진 돌아오겠다고.",
  ui_story_5043_50431301_9_dialog_content = "그런데...",
  ui_story_5043_50431301_10_dialog_content = "티나가 피고가 됐다면서?",
  ui_story_5043_50431301_11_dialog_content = "마티외, 너 정말 대단하네.",
  ui_story_5043_50431301_12_dialog_content = "뭐야? 무슨 뜻이야?!",
  ui_story_5043_50431301_13_dialog_content = "화, 확실히 그렇게 된 건 맞아.",
  ui_story_5043_50431301_14_dialog_content = "이상한 증거물 때문에 티나가 용의자가 돼 버렸어.",
  ui_story_5043_50431301_15_dialog_content = "하지만 재판 중에 분명히 뒤집을 기회가 있을 거야!",
  ui_story_5043_50431301_16_dialog_content = "이틀 동안 대체 무슨 일이 있었던 거야?",
  ui_story_5043_50431301_17_dialog_content = "자세한 건 안에 들어가서 얘기해 줄게.",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>하이가든, 심판소 연애 지부</color>",
  ui_story_5043_50431301_19_dialog_content = "정숙, 정숙하세요!",
  ui_story_5043_50431301_20_dialog_content = "여러분, 이번 사건 때문에 여러 차례 재판에 참여하시느라 이제 지겨우시겠지요.",
  ui_story_5043_50431301_21_dialog_content = "애석하게도 우린 범인의 거듭되는 악행을 막아내지 못했습니다.",
  ui_story_5043_50431301_22_dialog_content = "하지만 다행히 우리는 오늘 그 죄악에 종지부를 찍을 수 있게 되었습니다.",
  ui_story_5043_50431301_23_dialog_content = "그럼, 이제 선언하겠습니다...",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5043_50431301_25_dialog_content = "지금부터 「목 없는 조각상 연쇄 사건」의 재판을 시작하겠습니다!",
  ui_story_5043_50431301_26_dialog_content = "......",
  ui_story_5043_50431301_27_dialog_content = "......",
  ui_story_5043_50431301_28_dialog_content = "<size=30>티나, 레인 씨, 마티외 씨...</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>저들을 믿어. 우리가 할 수 있는 건 그것뿐이야.</size>",
  ui_story_5043_50431301_30_dialog_content = "우선 소송 당사자와 기타 증인의 정보를 확인하겠습니다!",
  ui_story_5043_50431301_31_dialog_content = "원고, 바이런 씨.",
  ui_story_5043_50431301_32_dialog_content = "피고, 티나 캠벨.",
  ui_story_5043_50431301_33_dialog_content = "아아, 정말 유감입니다. 연애 심판소의 심판관이 피고석에 서게 되다니 말이지요.",
  ui_story_5043_50431301_34_dialog_content = "저 녀석...",
  ui_story_5043_50431301_35_dialog_content = "본 재판은 저 슈와브 살라르가 대심판관을 맡습니다.",
  ui_story_5043_50431301_36_dialog_content = "심판관으로는 마티외 소이어, 레인,\n그리고 존경하는 배심원단이 합의체를 구성하여 재판을 진행합니다.",
  ui_story_5043_50431301_37_dialog_content = "젊은이가 드디어 존경을 배운 모양이군.",
  ui_story_5043_50431301_38_dialog_content = "우리처럼 경험 많은 배심원들은 사건 심리에 큰 도움을 준단 말이다.",
  ui_story_5043_50431301_39_dialog_content = "그대들은 이 사건에 대해 어떤 견해를 가지고 있지?",
  ui_story_5043_50431301_40_dialog_content = "......",
  ui_story_5043_50431301_41_dialog_content = "......",
  ui_story_5043_50431301_42_dialog_content = "아, 그렇지. 지금은 침묵해야 할 시간이군.",
  ui_story_5043_50431301_43_dialog_content = "본 사건의 개요는 여러분께 나눠드린 자료에 적혀 있습니다. 언제든지 살펴보세요.",
  ui_story_5043_50431301_44_dialog_content = "충분한 조사가 이루어졌기 때문에 사건의 경위는 이미 명확합니다.",
  ui_story_5043_50431301_45_dialog_content = "그럼 지금부터 「목 없는 조각상 연쇄 사건」의 조사 결과를\n제가 간단하게 말씀드리겠습니다.",
  ui_story_5043_50431301_46_dialog_content = "피고 티나 캠벨은 자유연애 풍조에 불만을 품고 조각상을 파괴함으로써\n그 불만을 표출하려 했습니다.",
  ui_story_5043_50431301_47_dialog_content = "처음 두 사건에서는 심판관이라는 신분을 이용해 증거를 인멸하였기에,\n범행의 흔적을 남기지 않았습니다.",
  ui_story_5043_50431301_48_dialog_content = "하지만 3차 범행 때는 바이런 씨의 즉각적인 신고 덕분에\n레인 심판관도 사전에 준비할 수 있었습니다.",
  ui_story_5043_50431301_49_dialog_content = "3차 범행 현장에서 레인 심판관은 범인의 손에서 핵심 증거물을 취득하였으며...",
  ui_story_5043_50431301_50_dialog_content = "이 장갑이 바로 그것입니다.",
  ui_story_5043_50431301_51_dialog_content = "훌륭하다! 이는 범인을 가리키는 결정적 단서로군!",
  ui_story_5043_50431301_52_dialog_content = "그렇습니다. 그래서 전 바로 부하를 보내 조사하도록 했고,\n피고의 책상 서랍에서 나머지 한 짝의 장갑을 발견했습니다.",
  ui_story_5043_50431301_53_dialog_content = "틀림없는 한 쌍이다!",
  ui_story_5043_50431301_54_dialog_content = "분석 결과 이 두 장갑은 명백히 한 쌍이며, 동일한 주인에게 속하는 것으로 판명되었습니다.",
  ui_story_5043_50431301_55_dialog_content = "그 주인이 바로 지금 피고석에 앉아 있는 티나 캠벨 양입니다.",
  ui_story_5043_50431301_56_dialog_content = "아니에요...",
  ui_story_5043_50431301_X56_dialog_content = "대단하군! 슈와브 대심판관, 역시 재능이 뛰어난 젊은이로다!",
  ui_story_5043_50431301_57_dialog_content = "이 반박할 수 없는 증거를 토대로, 본 심판소는 피고를\n「공용물건손상죄 및 연애방해죄」로 기소합니다.",
  ui_story_5043_50431301_58_dialog_content = "물론, 지금부터 피고는 변론하셔도 됩니다.",
  ui_story_5043_50431301_59_dialog_content = "그리고 눈물을 흘리며 호소하는 연기가 배심원들의 마음을 흔들어서,\n배심원들이 무죄의 표를 던져주길 기도하시죠.",
  ui_story_5043_50431301_60_dialog_content = "당신...",
  ui_story_5043_50431301_61_dialog_content = "있을 수 없는 일이다!",
  ui_story_5043_50431301_62_dialog_content = "이 자리에 앉은 이상, 우리가 따라야 할 원칙은 단 하나! 바로 공정이다!",
  ui_story_5043_50431301_63_dialog_content = "내 말이 맞지 않은가? 배심원 여러분.",
  ui_story_5043_50431301_64_dialog_content = "......",
  ui_story_5043_50431301_65_dialog_content = "......",
  ui_story_5043_50431301_66_dialog_content = "증거물인 장갑에 대해선 저도 뭐라고 말씀드려야 할지 모르겠어요...",
  ui_story_5043_50431301_67_dialog_content = "그건 확실히 제 거예요. 하지만 제가 사건 현장에 그걸 가지고 가진 않았어요.",
  ui_story_5043_50431301_68_dialog_content = "그때 전 암귀와 싸우고 있었고, 조각상에 접근할 수 없었어요.",
  ui_story_5043_50431301_69_dialog_content = "현장에 도착해서 조각상을 보았을 땐 이미 범인의 손에 부서진 뒤였죠...",
  ui_story_5043_50431301_70_dialog_content = "그걸 증명할 수 있는 사람이 있습니까?",
  ui_story_5043_50431301_71_dialog_content = "그건...",
  ui_story_5043_50431301_72_dialog_content = "죄송해요. 그때 전 일행과 따로 움직이고 있어서, 그걸 증명할 사람은 없어요...",
  ui_story_5043_50431301_73_dialog_content = "그렇다면 당신의 변론은 현재의 결론을 뒤집기엔 부족하군요.",
  ui_story_5043_50431301_74_dialog_content = "그 이상의 증거를 제시할 수 없다면, 당신을 「공용물건손상죄 및 연애방해죄」로...",
  ui_story_5043_50431301_75_dialog_content = "<size=45>잠깐!!!</size>",
  ui_story_5043_50431301_76_dialog_content = "...마티외 심판관?",
  ui_story_5043_50431301_77_dialog_content = "슈와브 대심판관의 판결에 이의를 제기합니다!",
  ui_story_5043_50431301_78_dialog_content = "피고는 「목 없는 조각상 연쇄 사건」의 범인이 아닙니다. 현장 부재를 증명할 수 있습니다!",
  ui_story_5043_50431301_79_dialog_content = "호오, 알리바이 말입니까?",
  ui_story_5043_50431301_80_dialog_content = "마티외 심판관, 자세히 말씀해 주세요.",
  ui_story_5043_50431301_81_dialog_content = "대신 객관적이고 이성적으로 진술하는 게 좋을 겁니다.",
  ui_story_5043_50431301_82_dialog_content = "그렇지 않으면 전 이 사건에 공범이 있을 가능성을 의심할 테니까요.",
  ui_story_5043_50431301_83_dialog_content = "크흠. 우선 사건의 시작으로 돌아가죠.",
  ui_story_5043_50431301_84_dialog_content = "첫 번째 「목 없는 조각상 사건」이 일어났을 때였습니다.",
  ui_story_5043_50431301_85_dialog_content = "그날 범인의 동향에 대해서는 제가 이미 조사했습니다만.",
  ui_story_5043_50431301_86_dialog_content = "유감스럽게도 피고의 알리바이가 입증되지 않습니다.",
  ui_story_5043_50431301_87_dialog_content = "중요한 건 사건 발생 당시가 아니라 사건 발생 후입니다!",
  ui_story_5043_50431301_88_dialog_content = "그날 오후 피고는 심판소에서 저와 함께 4시간 동안 일을 하고 있었습니다.",
  ui_story_5043_50431301_89_dialog_content = "이 점에 대해선 저뿐만 아니라 다른 동료들도 증명할 수 있습니다.",
  ui_story_5043_50431301_90_dialog_content = "좋습니다. 4시간 동안 일을 했군요. 그래서요?",
  ui_story_5043_50431301_91_dialog_content = "범행 후에 심판소로 돌아와 일을 하는 건 얼마든지 가능했던 일입니다.",
  ui_story_5043_50431301_92_dialog_content = "틀렸습니다! 이 4시간이라는 것 자체가 바로 알리바이입니다!",
  ui_story_5043_50431301_93_dialog_content = "피고가 「기면증」을 앓고 있다는 건 백야성의 주요 병원들이 증명 가능한 사실입니다.",
  ui_story_5043_50431301_94_dialog_content = "피고가 하루 동안 깨어 있을 수 있는 시간은 단 4시간뿐이란 말입니다!",
  ui_story_5043_50431301_95_dialog_content = "......",
  ui_story_5043_50431301_96_dialog_content = "그러니까 지금 증명한 4시간의 업무 시간을 제외하면,\n나머지 모든 시간 동안 피고는 자고 있었다는 것이 됩니다!",
  ui_story_5043_50431301_97_dialog_content = "따라서 피고가 첫 번째 조각상을 파괴하는 것은 불가능합니다!",
  ui_story_5043_50431301_98_dialog_content = "지금 업무 시간에 잠을 잤다는 말이냐?!",
  ui_story_5043_50431301_99_dialog_content = "이 얼마나 파렴치한가! 이제 월급을 그렇게 쉽게 받을 수 있는 시대가 되었단 말인가!",
  ui_story_5043_50431301_100_dialog_content = "아... 맞아요! 전 그때 자고 있었어요!",
  ui_story_5043_50431301_101_dialog_content = "일어난 뒤에야 「목 없는 조각상 사건」에 대해 들었어요.",
  ui_story_5043_50431301_102_dialog_content = "어떻습니까! 이것으로 현장부재가 증명되지 않습니까?",
  ui_story_5043_50431301_103_dialog_content = "극도로 허술한 변론입니다!",
  ui_story_5043_50431301_104_dialog_content = "「추측」으로 알리바이를 만들다니요.\n심판관이 「추측」에 근거해 판결을 내린단 말입니까!",
  ui_story_5043_50431301_105_dialog_content = "사건 발생 당시의 증인이든, 물증이든 상관없습니다. 어느 하나라도 제시할 수 있다면...",
  ui_story_5043_50431301_106_dialog_content = "알겠습니다! 대심판관님께서는 증거를 요구하시는군요.",
  ui_story_5043_50431301_107_dialog_content = "그렇다면 두 번째 「목 없는 조각상 사건」을 살펴봅시다.",
  ui_story_5043_50431301_108_dialog_content = "두 번째 사건에서도 피고에겐 마찬가지로 알리바이가 있습니다.",
  ui_story_5043_50431301_109_dialog_content = "저와 레인 모두 이를 증언할 수 있습니다.",
  ui_story_5043_50431301_110_dialog_content = "훗, 증인일지 공범일지는 아직 모르는 것 아닙니까?",
  ui_story_5043_50431301_111_dialog_content = "이런 이런, 아무래도 대심판관님께서는 직속 부하 심판관을 믿지 못하시는 것 같군요.",
  ui_story_5043_50431301_112_dialog_content = "상관없습니다. 다른 증인도 있으니까요.",
  ui_story_5043_50431301_113_dialog_content = "게다가 지극히 신뢰할 수 있는 신분이지요.",
  ui_story_5043_50431301_114_dialog_content = "슈와브 대심판관님. 설마 백야성의 공주 전하조차 공범이라 주장하진 않으시겠죠?",
  ui_story_5043_50431301_115_dialog_content = "......",
  ui_story_5043_50431301_116_dialog_content = "...공주 전하 말입니까?",
  ui_story_5043_50431301_117_dialog_content = "두 번째 사건 발생 당시, 저희는 소란이 발생한 미드가든 초원 광장에 있었습니다.",
  ui_story_5043_50431301_118_dialog_content = "...무슨 뜻인지 알겠어. 하지만 지금은 혼란을 가라앉히는 게 먼저야!",
  ui_story_5043_50431301_119_dialog_content = "여러분, 당황하지 말고 절 따라오세요!",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431301_121_dialog_content = "(무슨 소리지?!)",
  ui_story_5043_50431301_122_dialog_content = "그때 전 조각상이 파괴된 소리를 가장 먼저 들었고,\n그 후 피고와 조사를 진행했습니다.",
  ui_story_5043_50431301_123_dialog_content = "그리고 저희 두 사람은 현장에 남겨진 목 없는 조각상을 동시에 발견했습니다.",
  ui_story_5043_50431301_124_dialog_content = "이 과정 동안 티나 심판관은 줄곧 제 시야 범위 안에 있었고, 완벽한 알리바이가 성립합니다.",
  ui_story_5043_50431301_125_dialog_content = "이 점은 카렌 전하와 수녀님이 증명해 주실 수 있습니다.",
  ui_story_5043_50431301_126_dialog_content = "맞아. 사건이 일어날 때까지 티나는 계속 우리와 함께 있었어.",
  ui_story_5043_50431301_127_dialog_content = "티나의 혐의는 성립되지 않아.",
  ui_story_5043_50431301_128_dialog_content = "네, 저도 티나 심판관의 알리바이를 증언하겠어요.",
  ui_story_5043_50431301_129_dialog_content = "어떻습니까, 슈와브 대심판관님?",
  ui_story_5043_50431301_130_dialog_content = "이 정도면 원하시는 증인으로 충분합니까?",
  ui_story_5043_50431301_131_dialog_content = "그래요, 좋습니다.",
  ui_story_5043_50431301_132_dialog_content = "카렌 전하의 증언이라면 본 심판소는 물론 존중해야겠지요.",
  ui_story_5043_50431301_133_dialog_content = "아, 카렌 전하뿐만이 아니라, 마티외 심판관의 열정적인 변론도 감동적이었습니다.",
  ui_story_5043_50431301_134_dialog_content = "덕분에 제가 작은 실수를 저질렀다는 것을 깨달았습니다.\n제가 티나 캠벨 양에게 누명을 씌워 버렸군요.",
  ui_story_5043_50431301_135_dialog_content = "(서, 성공한 건가?)",
  ui_story_5043_50431301_136_dialog_content = "따라서 본 심판소는 본건의 공소 사실을 철회하겠습니다.\n피고 티나 캠벨은 「목 없는 조각상 연쇄 사건」의 범인이 아닙니다.",
  ui_story_5043_50431301_137_dialog_content = "피고는 그저 <color=#FFB400>세 번째</color> 「목 없는 조각상 사건」의 범인일 뿐입니다.",
  ui_story_5043_50431301_138_dialog_content = "뭐야...?",
  ui_story_5043_50431301_139_dialog_content = "쳇.",
  ui_story_5043_50431301_140_dialog_content = "마티외 심판관, 노력한 보람이 있었네요! 당신 덕분에 피고의 벌이 대폭 가벼워질 겁니다.",
  ui_story_5043_50431301_141_dialog_content = "하지만! 피고가 세 번째 사건의 범인인 이상, 핵심 증거가 증거능력을 상실하지 않는 한!",
  ui_story_5043_50431301_142_dialog_content = "피고는 변함없이 「공용물건손상죄 및 연애방해죄」로 기소될 것입니다.",
  ui_story_5043_50431301_143_dialog_content = "이 점은 마티외 심판관께서도 동의하시겠죠?",
  ui_story_5043_50431301_144_dialog_content = "동의 같은 소리 하네...",
  ui_story_5043_50431301_145_dialog_content = "아니면 본건의 핵심 증거물에 계속해서 이의를 제기하실 생각인가요?",
  ui_story_5043_50431301_146_dialog_content = "......",
  ui_story_5043_50431301_147_dialog_content = "<size=30>마티외 씨... 힘을 내...!</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>지금까지의 변론으론 부족해...</size>",
  ui_story_5043_50431301_149_dialog_content = "아닙니다. 제 변론은 여기까지입니다.",
  ui_story_5043_50431301_150_dialog_content = "뭐라고...?",
  ui_story_5043_50431301_151_dialog_content = "후훗, 그걸로 끝입니까?",
  ui_story_5043_50431301_152_dialog_content = "네.",
  ui_story_5043_50431301_153_dialog_content = "그렇다면 본 심판소는...",
  ui_story_5043_50431301_154_dialog_content = "레인, 바톤 터치다.",
  ui_story_5043_50431301_155_dialog_content = "!!!",
  ui_story_5043_50431301_156_dialog_content = "레인?",
  ui_story_5043_50431301_157_dialog_content = "네 실력을 보여줄 기회를 놓치지 마라, 신입.",
  ui_story_5043_50431301_158_dialog_content = "네.",
  ui_story_5043_50431301_159_dialog_content = "슈와브 대심판관님, 배심원 여러분, 방청객 여러분.",
  ui_story_5043_50431301_160_dialog_content = "부디 제게 몇 분의 시간을 주시기 바랍니다.",
  ui_story_5043_50431301_161_dialog_content = "모두 저와 함께 <color=#FFB400>추리</color>를 한번 해보도록 합시다.",
  ui_story_5043_50431301_162_dialog_content = "쯧쯧, 애송이가 말이 건방지군.",
  ui_story_5043_50431301_163_dialog_content = "레인 심판관. 서민 출신인 당신이라면 언행을 더 주의할 줄 알았는데요.",
  ui_story_5043_50431301_164_dialog_content = "업무에 과실이 있을 때, 당신에겐 마티외 심판관처럼 뒷배가 돼 줄 가문이 없으니까요.",
  ui_story_5043_50431301_165_dialog_content = "슈와브 대심판관님, 서민 출신이 꼭 나쁘기만 한 것은 아니라고 생각합니다.",
  ui_story_5043_50431301_166_dialog_content = "적어도 제가 한 잘못 때문에 가문 전체가 연루될까 걱정할 필요는 없으니까요.",
  ui_story_5043_50431301_167_dialog_content = "큭...",
  ui_story_5043_50431301_168_dialog_content = "슈와브 대심판관께서는 핵심적인 증거와 세 번째 사건을\n무척이나 신경 쓰고 계시는 것 같더군요.",
  ui_story_5043_50431301_169_dialog_content = "그렇다면 이 사건에 대해 다시 한번 자세히 검토해 보기로 합시다.",
  ui_story_5043_50431301_170_dialog_content = "세부적인 사항에 주목하고, 범인이 간과하고 있던 작은 실마리를 찾아보는 겁니다.",
  ui_story_5043_50431301_171_dialog_content = "오, 훌륭하군! 참으로 전문성을 갖추고 있구나! 마음에 드는구나!",
  ui_story_5043_50431301_172_dialog_content = "(범인이 간과하고 있던 작은 실마리라니...)",
  ui_story_5043_50431301_173_dialog_content = "(레인 씨, 드디어 찾아낸 거야?)",
  ui_story_5043_50431301_174_dialog_content = "우선 어제 사건이 일어나기 전의 천성의 계단으로 돌아가 보겠습니다.",
  ui_story_5043_50431301_175_dialog_content = "저희는 천성의 계단 위에 있는 조각상을 지키기 위해 시위대의 행진을 저지하려 했습니다.",
  ui_story_5043_50431301_176_dialog_content = "그러나 뜻밖에도 시위대 후미에서 갑자기 암귀가 출현했던 것입니다.",
  ui_story_5043_50431301_177_dialog_content = "저는 즉시 전투를 개시했고, 얼마 후 피고도 달려왔습니다.",
  ui_story_5043_50431302_1_dialog_content = "마지막 세 마리가 남았을 때, 전 그중 한 마리를 계단 아래로 차버렸습니다.",
  ui_story_5043_50431302_2_dialog_content = "이어서 다른 한 마리를 제 선창으로 꿰뚫었지요.",
  ui_story_5043_50431302_3_dialog_content = "그리고 마지막 한 마리는 티나가 일격에 분쇄했습니다.",
  ui_story_5043_50431302_4_dialog_content = "그만그만, 그렇게까지 세세할 필요가 있나?",
  ui_story_5043_50431302_5_dialog_content = "눈앞의 암귀들을 모두 처치한 후, 저와 티나는 조각상이 있는 곳으로 돌아와\n다른 일행과 합류하려고 했습니다.",
  ui_story_5043_50431302_6_dialog_content = "하지만 밀집해 있는 인파를 뚫고 지나가는 것은 쉽지 않았습니다.",
  ui_story_5043_50431302_7_dialog_content = "결국 도중에 티나와 떨어지게 되었고, 티나와 다시 만난 건 사건이 발생한 뒤였습니다.",
  ui_story_5043_50431302_8_dialog_content = "맞아요. 사람들 사이를 지나가는 건 정말 힘들었어요.\n계속 밀려서 좀처럼 앞으로 갈 수가 없었어요...",
  ui_story_5043_50431302_9_dialog_content = "그 점은 제 이해와 일치하는군요.",
  ui_story_5043_50431302_10_dialog_content = "이 세 번째 사건에서 피고에겐 알리바이가 없습니다.",
  ui_story_5043_50431302_11_dialog_content = "알리바이는 일단 넘어가겠습니다. 다시 사건이 일어난 시각으로 돌아가죠.",
  ui_story_5043_50431302_12_dialog_content = "제가 조각상이 있는 곳으로 돌아왔을 때, 또 다른 암귀의 습격이 있었습니다.",
  ui_story_5043_50431302_13_dialog_content = "저흰 조각상 주변에서 암귀와 싸웠고, 범인에게 범행을 저지를 틈을 주고 말았습니다.",
  ui_story_5043_50431302_14_dialog_content = "범인은 전투 중의 혼란을 틈타 몰래 손을 뻗어 조각상의 머리를 파괴했습니다.",
  ui_story_5043_50431302_15_dialog_content = "전 그 손을 붙잡았지만, 범인은 암귀들 틈에 섞여 있었기 때문에\n외모나 체형적 특징을 식별할 수 없었습니다.",
  ui_story_5043_50431302_16_dialog_content = "그 순간 범인은 장갑을 벗어 제 손을 뿌리치고 도망쳐 버렸습니다.",
  ui_story_5043_50431302_17_dialog_content = "바로 본건의 핵심 단서가 된 그 장갑 말이죠.",
  ui_story_5043_50431302_18_dialog_content = "카렌 전하와 마티외 심판관은 곧바로 주위의 암귀들을 쓰러트렸지만,\n넓은 광장엔 범인의 모습이 보이지 않았습니다.",
  ui_story_5043_50431302_19_dialog_content = "티나 심판관이 돌아온 건 그 후였습니다.",
  ui_story_5043_50431302_20_dialog_content = "이상이 이 사건의 전체 과정입니다.",
  ui_story_5043_50431302_21_dialog_content = "아주 좋습니다. 레인 심판관의 진술은 매우 객관적이었습니다.",
  ui_story_5043_50431302_22_dialog_content = "덕분에 이후의 심리가 매우 합리적으로 진행되겠군요.\n그 장갑을 단서로 조사하면 진짜 범인을 찾을 수 있다는 뜻이니까요.",
  ui_story_5043_50431302_23_dialog_content = "그리고 우리가 피고를 체포한 것도 같은 판단에 따라 이루어진 것입니다.",
  ui_story_5043_50431302_24_dialog_content = "아니요, 대심판관님의 추리는 경솔했습니다.",
  ui_story_5043_50431302_25_dialog_content = "호오?",
  ui_story_5043_50431302_26_dialog_content = "범행 현장에서 저희가 얻은 범인의 정보는 다음과 같습니다.",
  ui_story_5043_50431302_27_dialog_content = "증거물인 장갑을 끼고, 손으로 조각상을 부쉈죠.",
  ui_story_5043_50431302_28_dialog_content = "한편 대심판관이 체포한 피고의 특징은...",
  ui_story_5043_50431302_29_dialog_content = "증거물인 장갑의 합법적 소유자인 젊은 여성입니다.",
  ui_story_5043_50431302_30_dialog_content = "엄밀히 보자면 양자는 완전히 동일한 관계가 아님을 알 수 있습니다.",
  ui_story_5043_50431302_31_dialog_content = "정말 외골수로군요.",
  ui_story_5043_50431302_32_dialog_content = "장갑의 소유자야말로 현장에서 그것을 착용하고 있었을 가능성이 가장 높습니다.\n무슨 문제가 있다는 거죠?",
  ui_story_5043_50431302_33_dialog_content = "물론 거기까지는 문제가 없습니다. 문제는 그다음입니다.",
  ui_story_5043_50431302_34_dialog_content = "피고는 손으로 조각상을 부술 수 있을까요?",
  ui_story_5043_50431302_35_dialog_content = "오오! 새로운 관점이로군.",
  ui_story_5043_50431302_36_dialog_content = "생각해 보면 그렇지. 젊은 아가씨가 손으로 조각상을 부술 수 있을 리가 없잖아?",
  ui_story_5043_50431302_37_dialog_content = "레인 심판관, 생각을 너무 많이 해서 머리가 과열되기라도 했습니까?",
  ui_story_5043_50431302_38_dialog_content = "2분 전 자신의 발언을 떠올려 보세요.",
  ui_story_5043_50431302_39_dialog_content = "마지막 세 마리가 남았을 때, 전 그중 한 마리를 계단 아래로 차버렸습니다.",
  ui_story_5043_50431302_40_dialog_content = "이어서 다른 한 마리를 제 선창으로 꿰뚫었지요.",
  ui_story_5043_50431302_41_dialog_content = "그리고 마지막 한 마리는 티나가 <color=#FFB400>일격에 분쇄</color>했습니다.",
  ui_story_5043_50431302_42_dialog_content = "자기 동료에 대해 잘 모르시는 겁니까?\n피고는 「신의 손」을 계승한 캠벨 가문의 후계자입니다.",
  ui_story_5043_50431302_43_dialog_content = "암귀조차도 쉽게 박살 낼 수 있는데, 하물며 조각상은 어떨까요?",
  ui_story_5043_50431302_44_dialog_content = "그랬지! 피고는 평범한 소녀가 아니지 않은가!",
  ui_story_5043_50431302_45_dialog_content = "젊은이, 그대의 추리는 생각이 짧았던 것 같군.",
  ui_story_5043_50431302_46_dialog_content = "(아직 부족해...)",
  ui_story_5043_50431302_47_dialog_content = "(레인 씨, 다른 건 없는 거야? 찾아내야 해. 범인도 놓친 무언가를...)",
  ui_story_5043_50431302_48_dialog_content = "아, 맞습니다. 피고는 「신의 손」을 계승했습니다.",
  ui_story_5043_50431302_49_dialog_content = "즉, 피고는 「신의 손」으로 조각상을 부쉈다는 것이군요. 맞습니까?",
  ui_story_5043_50431302_50_dialog_content = "물론이죠. 그게 유일하고 정확한 결론입니다.",
  ui_story_5043_50431302_51_dialog_content = "레인 심판관, 당신의 치밀한 사고방식은 칭찬받아 마땅합니다.",
  ui_story_5043_50431302_52_dialog_content = "하지만 그런 문제는 추후에 개인적으로 말씀하세요.\n재판에서 여러 사람의 시간을 낭비하면 안 되니까요.",
  ui_story_5043_50431302_53_dialog_content = "아니요, 그 누구의 시간도 낭비하지 않았습니다.",
  ui_story_5043_50431302_54_dialog_content = "이 모든 추리는 방금 대심판관님이 인정한 결론을 도출하기 위한 것이었으니까요.",
  ui_story_5043_50431302_55_dialog_content = "「티나는 신의 손으로 조각상을 파괴했다」는 결론 말입니다.",
  ui_story_5043_50431302_56_dialog_content = "...돌려 말하지 마세요. 그래서 무슨 말이 하고 싶은 거죠?",
  ui_story_5043_50431302_57_dialog_content = "이렇게 도출된 결론으로 다시 한번 돌아보면 알 수 있을 겁니다.",
  ui_story_5043_50431302_58_dialog_content = "티나를 피고석에 앉힌 장갑이야말로 피고가 무죄임을 증명하는 명백한 증거입니다!",
  ui_story_5043_50431302_59_dialog_content = "뭐라고요?!",
  ui_story_5043_50431302_60_dialog_content = "본건의 가장 중요한 증거물이자 범인이 범행 시 착용하고 있던 장갑을\n이 자리의 모두에게 공개하는 것을 허락해 주십시오.",
  ui_story_5043_50431302_61_dialog_content = "비록 슈와브 대심판관께서 저희의 증거물 검토를 금지하셨던 동안,\n일부 흔적이 변조되었을 가능성은 있겠지만 말이죠.",
  ui_story_5043_50431302_62_dialog_content = "물론 그렇다고 해서 장갑 자체를 바꿔치기했다거나 하진 않았겠죠.\n그 점은 믿어도 되겠습니까?",
  ui_story_5043_50431302_63_dialog_content = "증거물을 지키는 건 심판소의 가장 기본적인 책임입니다!\n지금 심판소의 근본을 의심하는 겁니까?!",
  ui_story_5043_50431302_64_dialog_content = "그렇다면 다행입니다.",
  ui_story_5043_50431302_65_dialog_content = "자, 여러분, 이 장갑을 잘 보세요.",
  ui_story_5043_50431302_66_dialog_content = "이건... 오른손에 끼는 장갑이죠?",
  ui_story_5043_50431302_67_dialog_content = "쓸데없는 소리 말고 요점만 말하세요!",
  ui_story_5043_50431302_68_dialog_content = "어느 쪽 손에 끼는 게 무슨 상관이...",
  ui_story_5043_50431302_69_dialog_content = "!!!",
  ui_story_5043_50431302_70_dialog_content = "어라?",
  ui_story_5043_50431302_71_dialog_content = "아앗──!",
  ui_story_5043_50431302_72_dialog_content = "오른손! 그런 거였어!",
  ui_story_5043_50431302_73_dialog_content = "무슨 말이야?! 그게 왜?",
  ui_story_5043_50431302_74_dialog_content = "이해하신 모양이군요, 슈와브 대심판관님.",
  ui_story_5043_50431302_75_dialog_content = "이건 결코 돌이킬 수 없는 치명적인 실수입니다.",
  ui_story_5043_50431302_76_dialog_content = "티나가 조각상을 파괴할 수 있는 「신의 손」은 <color=#FFB400>왼손</color>이니까요.",
  ui_story_5043_50431302_77_dialog_content = "하지만 이건 <color=#FFB400>오른손</color>에 끼는 장갑입니다!",
  ui_story_5043_50431302_78_dialog_content = "아아! 그렇구나!",
  ui_story_5043_50431302_79_dialog_content = "왼손... 오른손...",
  ui_story_5043_50431302_80_dialog_content = "당신은 줄곧 심판소에서 사건 해결의 핵심인 이 증거물의 중요성을 강조했습니다.",
  ui_story_5043_50431302_81_dialog_content = "그렇다면 우리도 증거를 무엇보다 중시해야겠죠.",
  ui_story_5043_50431302_82_dialog_content = "「신의 손」과 다른 쪽 손에 끼는 장갑을 증거물로,\n당신은 어떤 결론을 도출하실 겁니까?",
  ui_story_5043_50431302_83_dialog_content = "자, 슈와브 대심판관님. 모두에게 선고해 주시죠.",
  ui_story_5043_50431302_84_dialog_content = "이... 이 자식...",
  ui_story_5043_50431302_85_dialog_content = "죄를 묻는 증거물이 누명을 벗는 증거물이 됐잖아? 대단해, 레인 씨!",
  ui_story_5043_50431302_86_dialog_content = "이제서야 저울이 우리 쪽으로 기울었어!",
  ui_story_5043_50431302_87_dialog_content = "설마 그런 곳에 허점이 있을 줄이야...",
  ui_story_5043_50431302_88_dialog_content = "자, 좋습니다. 당신들의 궤변도 나름대로 이치에 맞는 건 인정하겠습니다.",
  ui_story_5043_50431302_89_dialog_content = "아무래도 이 증거로는 피고에게 죄를 물을 수 없을 것 같습니다.",
  ui_story_5043_50431302_90_dialog_content = "「목 없는 조각상 연쇄 사건」의 용의자는 다시 수수께끼로 남고 말았습니다.",
  ui_story_5043_50431302_91_dialog_content = "좋았어!",
  ui_story_5043_50431302_92_dialog_content = "카렌, 다들 해냈어!",
  ui_story_5043_50431302_93_dialog_content = "응, 정말 다행이네!",
  ui_story_5043_50431302_94_dialog_content = "심판소에서 백야성의 공정함을 지켜볼 수 있어서 영광이야!",
  ui_story_5043_50431302_95_dialog_content = "용의자가 다시 수수께끼가 됐다는 건...",
  ui_story_5043_50431302_96_dialog_content = "전 죄가 없다는 얘기네요!",
  ui_story_5043_50431302_97_dialog_content = "당연하죠. 당신은 처음부터 결백했으니까요.",
  ui_story_5043_50431302_98_dialog_content = "우리한테 제대로 감사하라고. 특히 서민 신입한테 말이야.",
  ui_story_5043_50431302_99_dialog_content = "처음 큰 무대에 선 것 치고는 꽤 잘했잖아.",
  ui_story_5043_50431302_100_dialog_content = "네! 물론 여러분께 감사하고 있어요!",
  ui_story_5043_50431302_101_dialog_content = "고마워요! 멋진 동료 여러분!",
  ui_story_5043_50431302_102_dialog_content = "아니, 지금 뭐 하자는 거야?",
  ui_story_5043_50431302_103_dialog_content = "이 난리를 쳐놓고 결국 범인을 잘못 잡은 거였어?",
  ui_story_5043_50431302_104_dialog_content = "......",
  ui_story_5043_50431302_105_dialog_content = "세상에, 말도 안 돼!",
  ui_story_5043_50431302_106_dialog_content = "온종일 여기 앉아서 일장 연설을 듣게 만들어 놓고,\n고작 한다는 소리가 결국 원점으로 돌아왔다고?!",
  ui_story_5043_50431302_107_dialog_content = "내가 말했겠지! 내 인내심에도 한계가 있다고!",
  ui_story_5043_50431302_108_dialog_content = "만약 오늘 이 사건에 종지부를 찍을 수 없다면...\n너희 연애 심판소에 종지부를 찍어주고 말겠다!",
  ui_story_5043_50431302_109_dialog_content = "원고, 진정하세요. 사건은 이제 막 반환점을 돌았을 뿐인걸요.",
  ui_story_5043_50431302_110_dialog_content = "반환점?",
  ui_story_5043_50431302_111_dialog_content = "티나, 이리 오세요.",
  ui_story_5043_50431302_112_dialog_content = "이어서 피고석에 앉을 다른 분을 모시겠습니다.",
  ui_story_5043_50431302_113_dialog_content = "네? 다른 분이라면...",
  ui_story_5043_50431302_114_dialog_content = "연애 심판소의 엄밀한 조사와 증거 수집에 근거하여, 본 심판소의 심판관 레인...",
  ui_story_5043_50431302_115_dialog_content = "심판관 마티외는...",
  ui_story_5043_50431302_116_dialog_content = "「공용물건손상죄 및 연애방해죄」로 슈와브 살라르 씨를 기소하겠습니다.",
  ui_story_5043_50431302_117_dialog_content = "대심판관님, 이쪽 자리로 옮겨 주시죠.",
  ui_story_5043_50431302_118_dialog_content = "뭐라고? 슈와브를 기소한다고?!",
  ui_story_5043_50431302_119_dialog_content = "PlayerName, 이것도 너희 계획이었어?",
  ui_story_5043_50431302_120_dialog_content = "으엑...",
  ui_story_5043_50431302_121_dialog_content = "확실히 우린 어제 저 사람을 의심하긴 했어...",
  ui_story_5043_50431302_122_dialog_content = "근데 기소까지 할 줄은 몰랐다고...",
  ui_story_5043_50431302_123_dialog_content = "결정적인 증거는 있어?",
  ui_story_5043_50431302_124_dialog_content = "전혀 없는데...",
  ui_story_5043_50431302_125_dialog_content = "절 기소한다고요?",
  ui_story_5043_50431302_126_dialog_content = "레인 심판관, 지금 자신이 무슨 말을 하는 건지 알고 있습니까?",
  ui_story_5043_50431302_127_dialog_content = "저는 제 직무에 최선을 다하고 있을 뿐입니다.",
  ui_story_5043_50431302_128_dialog_content = "훗, 정말로 최선이어야 할 겁니다.",
  ui_story_5043_50431302_129_dialog_content = "먼저 말해두죠. 세 번의 사건 발생 시점에 제겐 결코 반박할 수 없는 알리바이가 있습니다.",
  ui_story_5043_50431302_130_dialog_content = "조사해 보면 금방 알 수 있을 겁니다.\n심판소의 사람이라면 누구나 증언할 수 있죠.",
  ui_story_5043_50431302_131_dialog_content = "이런 어처구니없는 모함이라니, 더 변론할 필요조차 없어 보입니다만.",
  ui_story_5043_50431302_132_dialog_content = "슈와브 씨, 안심하세요. 조사는 물론 실시할 겁니다.",
  ui_story_5043_50431302_133_dialog_content = "당신의 주장도 인정합니다. 세 사건 모두 당신은 알리바이가 있습니다.",
  ui_story_5043_50431302_134_dialog_content = "그렇다면 왜 기소를 철회하지 않는 거죠?",
  ui_story_5043_50431302_135_dialog_content = "범인이 꼭 직접 현장에 가야만 하는 건 아니니까요.",
  ui_story_5043_50431302_136_dialog_content = "증인신문을 신청해도 되겠습니까?",
  ui_story_5043_50431302_137_dialog_content = "증인?",
  ui_story_5043_50431302_138_dialog_content = "증인은 증인석으로 나와 증언해 주시기 바랍니다.",
  ui_story_5043_50431302_139_dialog_content = "(언제 이 사건에 증인이 생긴 거지?)",
  ui_story_5043_50431302_140_dialog_content = "(대체 누가...)",
  ui_story_5043_50431302_141_dialog_content = "저, 저기...",
  ui_story_5043_50431302_142_dialog_content = "말해도 되나요?",
  ui_story_5043_50431302_143_dialog_content = "암귀?! 게다가 말도 하잖아?!",
  ui_story_5043_50431302_144_dialog_content = "보, 복슬 씨!",
  ui_story_5043_50431302_145_dialog_content = "뭐어어어?!",
  ui_story_5043_50431302_146_dialog_content = "암귀가 증인이라고? 대체 이게 무슨...",
  ui_story_5043_50431302_147_dialog_content = "미쳤습니까?! 감히 그런 더러운 것을 심판소에 들이다니!",
  ui_story_5043_50431302_148_dialog_content = "심판소의 질서를 어지럽힐 생각인가요?!",
  ui_story_5043_50431302_149_dialog_content = "안심하세요. 이 암귀는 무해하다는 것을 이미 확인했습니다.",
  ui_story_5043_50431302_150_dialog_content = "그저 진실을 밝히기 위해 증언하러 왔을 뿐, 그 누구도 해치지 않을 겁니다.",
  ui_story_5043_50431302_151_dialog_content = "이 자리의 그 누구도 진실을 거부하진 않겠죠?",
  ui_story_5043_50431302_152_dialog_content = "음, 그렇다면 증언을 들어보는 것도 나쁘진 않을 것 같군.",
  ui_story_5043_50431302_153_dialog_content = "복슬 씨... 저번보다 더 살이 빠진 것 같아요...",
  ui_story_5043_50431302_154_dialog_content = "이렇게 특별한 증인이라니, 대체 어떤 놀라운 증언을 할까...",
  ui_story_5043_50431302_155_dialog_content = "머, 먼저 자기소개부터 할게요...",
  ui_story_5043_50431302_156_dialog_content = "여, 여러분, 절 무서워하지 말아 주세요...",
  ui_story_5043_50431302_157_dialog_content = "저는 원래 평범한 하급 암귀였어요...",
  ui_story_5043_50431302_158_dialog_content = "하, 하지만 자난성에서 실수로 어떤 실험 도구를 삼켜 버렸어요...",
  ui_story_5043_50431302_159_dialog_content = "그게 뭔지는 모르겠어요... 하지만...",
  ui_story_5043_50431302_160_dialog_content = "제 모습에 변화가 일어났고, 뚜렷한 의식을 가지게 됐어요...",
  ui_story_5043_50431302_161_dialog_content = "쯧, 봐라. 저 일루미나 놈들이 또 무슨 대단한 발명을 해버렸는지 말이야!",
  ui_story_5043_50431302_162_dialog_content = "한 번에 말도 엄청 길게 하네... 통용어가 전보다 훨씬 유창해졌는데?",
  ui_story_5043_50431302_163_dialog_content = "그, 그리고 다른 암귀와의 연결도 약해졌어요...",
  ui_story_5043_50431302_164_dialog_content = "다른 암귀들은 절 통제할 수 없었고, 저도 다른 암귀들을 통제할 수 없었어요...",
  ui_story_5043_50431302_165_dialog_content = "그 뒤로 암귀 무리에서 전 매번 실수만 하고... 주어진 업무를 해내지 못했어요...",
  ui_story_5043_50431302_166_dialog_content = "결국 두목은 참다못해 절 쫓아냈어요...",
  ui_story_5043_50431302_167_dialog_content = "폐를 끼칠 거면 차라리 오로리안한테 가서 끼치라면서 말이죠...",
  ui_story_5043_50431302_168_dialog_content = "아... 암귀도 동료한테 괴롭힘을 당할 때가 있는 거였구나...",
  ui_story_5043_50431302_169_dialog_content = "동정해선 안 돼. 적의 적이라고 반드시 친구는 아니니까.",
  ui_story_5043_50431302_170_dialog_content = "그 후 전 오로리안의 언어와 문화를 배우기 시작했어요...",
  ui_story_5043_50431302_171_dialog_content = "머, 먹고 살기 위해 전 여러 곳에서 일했어요... 항상 금방 잘렸지만요...",
  ui_story_5043_50431302_172_dialog_content = "사는 건 힘들었어요... 하지만 전에 비하면 훨씬 즐거워요...",
  ui_story_5043_50431302_173_dialog_content = "전 아무도 해치지 않아요...",
  ui_story_5043_50431302_174_dialog_content = "저, 전 오로리안의 삶이 좋아요!",
  ui_story_5043_50431302_X174_dialog_content = "더는 미움받고 싶지 않아요!",
  ui_story_5043_50431302_175_dialog_content = "그래요! 복슬 씨는 여러분을 해치지 않을 거예요!",
  ui_story_5043_50431302_176_dialog_content = "많은 오로리안들보다 훨씬 착하고 귀여워요! 그러니까 다들 안심하세요!",
  ui_story_5043_50431302_177_dialog_content = "쯧쯧... 암귀가 오로리안처럼 살 수 있다니...",
  ui_story_5043_50431302_178_dialog_content = "시대가 변했군.",
  ui_story_5043_50431302_179_dialog_content = "자기소개는 그 정도면 됐습니다, 증인.",
  ui_story_5043_50431302_180_dialog_content = "증인은 무엇을 증언하기 위해 본 심판소에 출석했습니까?",
  ui_story_5043_50431302_181_dialog_content = "어, 어떤 오로리안의 죄를 고발하러 왔어요...",
  ui_story_5043_50431302_182_dialog_content = "그게 누구입니까?",
  ui_story_5043_50431302_183_dialog_content = "제일 높은 곳에 앉아 있는... 저 슈와브라는 사람이에요!",
  ui_story_5043_50431302_184_dialog_content = "큭...",
  ui_story_5043_50431302_185_dialog_content = "어떤 죄입니까?",
  ui_story_5043_50431302_186_dialog_content = "저, 저 사람이 조각상을 부순 진범이에요!",
  ui_story_5043_50431302_187_dialog_content = "하지만 피고에겐 알리바이가 있습니다. 그 증언의 근거가 뭐죠?",
  ui_story_5043_50431302_188_dialog_content = "저 사람은 현장에 있을 필요가 없어요... 왜냐면 조각상을... 조, 조각상을...",
  ui_story_5043_50431302_189_dialog_content = "조각상을 어떻게 했습니까!",
  ui_story_5043_50431302_190_dialog_content = "암귀를 조종해서 부쉈거든요!",
  ui_story_5043_50431401_1_dialog_content = "암귀를 조종해?!",
  ui_story_5043_50431401_2_dialog_content = "세상에, 지금 그게 무슨 말인지 알고 있나?",
  ui_story_5043_50431401_3_dialog_content = "암귀와 결탁하는 것은 극악무도한 죄다!",
  ui_story_5043_50431401_4_dialog_content = "풉, 어이가 없을 만큼 웃기는 증언이군요!",
  ui_story_5043_50431401_5_dialog_content = "지금 고작 암귀 따위의 일방적인 증언을 가지고...\n백야성 귀족인 제게 암귀와 결탁했다는 오명을 씌우겠다는 겁니까?!",
  ui_story_5043_50431401_6_dialog_content = "망상도 정도껏 하세요! 차라리 술 취한 사람의 잠꼬대가 더 신빙성이 있겠군요!",
  ui_story_5043_50431401_7_dialog_content = "레인, 모함하는 수준이 정말 형편없군요!",
  ui_story_5043_50431401_8_dialog_content = "그렇습니까? 그럼 당신한테 좀 배워야 할까요?",
  ui_story_5043_50431401_9_dialog_content = "크윽...",
  ui_story_5043_50431401_10_dialog_content = "당신의 죄를 묻는 일에 모함 따위는 필요 없습니다.",
  ui_story_5043_50431401_11_dialog_content = "지금 말씀하신 것처럼, 암귀의 증언만으로 유죄를 선고할 순 없습니다.",
  ui_story_5043_50431401_12_dialog_content = "하지만 만약 이 암귀가 이 사건에서 특수한 역할을 맡고 있다면 어떨까요?",
  ui_story_5043_50431401_13_dialog_content = "...특수한 역할?!",
  ui_story_5043_50431401_14_dialog_content = "증인, 계속하세요.",
  ui_story_5043_50431401_15_dialog_content = "죄, 죄송합니다!",
  ui_story_5043_50431401_16_dialog_content = "전 잘못을 했어요! 여기서 자백할게요!",
  ui_story_5043_50431401_17_dialog_content = "네?",
  ui_story_5043_50431401_18_dialog_content = "말도 안 돼요... 복슬 씨가 나쁜 짓을 할 리가 없잖아요!",
  ui_story_5043_50431401_19_dialog_content = "대체 뭘 하자는 것이냐?\n조금 전까지 남의 죄를 말하더니, 이번엔 자기 죄를 인정하겠다고?",
  ui_story_5043_50431401_20_dialog_content = "똑바로 생각하고 발언해라!",
  ui_story_5043_50431401_21_dialog_content = "죄, 죄송합니다. 사실은...",
  ui_story_5043_50431401_22_dialog_content = "제가 바로 조각상을 부순 범인이에요!",
  ui_story_5043_50431401_23_dialog_content = "뭐?!",
  ui_story_5043_50431401_24_dialog_content = "하아? 네가 범인이라고?",
  ui_story_5043_50431401_25_dialog_content = "잔인하게 내 「아내」와 「애인」을 부순 게 바로 너였던 것이냐?!",
  ui_story_5043_50431401_26_dialog_content = "맞아요, 제가 했어요...",
  ui_story_5043_50431401_27_dialog_content = "이... 빌어먹을 놈이!",
  ui_story_5043_50431401_28_dialog_content = "하, 하지만... 제가 원해서 한 게 아니에요!",
  ui_story_5043_50431401_29_dialog_content = "다 슈와브가 억지로 시킨 거예요!",
  ui_story_5043_50431401_30_dialog_content = "여러분, 제발 선처해 주세요...",
  ui_story_5043_50431401_31_dialog_content = "<size=45>뭐?!</size>",
  ui_story_5043_50431401_32_dialog_content = "......",
  ui_story_5043_50431401_33_dialog_content = "그랬구나...",
  ui_story_5043_50431401_34_dialog_content = "사, 사건은 보름 전부터 시작됐어요...",
  ui_story_5043_50431401_35_dialog_content = "전 백야성에서 새로운 일자리를 차, 찾고 있었어요...",
  ui_story_5043_50431401_36_dialog_content = "백야성은 넓고... 길도 몰라서... 어느새 밤이 돼 있었어요...",
  ui_story_5043_50431401_37_dialog_content = "그러다... 갑자기 미드가든에서 암귀 몇 마리를 만났어요...",
  ui_story_5043_50431401_38_dialog_content = "음, 확실히 최근 성안에서 몇 번인가 암귀의 흔적이 발견됐었지.",
  ui_story_5043_50431401_39_dialog_content = "조치가 필요하겠군.",
  ui_story_5043_50431401_40_dialog_content = "서, 설마 백야성에서 동족을 만날 줄은 몰랐어요... 그래서 조금 신기하게 생각했어요...",
  ui_story_5043_50431401_41_dialog_content = "제가 깜짝 놀라는 사이... 그 암귀들은 절 길 잃은 동료라고 착각했어요...",
  ui_story_5043_50431401_42_dialog_content = "그러더니 억지로 절 무리에 포함시켰어요...",
  ui_story_5043_50431401_43_dialog_content = "전 영문도 모른 채 따라다니다가 마지막엔...",
  ui_story_5043_50431401_44_dialog_content = "살라르 장원에 도착했어요...",
  ui_story_5043_50431401_45_dialog_content = "어?! 슈와브네 집이잖아?!",
  ui_story_5043_50431401_46_dialog_content = "네... 전 거기서 슈와브를 봤어요...",
  ui_story_5043_50431401_47_dialog_content = "그리고 깜짝 놀랄 장면을 보게 됐어요...",
  ui_story_5043_50431401_48_dialog_content = "슈와브는 암귀를 노예처럼 부리고 있었어요...",
  ui_story_5043_50431401_49_dialog_content = "암귀들도 모두 슈와브의 말에 복종하고 있었고요...",
  ui_story_5043_50431401_50_dialog_content = "저, 전 도망칠 기회가 없어서 같은 무리인 척하고 있었어요...",
  ui_story_5043_50431401_51_dialog_content = "그러다 결국 다른 암귀들이랑 같이... 지, 지하실에 갇혔어요...",
  ui_story_5043_50431401_52_dialog_content = "지하실?!",
  ui_story_5043_50431401_53_dialog_content = "암귀를 가둬 두는 곳이었구나. 어쩐지...",
  ui_story_5043_50431401_54_dialog_content = "슈와브의 집 지하실을 알아?",
  ui_story_5043_50431401_55_dialog_content = "으엑, 이 얘긴 심판소에서 말하긴 좀...",
  ui_story_5043_50431401_56_dialog_content = "이따가 따로 얘기해 줄게!",
  ui_story_5043_50431401_57_dialog_content = "<size=45>터무니없는 헛소리입니다!</size>",
  ui_story_5043_50431401_58_dialog_content = "이게 대체 무슨 웃기는 증언입니까! 동화라도 읽는 겁니까?",
  ui_story_5043_50431401_59_dialog_content = "제가 심판소에서 이런 누명을 쓸 이유는 없습니다!",
  ui_story_5043_50431401_60_dialog_content = "누명인지 아닌지는 금방 알게 되겠죠.",
  ui_story_5043_50431401_61_dialog_content = "증인, 그 후에 무슨 일이 있었죠?",
  ui_story_5043_50431401_62_dialog_content = "방금 그 증언은 확실히 놀라운 사실이긴 하지만,\n이 「목 없는 조각상 연쇄 사건」과는 관계가 없습니다.",
  ui_story_5043_50431401_63_dialog_content = "아, 맞아요! 다시 사건 이야기로 돌아갈게요!",
  ui_story_5043_50431401_64_dialog_content = "슈와브는 가끔씩 암귀 몇 마리를 골라 지하실에서 데리고 나가서 임무를 줬어요...",
  ui_story_5043_50431401_65_dialog_content = "저, 전 도망칠 기회를 잡으려고 항상 적극적으로 나섰어요...",
  ui_story_5043_50431401_66_dialog_content = "그랬더니 역시나 절 고르더군요...",
  ui_story_5043_50431401_67_dialog_content = "슈와브는 달 열기구가 뜰 때마다... 그, 그 아래에 있는 조각상을 부수라고 했어요...",
  ui_story_5043_50431401_68_dialog_content = "오! 이번 사건의 규칙성과 일치하는군!",
  ui_story_5043_50431401_69_dialog_content = "처, 처음 두 번은 심판소 앞과 초원 광장에서 조각상을 부쉈어요...",
  ui_story_5043_50431401_70_dialog_content = "심판소 앞?!",
  ui_story_5043_50431401_71_dialog_content = "안 돼! 내 「애인」아!",
  ui_story_5043_50431401_72_dialog_content = "바이런 씨, 삼가 고인의 명복을 빕니다.",
  ui_story_5043_50431401_73_dialog_content = "근데 일이 잘 풀려서 그런 건지... 세 번째 요구는 전보다 더 어려워졌어요...",
  ui_story_5043_50431401_74_dialog_content = "저, 저한테 이상한 장갑을 끼고 조각상을 부수라고 했어요...",
  ui_story_5043_50431401_75_dialog_content = "장갑?!",
  ui_story_5043_50431401_76_dialog_content = "그리고 일을 마치면 장갑을 그 자리에 남기라고 했죠...",
  ui_story_5043_50431401_77_dialog_content = "그, 그래서 전 다른 암귀들 틈에 섞여서... 천성의 계단으로 갔어요...",
  ui_story_5043_50431401_78_dialog_content = "그러다 도중에 오른손을 레인 심판관한테 잡혀서... 현장에서 체포당할 뻔했어요...",
  ui_story_5043_50431401_79_dialog_content = "다, 다행히 전 장갑을 벗어서 도망칠 수 있었고... 장갑도 그 자리에 남길 수 있었어요...",
  ui_story_5043_50431401_80_dialog_content = "당신이 남긴 장갑이 바로 이것입니까?",
  ui_story_5043_50431401_81_dialog_content = "맞아요! 그거예요!",
  ui_story_5043_50431401_82_dialog_content = "모든 수수께끼가 풀렸다!",
  ui_story_5043_50431401_83_dialog_content = "아무래도 증인 복슬 씨의 증언과 증거가 부합하는 것 같군요.",
  ui_story_5043_50431401_84_dialog_content = "그럼 이제...",
  ui_story_5043_50431401_85_dialog_content = "하, 부합한다고요?",
  ui_story_5043_50431401_86_dialog_content = "전부 사건 기록을 토대로 꾸며낸 이야기일 뿐이잖습니까!",
  ui_story_5043_50431401_87_dialog_content = "지금 말한 내용을 증명할 증거가 하나라도 있습니까?",
  ui_story_5043_50431401_88_dialog_content = "피고, 지금 스스로 죄를 인정한 증인을 믿을 수 없다고 말씀하시는 겁니까?",
  ui_story_5043_50431401_89_dialog_content = "흥, 죄를 인정했다고 반드시 범인인 것이 아닙니다!",
  ui_story_5043_50431401_90_dialog_content = "오히려 누군가 절 모함하기 위해 저 암귀를 매수했다고 의심하는 게 합리적이죠.",
  ui_story_5043_50431401_91_dialog_content = "고작 비천한 목숨 하나 가지고 절 시궁창에 빠트릴 수 있다니, 정말 좋은 거래 아닙니까?",
  ui_story_5043_50431401_92_dialog_content = "내, 내가 뭘 빠트려! 너, 너너너너, 너야말로 날 이렇게 만들었잖아!",
  ui_story_5043_50431401_93_dialog_content = "난 그저 일자리를 찾으러 왔을 뿐인데...\n네 음모에 휘말려서 붙잡히고... 억지로 나쁜 일까지 해버렸어!",
  ui_story_5043_50431401_94_dialog_content = "어제 누가 지하실을 열어주지 않았으면... 난 아마 영원히 자유를 얻지 못했을 거야!",
  ui_story_5043_50431401_95_dialog_content = "음, 아무래도 그 지하실이 중요한 장소인 모양이군.",
  ui_story_5043_50431401_96_dialog_content = "보세요, 아직도 헛소리를 하고 있잖아요!",
  ui_story_5043_50431401_97_dialog_content = "제 장원엔 지하실 같은 건 없습니다!",
  ui_story_5043_50431401_98_dialog_content = "지하실이 있는지 없는지는 사람을 보내서 찾아보면 바로 알 수 있잖아!",
  ui_story_5043_50431401_99_dialog_content = "제 집을 뒤지겠다는 겁니까? 그건 위법행위입니다!",
  ui_story_5043_50431401_100_dialog_content = "살라르 가문은 자신의 사적 비밀을 지킬 권리가 있습니다!",
  ui_story_5043_50431401_101_dialog_content = "그게 무슨...",
  ui_story_5043_50431401_102_dialog_content = "피고의 말이 맞습니다. 저희에게 살라르 장원을 조사할 권리는 없습니다.",
  ui_story_5043_50431401_103_dialog_content = "......",
  ui_story_5043_50431401_104_dialog_content = "증인이 자신의 유죄를 증명할 수 있다면 이야기는 다르겠지만요.",
  ui_story_5043_50431401_105_dialog_content = "뭐?!",
  ui_story_5043_50431401_106_dialog_content = "쳇...",
  ui_story_5043_50431401_107_dialog_content = "피고도 그 점을 염두에 둔 거겠죠? 그러니 조금 전에...",
  ui_story_5043_50431401_108_dialog_content = "죄를 인정했다고 반드시 범인인 것이 아니라고 말한 겁니다.",
  ui_story_5043_50431401_109_dialog_content = "......",
  ui_story_5043_50431401_110_dialog_content = "당신은 그 점에 집착하고 있습니다. 왜냐하면 모든 열쇠가 거기 달려 있기 때문입니다.",
  ui_story_5043_50431401_111_dialog_content = "증인이 범인으로 특정되는 순간, 증인의 모든 발언은 상세한 조사가 필요하게 됩니다.",
  ui_story_5043_50431401_112_dialog_content = "그때부턴 단순한 증언이 아니라 범인의 자백이 되니까요.",
  ui_story_5043_50431401_113_dialog_content = "사람들은 암귀가 악당인 이야기를 믿고,\n사건의 배후엔 남모를 어둠이 숨어 있다고 믿습니다.",
  ui_story_5043_50431401_114_dialog_content = "그리고 심판소는 수색영장을 발부해서 복슬 씨가 말한 모든 내용을 조사하겠죠.",
  ui_story_5043_50431401_115_dialog_content = "그럼 살라르 장원에 지하실이 있는지도 없는지도 모두가 알게 될 겁니다.",
  ui_story_5043_50431401_116_dialog_content = "쳇, 망상은 집어치우세요, 레인. 당신 속셈이 뭔지 알고 있으니까요.",
  ui_story_5043_50431401_117_dialog_content = "시시한 사건과 보잘것없는 암귀를 앞세워서 우리 가문의 비밀을 훔쳐볼 생각이겠죠.",
  ui_story_5043_50431401_118_dialog_content = "그렇게는 안 될 겁니다.",
  ui_story_5043_50431401_119_dialog_content = "뭐야? 지금 내 사건이 시시하다는 거냐?!",
  ui_story_5043_50431401_120_dialog_content = "닥쳐요!",
  ui_story_5043_50431401_121_dialog_content = "뭐...뭐라고...?!",
  ui_story_5043_50431401_122_dialog_content = "당신들을 상대해 주는 것도 여기까지입니다!",
  ui_story_5043_50431401_123_dialog_content = "본 심판소의 대심판관으로서, 저는 증인석의 암귀와 이 사건이 무관하다고 판단합니다.",
  ui_story_5043_50431401_124_dialog_content = "현 상황에서는 증거 불충분으로 심리를 계속할 수 없으므로,\n휴정 후 상세한 조사와 증거 수집을 하도록 하겠습니다.",
  ui_story_5043_50431401_125_dialog_content = "그럼 확실한 증거가 갖춰진 뒤에 다시 심리를 재개하는 것으로 하고...",
  ui_story_5043_50431401_126_dialog_content = "즈, 증명할 수 있어요!",
  ui_story_5043_50431401_127_dialog_content = "!!!",
  ui_story_5043_50431401_128_dialog_content = "지금 여기서... 제 죄를 증명할 수 있다구요!",
  ui_story_5043_50431401_129_dialog_content = "또 꾸며낸 이야기로 절 계속 모함할 생각인가요?",
  ui_story_5043_50431401_130_dialog_content = "증거가 있어요!",
  ui_story_5043_50431401_131_dialog_content = "증인, 그 증거란 무엇입니까?",
  ui_story_5043_50431401_132_dialog_content = "범행 현장에 남긴 장갑이요!",
  ui_story_5043_50431401_133_dialog_content = "...장갑?",
  ui_story_5043_50431401_134_dialog_content = "무, 물론 슈와브가 장갑을 깨끗하게 씻어서 겉으로는 암귀의 흔적이 보이지 않을 거예요...",
  ui_story_5043_50431401_135_dialog_content = "하지만! 조각상을 부수기 전에 제가 장갑 안쪽에 손톱으로 낸 흠집이 있어요...",
  ui_story_5043_50431401_136_dialog_content = "그, 그건 씻어도 없어지지 않아요!",
  ui_story_5043_50431401_137_dialog_content = "뭐라고?!",
  ui_story_5043_50431401_138_dialog_content = "그렇군요. 그럼 그 흠집만 찾아내면 장갑을 꼈던 게 당신임을 증명할 수 있겠군요.",
  ui_story_5043_50431401_139_dialog_content = "즉, 당신이 범인이라는 뜻이 됩니다.",
  ui_story_5043_50431401_140_dialog_content = "네!",
  ui_story_5043_50431401_141_dialog_content = "슈와브 대심판관님, 본건의 핵심 증거물을 조사할 수 있을까요?",
  ui_story_5043_50431401_142_dialog_content = "......",
  ui_story_5043_50431401_143_dialog_content = "장갑을 이리 주시겠습니까?",
  ui_story_5043_50431401_144_dialog_content = "이제 곧 휴정해야 하니 더는 지체하지 않겠습니다. 이번이 마지막 조사입니다.",
  ui_story_5043_50431401_145_dialog_content = "......",
  ui_story_5043_50431401_146_dialog_content = "슈와브 대심판관님?",
  ui_story_5043_50431401_147_dialog_content = "...쳇.",
  ui_story_5043_50431401_148_dialog_content = "그래서 전 <color=#FFB400>사랑이 싫은 겁니다</color>.",
  ui_story_5043_50431401_149_dialog_content = "뭐?!",
  ui_story_5043_50431401_150_dialog_content = "지금 저 말은 그럼...",
  ui_story_5043_50431401_151_dialog_content = "수많은 평범한 자들에게 둘러싸여 사랑받는 건 정말 끔찍합니다.",
  ui_story_5043_50431401_152_dialog_content = "제멋대로 제게 다가오고, 제멋대로 제 사생활을 탐구하죠.",
  ui_story_5043_50431401_153_dialog_content = "그래요, 당신들이 하는 일처럼 말이에요.",
  ui_story_5043_50431401_154_dialog_content = "사랑이 싫다고?",
  ui_story_5043_50431401_155_dialog_content = "물론이죠! 그건 영원히 깨어날 수 없는 악몽 같은 거라고요!",
  ui_story_5043_50431401_156_dialog_content = "또래 여자들에게 둘러싸여 아첨하는 말을 견뎌야 하는 하루하루...",
  ui_story_5043_50431401_157_dialog_content = "학창 시절 책상엔 러브레터가 산더미처럼 쌓였고,\n기념일엔 선물이 온 집을 메울 만큼 쌓였죠.",
  ui_story_5043_50431401_158_dialog_content = "모든 이가 자신을 좋아한다는 게 얼마나 고통스러운 일인지 당신들은 알기나 합니까?!",
  ui_story_5043_50431401_159_dialog_content = "......",
  ui_story_5043_50431401_160_dialog_content = "...뭐라는 거야?",
  ui_story_5043_50431401_161_dialog_content = "나, 나도 모르겠어.",
  ui_story_5043_50431401_162_dialog_content = "일을 하게 되면 조금은 나아질 줄 알았습니다.",
  ui_story_5043_50431401_163_dialog_content = "그런데 이 백야성에서 사랑을 찬미하는 끔찍한 풍조가 일어날 줄 누가 알았겠습니까!",
  ui_story_5043_50431401_164_dialog_content = "게, 게다가 그런 저한테 「연애 심판소」의 대심판관을 하라고요?!",
  ui_story_5043_50431401_165_dialog_content = "그래요, 정말 참을 만큼 참았어요! 제가 그 조각상들을 부쉈습니다!",
  ui_story_5043_50431401_166_dialog_content = "그 천박한 활동의 주최자는 그저 조각상의 문화적인 정취를 빌려\n자신의 활동을 포장하고 싶었던 거겠죠. 그런 건 절대 용납할 수 없습니다!",
  ui_story_5043_50431401_167_dialog_content = "......",
  ui_story_5043_50431401_168_dialog_content = "폭력으로 자신의 주장을 펼치는 당신보다 천박할까요?!",
  ui_story_5043_50431401_169_dialog_content = "결국 당신이 암귀를 보내서 조각상을 부순 거군요?",
  ui_story_5043_50431401_170_dialog_content = "맞아요, 제가 암귀를 보냈어요. 더러운 암귀야말로 저들의 연애 풍조에 딱 맞으니까요!",
  ui_story_5043_50431401_171_dialog_content = "지금 하신 모든 진술을 자백으로 간주해도 되겠습니까?",
  ui_story_5043_50431401_172_dialog_content = "그런 번거로운 절차는 집어치워요, 레인.",
  ui_story_5043_50431401_173_dialog_content = "이 사건은 당신이 이겼습니다. 이미 충분한 증거를 쥐고 있으니까요.",
  ui_story_5043_50431401_174_dialog_content = "제 유일한 실수는 「범행도구」를 인멸하지 않은 겁니다.\n멋대로 떠드는 입을 막았어야 했어요.",
  ui_story_5043_50431401_175_dialog_content = "......",
  ui_story_5043_50431401_176_dialog_content = "아니요, 당신이 진 이유는 그렇게 복잡한 게 아닙니다.",
  ui_story_5043_50431401_177_dialog_content = "유일한 실수가 있다면, 그건 제가 장갑을 조사하지 못하게 한 겁니다.",
  ui_story_5043_50431401_178_dialog_content = "<size=45>뭐라고?!</size>",
  ui_story_5043_50431401_179_dialog_content = "잠깐만! 장갑 안쪽에 결정적인 증거가 있다면서?!",
  ui_story_5043_50431401_180_dialog_content = "설마... 애초에 그런 건 없었다는 거야?",
  ui_story_5043_50431401_181_dialog_content = "휴, 엄청 긴장했잖아. 무사히 끝나서 망정이지.",
  ui_story_5043_50431401_182_dialog_content = "레인, 너 이 자식 사기꾼의 재능이 있잖아?",
  ui_story_5043_50431401_183_dialog_content = "당신들... 절 속인 겁니까?!",
  ui_story_5043_50431401_184_dialog_content = "자, 장갑에 흠집 같은 건 애초에 없었던 거군요!",
  ui_story_5043_50431401_185_dialog_content = "후후, 그뿐만이 아닙니다.",
  ui_story_5043_50431401_186_dialog_content = "우연이 너무 겹쳤다는 생각 안 듭니까?",
  ui_story_5043_50431401_187_dialog_content = "유일하게 당신의 집에서 도망칠 수 있었던 암귀가,\n마침 조각상 파괴 임무를 받은 암귀라니...",
  ui_story_5043_50431401_188_dialog_content = "설마...",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>어제</color>",
  ui_story_5043_50431401_190_dialog_content = "너도 야근할 거냐?",
  ui_story_5043_50431401_191_dialog_content = "아직 조사하지 못한 게 있어서요.\n개정 전까지 자료를 자세히 검토해 두는 건 당연한 일입니다.",
  ui_story_5043_50431401_192_dialog_content = "오히려 당신이 야근을 하다니 의외인데요.",
  ui_story_5043_50431401_193_dialog_content = "쳇. 서민 신입. 지금 심판관으로서의 내 프로 의식을 의심하는 거냐?\n아니면 내가 티나와의 우정을 내팽개칠 줄 알았나?",
  ui_story_5043_50431401_194_dialog_content = "뭐, 됐어. 오늘은 말다툼하지 말고 사건에 집중하자고...",
  ui_story_5043_50431401_195_dialog_content = "시, 실례합니다! 아직 업무 시간인가요?",
  ui_story_5043_50431401_196_dialog_content = "뭐야? 암귀?!",
  ui_story_5043_50431401_197_dialog_content = "심판소까지 제 발로 찾아오다니 배짱도 좋군! 그런다고 봐줄 것 같으냐!",
  ui_story_5043_50431401_198_dialog_content = "때, 때리지 마세요! 전 범죄 신고하러 온 거예요!",
  ui_story_5043_50431401_199_dialog_content = "하아? 암귀가 범죄를 신고해?",
  ui_story_5043_50431401_200_dialog_content = "한번 들어봅시다. 어차피 한 마리잖아요. 처치하는 것도 어렵지 않고 말입니다.",
  ui_story_5043_50431401_201_dialog_content = "좋아, 그럼 얘기해 봐라. 뭘 신고할 건데?",
  ui_story_5043_50431401_202_dialog_content = "네!",
  ui_story_5043_50431401_203_dialog_content = "머, 먼저 자기소개부터 할게요...",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>10분 후</color>",
  ui_story_5043_50431401_205_dialog_content = "...그러다 결국 다른 암귀들이랑 같이... 지, 지하실에 갇혔어요...",
  ui_story_5043_50431401_206_dialog_content = "그런 일이 있었다고? 어쩐지 지하실에 왜 암귀가 있었나 했네.",
  ui_story_5043_50431401_207_dialog_content = "네! 저, 전 그때 지하실에서 도망친 거예요!",
  ui_story_5043_50431401_208_dialog_content = "뭐야?!",
  ui_story_5043_50431401_209_dialog_content = "그럼 우리가 널 구해준 셈이잖아!",
  ui_story_5043_50431401_210_dialog_content = "그, 그런가요! 정말 고마워요!",
  ui_story_5043_50431401_211_dialog_content = "그래서 당신은 슈와브를 암귀 감금으로 고소하고 싶은 겁니까?",
  ui_story_5043_50431401_212_dialog_content = "맞아요! 무, 물론 백야성의 법이 암귀를 보호하지 않는 건 알아요...\n하지만... 그 사람은 분명히 더 큰 음모를 꾸미고 있어요!",
  ui_story_5043_50431401_213_dialog_content = "그렇다면 일은 간단하지. 내일 재판에 출석해서 방금 했던 얘기를 다시 하면 된다.",
  ui_story_5043_50431401_214_dialog_content = "모두에게 저 빌어먹을 슈와브가 뒤에서 무슨 짓거리를 했는지 알려주는 거다!",
  ui_story_5043_50431401_215_dialog_content = "네! 알겠어요!",
  ui_story_5043_50431401_216_dialog_content = "하지만 증거가 있습니까?",
  ui_story_5043_50431401_217_dialog_content = "즈, 증거요?",
  ui_story_5043_50431401_218_dialog_content = "잊지 마세요. 당신은 암귀입니다.",
  ui_story_5043_50431401_219_dialog_content = "저흰 슈와브의 지하실에 가봤기 때문에 지금 그 말을 믿지만, 다른 사람들은 어떨까요?",
  ui_story_5043_50431401_220_dialog_content = "증거를 제시하지 못하는 상황에서 슈와브가 사실을 부인한다면,\n우린 다른 방법이 없습니다.",
  ui_story_5043_50431401_221_dialog_content = "심지어 그의 반격을 받게 되겠죠.",
  ui_story_5043_50431401_222_dialog_content = "그러니 이건 굉장히 위험한 일인 겁니다.",
  ui_story_5043_50431401_223_dialog_content = "미, 미안해요. 증거는 없어요...",
  ui_story_5043_50431401_224_dialog_content = "도망치는 것만으로도... 이미 힘을 다 써버렸는걸요...",
  ui_story_5043_50431401_225_dialog_content = "어이, 이런 중대한 일을 증거가 없다는 이유로 그냥 넘어갈 순 없잖아!",
  ui_story_5043_50431401_226_dialog_content = "아니면 살라르 장원에 한 번 더 잠입하는 건 어때?",
  ui_story_5043_50431401_227_dialog_content = "잠깐만요, 그렇게 고생하지 않아도 될 것 같네요. 좋은 방법이 떠올랐습니다...",
  ui_story_5043_50431401_228_dialog_content = "뭐지?",
  ui_story_5043_50431401_229_dialog_content = "증거가 없다면, 심판소에서 녀석이 스스로 죄를 인정하게 만들면 됩니다.",
  ui_story_5043_50431401_230_dialog_content = "하아? 지금 무슨 꿈이라도 꾸는 거냐?",
  ui_story_5043_50431401_231_dialog_content = "증거가 없는데 녀석이 뭘 가지고 인정해?",
  ui_story_5043_50431401_232_dialog_content = "녀석이 암귀로 뭘 하고 있었다고 생각하십니까?",
  ui_story_5043_50431401_233_dialog_content = "음... 그 정도의 위험을 무릅쓴 이상, 분명히 상당한 음모가 있는 거겠지.",
  ui_story_5043_50431401_234_dialog_content = "전 녀석이 암귀에게 명령해서 조각상을 부수고 있었다고 생각합니다.",
  ui_story_5043_50431401_235_dialog_content = "호오? 왜 그렇게 생각하지?",
  ui_story_5043_50431401_236_dialog_content = "천성의 계단 때 일을 기억하십니까? 전 그때 범인의 손을 잡았습니다.",
  ui_story_5043_50431401_237_dialog_content = "하지만 여러분이 암귀를 쓰러트리고 나자, 주변엔 아무도 없었습니다.",
  ui_story_5043_50431401_238_dialog_content = "천성의 계단 위는 넓은 곳입니다. \n그 짧은 시간에 저희 시야에서 벗어나는 건 불가능합니다.",
  ui_story_5043_50431401_239_dialog_content = "하지만 범인이 암귀였다면 이야기는 다르겠죠.",
  ui_story_5043_50431401_240_dialog_content = "오, 이해했어! 암귀를 쓰러트렸을 때, 범인이었던 암귀도 같이 쓰러트렸다는 말이 되겠군!",
  ui_story_5043_50431401_241_dialog_content = "그래서 지금까지 잡히지 않았던 거다!",
  ui_story_5043_50431401_242_dialog_content = "네, 그럴 가능성이 가장 높다고 할 수 있겠죠.",
  ui_story_5043_50431401_243_dialog_content = "그럼 넌 그 단서를 어떻게 활용할 생각이지?",
  ui_story_5043_50431401_244_dialog_content = "복슬 씨를 범인으로 만드는 겁니다.",
  ui_story_5043_50431401_245_dialog_content = "그리고 저희가 추측한 진상을 복슬 씨가 증언하게 하면 됩니다.",
  ui_story_5043_50431401_246_dialog_content = "만약 우리의 추측이 진상에 가깝다면,\n슈와브는 분명히 복슬 씨가 자신이 보낸 암귀라고 믿을 겁니다.",
  ui_story_5043_50431401_247_dialog_content = "그런 거였냐! 우리가 중요한 증인을 확보했다고 믿게 만들어서,\n녀석이 죄를 인정할 수밖에 없도록 유도하겠다는 말이군!",
  ui_story_5043_50431401_248_dialog_content = "네, 일종의 심리전이죠.",
  ui_story_5043_50431401_249_dialog_content = "복슬 씨, 심판소에서 거짓말을 할 수 있겠습니까?",
  ui_story_5043_50431401_250_dialog_content = "슈, 슈와브의 악행을 폭로할 수 있다면... 할게요!",
  ui_story_5043_50431401_251_dialog_content = "좋습니다. 그렇다면 오늘 밤 안에 제가 해주는 말을 모두 외워야 합니다.",
  ui_story_5043_50431401_252_dialog_content = "그리고 이 작전의 성공을 위해 함께 머리를 써 봅시다.",
  ui_story_5043_50431401_253_dialog_content = "녀석이 진짜라고 믿을 만한 결정적인 증거를 만들어내는 겁니다.",
  ui_story_5043_50431401_254_dialog_content = "이...이 비열한 놈들!",
  ui_story_5043_50431401_255_dialog_content = "당신이 쓴 방법 그대로 갚아줬을 뿐입니다만.",
  ui_story_5043_50431401_256_dialog_content = "세상에... 설마 진범이 대심판관이었다니!",
  ui_story_5043_50431401_257_dialog_content = "암담하도다... 심판소는 부패했다!",
  ui_story_5043_50431401_258_dialog_content = "하지만 진상을 밝힌 것도 심판소잖아요?",
  ui_story_5043_50431401_259_dialog_content = "어둠이 있으니까, 그 어둠을 깨트릴 힘이 필요한 거예요!",
  ui_story_5043_50431401_260_dialog_content = "이제 끝내자고, 슈와브 대심판관, 마지막 순간엔 체면을 지켜야지.",
  ui_story_5043_50431401_261_dialog_content = "흥, 마지막 순간이라고?",
  ui_story_5043_50431401_262_dialog_content = "레인, 당신에게도 유일한 실수가 하나 있었는데, 그게 뭔지 알고 있나요?",
  ui_story_5043_50431401_263_dialog_content = "...저 말입니까?",
  ui_story_5043_50431401_264_dialog_content = "진상을 밝히면 모든 게 끝난다고 생각하면 큰 오산입니다.",
  ui_story_5043_50431401_265_dialog_content = "본 심판소는 레인, 티나, 마티외 3인의 심판관을 본건의 범인으로 기소합니다!",
  ui_story_5043_50431401_266_dialog_content = "이상 피고인 3인에 대한 판결을 선고한 후 체포하겠습니다!",
  ui_story_5043_50431401_267_dialog_content = "지금 무슨 헛소리를 하는 겁니까! 슈와브!",
  ui_story_5043_50431401_268_dialog_content = "여기 있는 모두가 들었습니다. 당신이야말로 진범입니다!",
  ui_story_5043_50431401_269_dialog_content = "이런, 사건에 대한 의견이 아직 일치하지 않는 모양이군요.",
  ui_story_5043_50431401_270_dialog_content = "그렇다면 합의체 규정에 따라 다수결에 의한 판결을 실시하겠습니다.",
  ui_story_5043_50431401_271_dialog_content = "합의체라고요?!",
  ui_story_5043_50431401_272_dialog_content = "잠깐만... 저건...!",
  ui_story_5043_50431401_273_dialog_content = "암귀잖아?! 언제 나타난 것이냐?!",
  ui_story_5043_50431401_274_dialog_content = "레인, 당신의 최종 의견을 듣도록 하죠.",
  ui_story_5043_50431401_275_dialog_content = "...슈와브 살라르가 본 사건의 진범입니다.",
  ui_story_5043_50431401_276_dialog_content = "좋습니다. 그럼 그의 결론에 동의하는 분은 손을 들어주세요.",
  ui_story_5043_50431401_277_dialog_content = "어디 보자... 레인, 마티외, 티나, 하급 재판관...",
  ui_story_5043_50431401_278_dialog_content = "좋습니다, 4표로군요. 많은 분들이 당신의 진술을 믿은 모양이네요.",
  ui_story_5043_50431401_279_dialog_content = "그게 진실이기 때문입니다!",
  ui_story_5043_50431401_280_dialog_content = "하지만 전 레인, 티나, 마티외, 이 3인의 심판관이 진범이라고 생각합니다.",
  ui_story_5043_50431401_281_dialog_content = "제 결론에 동의하는 합의체 구성원은 책상을 두드려 주세요.",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5043_50431401_286_dialog_content = "저 사람들...",
  ui_story_5043_50431401_287_dialog_content = "4표네요.",
  ui_story_5043_50431401_288_dialog_content = "여기에 저 슈와브 살라르 본인의 한 표를 포함해서 총 5표입니다.",
  ui_story_5043_50431401_289_dialog_content = "아무래도 제 판결에 더 찬성이 많은 것 같네요.",
  ui_story_5043_50431401_290_dialog_content = "배...배심원을 전부 자기 사람으로 바꿔치기했군요!",
  ui_story_5043_50431401_291_dialog_content = "자기 사람? 저 가면 너머에 있는 건 어차피 다 암귀일 거다!",
  ui_story_5043_50431401_292_dialog_content = "합의 결과가 나왔습니다! 결과에 따라 본 심판소는 최종 판결을 선고하겠습니다!",
  ui_story_5043_50431401_293_dialog_content = "주문. 피고인 1, 피고인 2, 피고인 3에게...",
  ui_story_5043_50431401_294_dialog_content = "유죄를 선고한다!",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_5043_50431401_296_dialog_content = "저 배심원들 뭔가 이상해!",
  ui_story_5043_50431401_X296_dialog_content = "엄청난 다크매터가 느껴져! 녀석들은 진짜 암귀야!",
  ui_story_5043_50431401_X297_dialog_content = "뭐, 뭐라고?!",
  ui_story_5043_50431401_X298_dialog_content = "말도 안 돼... 나와 함께 앉아 있던 배심원들이 모두 암귀였다는 것이냐?!",
  ui_story_5043_50431401_297_dialog_content = "배심원 여러분, 수고하셨습니다.",
  ui_story_5043_50431401_298_dialog_content = "청중으로서뿐만 아니라, 제 「기사」로서 훌륭하게 법을 실행하셨군요.",
  ui_story_5043_50431401_299_dialog_content = "이에 따라 심판소의 권한에 따라 판결을 이행하겠습니다...",
  ui_story_5043_50431401_300_dialog_content = "범인을 체포하세요!",
  ui_story_5043_50431401_301_dialog_content = "그어어...",
  ui_story_5043_50431401_302_dialog_content = "이런, 저 가면 쓴 녀석들, 평범한 암귀는 아닌 것 같아!",
  ui_story_5043_50431401_303_dialog_content = "그래, 슈와브가 준비한 비장의 카드라면, 절대 만만하지 않을 거야.",
  ui_story_5043_50431401_304_dialog_content = "어이, 이 자식! 말로 안 되니까 힘으로 밀어붙일 작정이냐!",
  ui_story_5043_50431401_305_dialog_content = "곤란해요. 심판소의 실내 구조상 저쪽에 유리해요. 이대로는 우리가 포위될 거예요.",
  ui_story_5043_50431401_306_dialog_content = "명백히 우리가 옳은데... 심판소에서조차 어둠이 정의를 뒤덮다니...",
  ui_story_5043_50431401_307_dialog_content = "바보! 이긴 쪽이 정의가 되는 거예요! 지면 그저 「피해자」일 뿐이라구요!",
  ui_story_5043_50431401_308_dialog_content = "일단 도망쳐요!",
  ui_story_5043_50431401_309_dialog_content = "그래! 멍하니 있지 마!",
  ui_story_5043_50431401_310_dialog_content = "다들 빨리 이쪽으로 와!",
  ui_story_5043_50431402_1_dialog_content = "사람들은 사랑의 진리를 높이 하늘에 올리지~♪",
  ui_story_5043_50431402_2_dialog_content = "아름다운 가죽을 씌워 만인을 즐겁게 하지~♪",
  ui_story_5043_50431402_3_dialog_content = "사랑이 얼마나 아름다운지 상상하는 사람들~♪",
  ui_story_5043_50431402_4_dialog_content = "꽃피는 순간을 위해 옷이 더러워져도 상관 안 해~♪",
  ui_story_5043_50431402_5_dialog_content = "오늘 달 열기구를 터트린다는 게 진짜야?",
  ui_story_5043_50431402_6_dialog_content = "맞아! 다들 그걸 보러 온 거라고.",
  ui_story_5043_50431402_7_dialog_content = "열기구 안엔 꽃이랑 종이 공예품, 갖가지 색깔의 비눗방울이 들어 있대.",
  ui_story_5043_50431402_8_dialog_content = "사랑을 찬미하는 활동이니까, 불꽃놀이 같은 것보다 훨씬 예쁠 거야!",
  ui_story_5043_50431402_9_dialog_content = "어라? 심판소 입구에서 사람들이 뛰어나오는데?",
  ui_story_5043_50431402_10_dialog_content = "뭐 하는 거지?",
  ui_story_5043_50431402_11_dialog_content = "휴, 겨우 도망쳤네.",
  ui_story_5043_50431402_12_dialog_content = "방심하면 안 돼. 아직 쫓아오고 있어!",
  ui_story_5043_50431402_13_dialog_content = "......",
  ui_story_5043_50431402_14_dialog_content = "으으, 끈질긴 놈들!",
  ui_story_5043_50431402_15_dialog_content = "이러다 움브라톤까지 도망쳐야 되는 건 아니겠지?",
  ui_story_5043_50431402_16_dialog_content = "잠시만요! 시위대가 이쪽으로 오고 있는 것 같아요!",
  ui_story_5043_50431402_17_dialog_content = "하필 이럴 때...",
  ui_story_5043_50431402_18_dialog_content = "더는 도망칠 수 없어요. 이러다간 암귀가 백성들을 해칠 거예요.",
  ui_story_5043_50431402_19_dialog_content = "그래, 여기서 막아야만 해.",
  ui_story_5043_50431402_20_dialog_content = "PlayerName, 넌 가서 시위대를 대피시켜 줘.",
  ui_story_5043_50431402_21_dialog_content = "응, 지금 바로 갈게...",
  ui_story_5043_50431402_22_dialog_content = "저들은 쇼를 보러 온 겁니다. 전대미문의 멋진 쇼를 말이죠.",
  ui_story_5043_50431402_23_dialog_content = "여러분은 사랑을 찬미하는 풍조에 찬물을 끼얹을 생각인가요?",
  ui_story_5043_50431402_24_dialog_content = "빌어먹을 자식, 빈정거리는 소리밖에 못 하는 거냐!",
  ui_story_5043_50431402_25_dialog_content = "아니요, 전 그저 진심으로 쇼가 순조롭게 진행되길 바랄 뿐이에요.",
  ui_story_5043_50431402_26_dialog_content = "이 터무니없는 풍조엔 그에 걸맞게 우스꽝스러운 클라이맥스가 있어야죠.",
  ui_story_5043_50431402_27_dialog_content = "<size=45>자, 여러분! 이쪽으로 오세요!</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>쇼가 시작됩니다!</size>",
  ui_story_5043_50431402_29_dialog_content = "...슈와브, 대체 뭘 할 생각이지?",
  ui_story_5043_50431402_30_dialog_content = "...안 돼요! 우리 활동을 망치려는 게 분명해요!",
  ui_story_5043_50431402_31_dialog_content = "인파가 몰려온다! 암귀한테 가는 걸 막아!",
  ui_story_5043_50431402_32_dialog_content = "알겠어요! 제가 사람들을 지킬게요!",
  ui_story_5043_50431402_33_dialog_content = "그렇게 긴장할 거 없습니다. 이건 그냥 쇼일 뿐이니까요.",
  ui_story_5043_50431402_34_dialog_content = "오늘 달 열기구를 터트리겠다고 하지 않았습니까?",
  ui_story_5043_50431402_35_dialog_content = "그럼 여러분께 보여드리죠.\n여러분이 올려다보던 사랑 속에 대체 무엇이 숨겨져 있었는지.",
  ui_story_5043_50431402_36_dialog_content = "당신 설마...",
  ui_story_5043_50431402_37_dialog_content = "허황된 신앙이 꽃을 피울 때가 되었습니다.",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>퍼어엉──!</color>",
  ui_story_5043_50431402_39_dialog_content = "으아아아아아아악!",
  ui_story_5043_50431402_40_dialog_content = "여러분! 조심하세요!",
  ui_story_5043_50431402_41_dialog_content = "뭐야, 하늘에서...",
  ui_story_5043_50431402_42_dialog_content = "제 클로버 꽃다발... 옛 기념일의 선물이... 어째서...",
  ui_story_5043_50431402_43_dialog_content = "이건... 시든 꽃이잖아?",
  ui_story_5043_50431402_44_dialog_content = "네, 사랑을 상징하는 레드 클로버네요...",
  ui_story_5043_50431402_45_dialog_content = "시든 꽃이 온 하늘에 가득해...",
  ui_story_5043_50431402_46_dialog_content = "정말 보기 흉하네. 이런 걸 보니까 기분이 정말 최악이야.",
  ui_story_5043_50431402_47_dialog_content = "달 열기구가 터지고 볼 수 있는 게 고작 이런 장면이었던 거야?",
  ui_story_5043_50431402_48_dialog_content = "네, 그렇습니다.",
  ui_story_5043_50431402_49_dialog_content = "슈와브, 다가오지 마세요!",
  ui_story_5043_50431402_50_dialog_content = "사랑이란 애초에 이런 게 아니었나요?",
  ui_story_5043_50431402_51_dialog_content = "알맹이를 모를 땐 한없는 상상을 통해 가장 아름다운 모습으로 미화해 버리죠.",
  ui_story_5043_50431402_52_dialog_content = "마치 하늘에 떠 있는 달처럼, 손에도 닿지 않고, 가늠할 수 없는...\n가장 신비롭고 아름다운 것이라고 상상하겠죠.",
  ui_story_5043_50431402_53_dialog_content = "그래요. 그 아름다움은 모두 무지에서 비롯되었을 뿐이에요.\n진짜 모습을 아무도 모르기 때문에 만들어진 겁니다.",
  ui_story_5043_50431402_54_dialog_content = "자, 이제 모두가 눈으로 보았군요.",
  ui_story_5043_50431402_55_dialog_content = "사랑 같은 건 애초에 그 정도뿐인 겁니다.",
  ui_story_5043_50431402_56_dialog_content = "터무니없는 축제의 소란이 지나가고 남긴 난잡한 잔해에 불과하죠.",
  ui_story_5043_50431402_57_dialog_content = "그리고 이제 달을 볼 일은 다시는 없을 겁니다.",
  ui_story_5043_50431402_58_dialog_content = "그러게... 이제 다시는 달 열기구를 못 보게 됐잖아.",
  ui_story_5043_50431402_59_dialog_content = "못 보면 어때? 시든 꽃다발밖에 안 들어 있는 쓰레기봉투일 뿐이었잖아...",
  ui_story_5043_50431402_60_dialog_content = "그, 그건 궤변이에요! 분명히 당신이 열기구의 내용물을 미리 바꾼 거겠죠!",
  ui_story_5043_50431402_61_dialog_content = "전 열기구의 내용물을 건드리지 않았습니다.\n그저 열기구를 보호하던 루미나틱스를 파괴했을 뿐이죠.",
  ui_story_5043_50431402_62_dialog_content = "당신...!",
  ui_story_5043_50431402_63_dialog_content = "왜 그러시죠? 당신은 루미나틱스로 생화를 시들지 않게 유지하면서\n대중을 속이려고 했잖아요.",
  ui_story_5043_50431402_64_dialog_content = "전 그저 진상을 밝혔을 뿐이에요.",
  ui_story_5043_50431402_65_dialog_content = "대중들이 아름다움을 볼 수 있는 건, 누군가 추함을 감당하고 있기 때문이라는 걸요.",
  ui_story_5043_50431402_66_dialog_content = "마치 절 갈망하는 백합꽃들이 사랑의 달콤함을 누릴 수 있는 건,\n제가 그녀들의 일방적인 마음을 참아주고 있기 때문인 것처럼 말이죠.",
  ui_story_5043_50431402_67_dialog_content = "사랑의 진면목이... 그런 건가요...?",
  ui_story_5043_50431402_68_dialog_content = "너무 무거운 사랑은... 오히려 그 사람에게 부담을 주고 마는 건가요...",
  ui_story_5043_50431402_69_dialog_content = "맞아요. 이제 당신도 그거 하나는 배웠겠죠.",
  ui_story_5043_50431402_70_dialog_content = "......",
  ui_story_5043_50431402_71_dialog_content = "(설마 저도... 같은 잘못을 한 건 아니었을까요...)",
  ui_story_5043_50431402_72_dialog_content = "아니야, 티나! 녀석의 번지르르한 말에 속지 마!",
  ui_story_5043_50431402_73_dialog_content = "네?",
  ui_story_5043_50431402_74_dialog_content = "슈와브가 하는 말이 사랑의 전부라고 누가 말할 수 있는데?",
  ui_story_5043_50431402_75_dialog_content = "똑같은 일이라도 모두가 느끼는 감정은 다른 법이잖아.",
  ui_story_5043_50431402_76_dialog_content = "난 사랑의 진상 같은 건 잘 몰라. 하지만 적어도 저 활동 속에서\n사람들이 항상 즐거워한다는 건 느낄 수 있었어! 그거면 된 거잖아!",
  ui_story_5043_50431402_77_dialog_content = "게다가 저 녀석은 애초에 사랑 같은 건 해본 적도 없잖아?!",
  ui_story_5043_50431402_78_dialog_content = "그러면서 무슨 자격으로 사랑에 대해 큰소리를 치냐고!",
  ui_story_5043_50431402_79_dialog_content = "큭...",
  ui_story_5043_50431402_80_dialog_content = "사랑 같은 더러운 걸 제가 왜 건드려야 하죠?!",
  ui_story_5043_50431402_81_dialog_content = "그래요! PlayerName 씨 말이 맞아요!",
  ui_story_5043_50431402_82_dialog_content = "애초에 진상 같은 건 존재하지 않았던 거예요.\n당신은 그저 가장 나쁜 결과를 확대해석했을 뿐이라구요!",
  ui_story_5043_50431402_83_dialog_content = "게다가 아름다운 걸 상상하는 과정은 사랑이 아닌가요?",
  ui_story_5043_50431402_84_dialog_content = "사랑은 애초에 심판소에서의 판결과는 달라요.\n결과만으로 모든 걸 말할 수 있는 건 아니에요!",
  ui_story_5043_50431402_85_dialog_content = "짝사랑, 고백, 교제, 그리고 이별까지...\n그런 모든 감정의 접촉이 전부 사랑의 일부분인 거예요!",
  ui_story_5043_50431402_86_dialog_content = "슈와브, 당신은 사랑이 뭔지 전혀 이해하지 못했어요!",
  ui_story_5043_50431402_87_dialog_content = "훗. 확실히 당신 말대로 전 사랑을 이해하지 못한 건지도 모르겠네요.",
  ui_story_5043_50431402_88_dialog_content = "대체 사랑의 어디에 당신들이 빠져들 만한 가치가 있는지, 전 이해가 안 됩니다.",
  ui_story_5043_50431402_89_dialog_content = "제겐 그저 귀찮은 벌레처럼, 제 조용한 삶을 어지럽히고,\n타인이 제 생활에 간섭할 이유를 주는 것에 불과한걸요.",
  ui_story_5043_50431402_90_dialog_content = "아니, 생활뿐만이 아니에요. 가장 끔찍한 건 그게 제 일에도 악영향을 미치고,\n백야성의 공정함조차 흔들었다는 겁니다!",
  ui_story_5043_50431402_91_dialog_content = "왜 그렇게 말하는 거죠?",
  ui_story_5043_50431402_92_dialog_content = "조금의 가치도 없는 그 감정 때문에 주변 사람들은 하나둘씩 이성을 잃었죠.",
  ui_story_5043_50431402_93_dialog_content = "게다가 거기서 그치지 않고, 법의 본질을 거스르는 「연애 심판소」까지 탄생했습니다!",
  ui_story_5043_50431402_94_dialog_content = "지금까지 사랑이 뭘 초래했는지 생각해 보세요.\n애정은 죄인이 죄를 면할 핑계가 되고, 무고한 자에게 누명을 씌웠습니다.",
  ui_story_5043_50431402_95_dialog_content = "이는 백야성이 수백 년간 쌓아 온 법 제도에 대한 모독입니다!",
  ui_story_5043_50431402_96_dialog_content = "그러니 전 맞서 싸워야 했습니다. 심판소에 서서 이 사악한 풍조에 맞섰습니다.",
  ui_story_5043_50431402_97_dialog_content = "제가 한 모든 일은 모든 사랑의 요소를 배제하는 심판소를 세우기 위해서입니다.",
  ui_story_5043_50431402_98_dialog_content = "그러기 위해선 저와 생각을 함께하는 배심원이 필요했죠.\n저들의 의지는 그 어떤 감정에도 흔들려서는 안 됩니다.",
  ui_story_5043_50431402_99_dialog_content = "그리고 마침 이 추악한 괴물들은 그 조건을 충족하더군요.",
  ui_story_5043_50431402_100_dialog_content = "......",
  ui_story_5043_50431402_101_dialog_content = "그런 생각을 하고 있었다니...",
  ui_story_5043_50431402_102_dialog_content = "극단적인 자기주장에 불과해.",
  ui_story_5043_50431402_103_dialog_content = "이런 자는 이익을 탐하는 죄인보다 더 무서운 법이야.",
  ui_story_5043_50431402_104_dialog_content = "자, 사랑에 관한 시시한 이야기는 여기까지 하도록 하죠.",
  ui_story_5043_50431402_105_dialog_content = "여러분도 저와 마찬가지로 사건과 그 판결에 주의를 돌려 주셨으면 좋겠네요.",
  ui_story_5043_50431402_106_dialog_content = "잊으시면 안 됩니다. 당신들은 모두 <color=#FFB400>유죄</color>입니다!",
  ui_story_5043_50431402_107_dialog_content = "다들 저기 좀 봐!",
  ui_story_5043_50431402_108_dialog_content = "심판소에서 암귀들이 튀어나오고 있어!",
  ui_story_5043_50431402_109_dialog_content = "오늘 운수가 왜 이래?! 빨리 튀어!",
  ui_story_5043_50431402_110_dialog_content = "이런! 슈와브가 또 손을 썼어!",
  ui_story_5043_50431402_111_dialog_content = "백성들 앞에서 암귀를 불러내다니, 이미 완전히 미쳐버렸어.\n이제 곧 경비병이 녀석을 체포할 거야.",
  ui_story_5043_50431402_112_dialog_content = "하지만 지금은 우리끼리 이 상황을 수습해야 해.\n무고한 백성들이 해를 입게 해선 안 돼.",
  ui_story_5043_50431402_113_dialog_content = "그건 그렇지만... 저 석고상 가면 쓴 암귀들은 상대하기 꽤 힘든 것 같아...",
  ui_story_5043_50431402_114_dialog_content = "제게 맡겨주세요.",
  ui_story_5043_50431402_115_dialog_content = "캠벨가의 명예를 걸고...",
  ui_story_5043_50431402_116_dialog_content = "「신의 손」의 힘을 걸고 싸우겠어요!",
  ui_story_5043_50431402_117_dialog_content = "우와... 엄청난 루미나야!",
  ui_story_5043_50431402_118_dialog_content = "이 위력이라면 정말로...",
  ui_story_5043_50431402_119_dialog_content = "하아암──",
  ui_story_5043_50431402_120_dialog_content = "뭐?! 이럴 때 웬 하품인데?!",
  ui_story_5043_50431402_121_dialog_content = "안 되겠어요... 오늘은 벌써... 너무 오래... 깨어 있었어요...",
  ui_story_5043_50431402_122_dialog_content = "기사들이여, 저들을 잡으세요.",
  ui_story_5043_50431402_123_dialog_content = "이럴 때 공격하다니 비겁하다!",
  ui_story_5043_50431402_124_dialog_content = "티나! 정신 차려!",
  ui_story_5043_50431402_125_dialog_content = "네... 신의 손으로 제가...",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>콰당──</color>",
  ui_story_5043_50431402_127_dialog_content = "싸움은 시작도 안 했는데 잠들어 버리면 어떡해!",
  ui_story_5043_50431402_128_dialog_content = "어쩌지?! 이런 데서 자면 너무 위험하잖아!",
  ui_story_5043_50431402_129_dialog_content = "티나, 일어나세요! 적이 옵니다!",
  ui_story_5043_50431402_130_dialog_content = "레인 씨 머리 위에... 별이... 보여요...",
  ui_story_5043_50431402_131_dialog_content = "별은 그만 보고! 일어나 싸울 때입니다!",
  ui_story_5043_50431402_132_dialog_content = "안... 되겠어요...",
  ui_story_5043_50431402_133_dialog_content = "자, 입을 열고 이걸 삼키세요.",
  ui_story_5043_50431402_134_dialog_content = "이럴 때 뭘 먹이는 거야?! 그건... 초콜릿?",
  ui_story_5043_50431402_135_dialog_content = "전 이제...",
  ui_story_5043_50431402_136_dialog_content = "어떡해... 적이 눈앞까지 왔다고...",
  ui_story_5043_50431402_137_dialog_content = "잠에서 깼어요!",
  ui_story_5043_50431402_138_dialog_content = "하아?!",
  ui_story_5043_50431402_139_dialog_content = "변화가 너무 심하잖아!",
  ui_story_5043_50431402_140_dialog_content = "훗, 당신들은 돌직구밖에 모르는 건가요? 그래서는 원하는 감정을 얻을 수 없다구요!",
  ui_story_5043_50431402_141_dialog_content = "제가 어떻게 해야 하는지 가르쳐 드릴게요!",
  ui_story_5043_50431402_142_dialog_content = "뭐? 어떻게 해야 되는데?",
  ui_story_5043_50431402_143_dialog_content = "잊으셨나요? 여러분이 제게 가르쳐 주셨잖아요.",
  ui_story_5043_50431402_144_dialog_content = "상대의 마음을 얻는 데는 다양한 방법이 있죠.\n물론...<color=#FFB400>적극적으로 고백</color>하는 방법도 포함이에요!",
  ui_story_5043_50431402_145_dialog_content = "레인 씨, 당신 말이 맞았어요.\n적극적으로 나서서 상대의 주의력을 끄는 건 아주 중요해요!",
  ui_story_5043_50431402_X145_dialog_content = "괴물들을 사람들이 떨어진 곳으로 유인해요!",
  ui_story_5043_50431402_146_dialog_content = "네...?",
  ui_story_5043_50431402_147_dialog_content = "조각상을 뒤집어쓴 녀석들! 받아라!",
  ui_story_5043_50431402_148_dialog_content = "그어어...",
  ui_story_5043_50431402_149_dialog_content = "「신의 손」의 인사가 마음에 들었길 바랄게요~",
  ui_story_5043_50431402_X149_dialog_content = "그어어어!",
  ui_story_5043_50431402_X150_dialog_content = "그 정도로는 제 기사를 쓰러트릴 수 없습니다.\n기사들이여, 계속 공격하세요!",
  ui_story_5043_50431402_150_dialog_content = "다음은 마티외 씨가 가르쳐 주신 방법이에요. 기억하시나요?",
  ui_story_5043_50431402_151_dialog_content = "적극적인 것만으론 부족해요. <color=#FFB400>자신을 숨기는 법</color>도 알아야 하죠!",
  ui_story_5043_50431402_152_dialog_content = "물론 기억하지! 엄호는 나한테 맡기라고!",
  ui_story_5043_50431402_153_dialog_content = "자! 빨리 벽 뒤로 숨어라!",
  ui_story_5043_50431402_154_dialog_content = "훗, 겨우 이 정도 좌절로 포기하다니,\n당신들이 말하는 사랑은 정말 불쌍할 만큼 나약하네요.",
  ui_story_5043_50431402_155_dialog_content = "방금까지 백성들을 지키겠다고 하지 않았습니까?",
  ui_story_5043_50431402_156_dialog_content = "그어어...",
  ui_story_5043_50431402_157_dialog_content = "캬악?",
  ui_story_5043_50431402_158_dialog_content = "역시 못 찾고 있네요!",
  ui_story_5043_50431402_159_dialog_content = "자세히 보니까 저 가면이 약점일 것 같은데요?",
  ui_story_5043_50431402_160_dialog_content = "그러게, 저 아래 대체 어떤 얼굴이 숨어있는지 꼭 봐야겠어!",
  ui_story_5043_50431402_161_dialog_content = "그리고 바로 이럴 때 세 번째 방법을 쓰는 거예요!",
  ui_story_5043_50431402_162_dialog_content = "밀고 당기면서 균형을 잡는 <color=#FFB400>탐색의 과정</color>도 필요해요!",
  ui_story_5043_50431402_163_dialog_content = "마지막 걸음을 내딛기 전에 상대를 확실히 파악하는 게 중요하니까요!",
  ui_story_5043_50431402_X163_dialog_content = "약점을 찾아내면, 일격에 이길 수 있어요!",
  ui_story_5043_50431402_164_dialog_content = "그럼 조각상의 가면을 노려보자!",
  ui_story_5043_50431402_165_dialog_content = "알겠습니다. 지금 바로 공격하겠습니다!",
  ui_story_5043_50431402_166_dialog_content = "크아아──!",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>퍽! 퍽! 퍽!</color>",
  ui_story_5043_50431402_168_dialog_content = "으... 엄청... 아프네요...",
  ui_story_5043_50431402_169_dialog_content = "아무래도 가면을 벗기는 건 쉽지 않을 것 같아...",
  ui_story_5043_50431402_170_dialog_content = "하하하하, 당신들의 바보짓에 정말 웃음이 멈추질 않는군요.",
  ui_story_5043_50431402_171_dialog_content = "그 정도 공격으로 제 기사들을 쓰러트릴 수 있을 거라 생각했습니까?",
  ui_story_5043_50431402_172_dialog_content = "흥, 수많은 곡절을 넘어온 지금이야말로! 감정의 최고조라구요!",
  ui_story_5043_50431402_173_dialog_content = "이럴 땐 더는 기교가 중요하지 않아요. 필요한 건 오직...",
  ui_story_5043_50431402_174_dialog_content = "그래! 지금이야! 티나!",
  ui_story_5043_50431402_175_dialog_content = "네 진심을 보여주는 거야!",
  ui_story_5043_50431402_176_dialog_content = "맞아요! 전심전력으로 제 진심을 보이겠어요!",
  ui_story_5043_50431402_177_dialog_content = "제 타오르는 진심의 일격을 받으세요!",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>거룩한 빛이여</color>!</size>",
  ui_story_5043_50431402_179_dialog_content = "휴... 성공인가?",
  ui_story_5043_50431402_180_dialog_content = "가면 쓴 암귀를 소멸시킨 것 같아!",
  ui_story_5043_50431402_181_dialog_content = "안 돼... 그럴 리가 없어... 내 기사들이...",
  ui_story_5043_50431402_182_dialog_content = "계속 싸우세요! 기사들이여!",
  ui_story_5043_50431402_183_dialog_content = "아직 판결이 집행되지 않았습니다! 쓰러져선 안 된단 말입니다!",
  ui_story_5043_50431402_184_dialog_content = "이제 다 끝났어요.",
  ui_story_5043_50431402_185_dialog_content = "당신과 저들 사이에 감정 같은 건 없었어요. 그저 당신의 강요와 핍박만 있었죠.",
  ui_story_5043_50431402_186_dialog_content = "우리의 진심 앞에서 그런 나약한 연결고리는 산산조각나는 게 당연하다구요.",
  ui_story_5043_50431402_187_dialog_content = "대체 언제까지 영문도 모를 헛소리를 지껄일 겁니까!",
  ui_story_5043_50431402_188_dialog_content = "판결이 집행되지 않은 점이라면 당신이 걱정할 필요는 없습니다.",
  ui_story_5043_50431402_189_dialog_content = "이런 소동을 벌인 이상, 심판소는 반드시 본건의 재심을 실시할 겁니다.",
  ui_story_5043_50431402_190_dialog_content = "아마 이리돈 님께서 대심판관석에 앉으시겠죠.",
  ui_story_5043_50431402_191_dialog_content = "그분이라면 당신이 만족할 만한 결과를 보여주실 겁니다.",
  ui_story_5043_50431402_192_dialog_content = "...날 심판하겠다고? 아니, 안 돼... 이럴 순 없어!",
  ui_story_5043_50431402_193_dialog_content = "아무도 나를 심판하지 못해! 나는 무죄다!",
  ui_story_5043_50431402_194_dialog_content = "무죄 여부를 결정하는 건 당신이 아닙니다.",
  ui_story_5043_50431402_195_dialog_content = "당연히 내가 결정한다! 내가 바로 대심판관이다!",
  ui_story_5043_50431402_196_dialog_content = "그 신분도 당신이 결정할 수 있는 게 아닐 텐데요.",
  ui_story_5043_50431402_197_dialog_content = "썩었어! 이 도시의 법은 이미 썩었다고!",
  ui_story_5043_50431402_198_dialog_content = "비켜라! 아버님을 만나야겠어!",
  ui_story_5043_50431402_199_dialog_content = "살라르 가문이 이 사건에 정의를 세울 것이다!",
  ui_story_5043_50431402_200_dialog_content = "정말 비참하군, 슈와브. 일이 터지면 가문의 힘을 빌릴 수밖에 없는 거냐?",
  ui_story_5043_50431402_201_dialog_content = "이게 무슨 망신이래.",
  ui_story_5043_50431402_202_dialog_content = "비켜!",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>철썩!</color>",
  ui_story_5043_50431402_204_dialog_content = "으악!",
  ui_story_5043_50431402_205_dialog_content = "누, 누가 감히 날 때렸어?!",
  ui_story_5043_50431402_206_dialog_content = "얌전히 우리와 심판소로 돌아가 사건 해결에 힘쓴다면,\n아무도 당신을 때리거나 하지 않습니다.",
  ui_story_5043_50431402_207_dialog_content = "레인! 네 녀석이 감히!",
  ui_story_5043_50431402_208_dialog_content = "비천한 서민 출신 주제에! 지금 네가 무슨 짓을 한 건지 알기나 해?!",
  ui_story_5043_50431402_209_dialog_content = "이건 당신을 위해서입니다.",
  ui_story_5043_50431402_210_dialog_content = "만약 티나였다면 실수로 저 왼손을 썼을지도 모르니까요.",
  ui_story_5043_50431402_211_dialog_content = "맞아요.",
  ui_story_5043_50431402_212_dialog_content = "네...네놈들...",
  ui_story_5043_50431402_213_dialog_content = "이제 됐어, 지금은 아직 근무 시간이라고.\n연애 심판소의 심판관인 우리가 밖에서 빈둥대면 안 되지.",
  ui_story_5043_50431402_214_dialog_content = "자, 가자, 일하러 가야지.",
  ui_story_5043_50431402_215_dialog_content = "네, 그래요. 아직 일이 산더미처럼 쌓여 있잖아요.",
  ui_story_5043_50431402_216_dialog_content = "후아암── 소파~ 베개~ 지금 가요~",
  ui_story_5043_50431402_217_dialog_content = "어이! 밀지 마라!",
  ui_story_5043_50431402_218_dialog_content = "더러운 손들 치우란 말이다!",
  ui_story_5043_50431402_219_dialog_content = "우와... 슈와브를 잡아가 버렸어!",
  ui_story_5043_50431402_220_dialog_content = "이걸로 사건도 해결된 건가?",
  ui_story_5043_50431402_221_dialog_content = "그래, 이제 녀석을 기다리고 있는 건 엄중한 심판뿐이야.",
  ui_story_5043_50431402_222_dialog_content = "비록 범죄의 피해는 크지 않았지만, 그 행위는 매우 악질적이야.",
  ui_story_5043_50431402_223_dialog_content = "만약 녀석이 한 발 더 나아가 저 암귀들로 정국을 어지럽혔다면... 상상만 해도 끔찍해.",
  ui_story_5043_50431402_224_dialog_content = "슈와브가 그렇게까지 악당은 아니라서 다행이네. 그저 사랑이 싫었을 뿐이잖아, 하하.",
  ui_story_5043_50431402_225_dialog_content = "그러게, 어쩌면 그런 극단적인 생각 때문에 다른 사람들은\n상상할 수도 없는 일을 벌일 수 있었던 거겠지.",
  ui_story_5043_50431402_226_dialog_content = "게다가 잠깐이었지만, 적어도 방금 그 재판에서 녀석은\n자신이 생각하는 이상적인 심판소를 만들어냈어.",
  ui_story_5043_50431402_227_dialog_content = "아무튼 이번 일도 이걸로 끝이네!",
  ui_story_5043_50431402_228_dialog_content = "처음엔 작은 사건이라고 생각했는데, 이런 소동이 일어날 줄은 정말 몰랐어...",
  ui_story_5043_50431402_229_dialog_content = "그래, 이제 끝났어.",
  ui_story_5043_50431402_230_dialog_content = "이제 결말만 남았으니까, 마지막까지 감상해 보자.",
  ui_story_5043_50431402_231_dialog_content = "응, 그래야지. 가자!",
  ui_story_5043_50431402_232_dialog_content = "최종 판결을 들으러...",
  ui_story_5043_50431402_233_dialog_content = "...어라? 수녀님?",
  ui_story_5043_50431402_234_dialog_content = "...다 끝났어요.",
  ui_story_5043_50431402_235_dialog_content = "가, 갑자기 왜 우세요?",
  ui_story_5043_50431402_236_dialog_content = "시위대도 모두 흩어졌고, 열기구도 없어져 버렸어요.",
  ui_story_5043_50431402_237_dialog_content = "제 레드 클로버도... 모두 사라졌어요...",
  ui_story_5043_50431402_238_dialog_content = "휴... 슈와브가 일으킨 소동만 아니었어도...",
  ui_story_5043_50431402_239_dialog_content = "끝났어요. 모든 게 끝나버렸네요.",
  ui_story_5043_50431402_240_dialog_content = "백야성의 자유연애도... 이걸로 끝이에요...",
  ui_story_5043_50431501_1_dialog_content = "조사 결과가 나왔어. 실제 상황은 레인의 추리와 일치했어.",
  ui_story_5043_50431501_2_dialog_content = "슈와브가 암귀를 조종해서 「목 없는 조각상 연쇄 사건」을 벌인 게 맞았어.",
  ui_story_5043_50431501_3_dialog_content = "다행히 조각상을 파괴한 것 외에는 오로리안을 해치거나 한 일은 없었어.",
  ui_story_5043_50431501_4_dialog_content = "휴, 그래도 최소한의 정의감은 있었다는 게 다행이라고 해야 하나...",
  ui_story_5043_50431501_5_dialog_content = "그나저나 심판관은 역시 대단하네.\n아무 단서도 없는 상황에서 정확한 결론을 내렸잖아.",
  ui_story_5043_50431501_6_dialog_content = "맞아, 이번 사건을 계기로 심판소도 그 세 사람을 더 주목하게 될 거야.",
  ui_story_5043_50431501_7_dialog_content = "근데 여전히 이해가 안 되는 게 하나 있어.",
  ui_story_5043_50431501_8_dialog_content = "슈와브는 대체 어떻게 암귀를 조종한 거야?",
  ui_story_5043_50431501_9_dialog_content = "싸울 때 특별한 장치 같은 것도 없어 보였는데...",
  ui_story_5043_50431501_10_dialog_content = "아, 마침 그 문제도 조사 결과가 나왔어.",
  ui_story_5043_50431501_11_dialog_content = "심판소는 살라르 장원에서 슈와브가 암귀를 가두던 지하실을 찾아냈어.",
  ui_story_5043_50431501_12_dialog_content = "하지만 조사원들은 암귀 조종에 쓸 만한 장치는 전혀 찾아내지 못했어.",
  ui_story_5043_50431501_13_dialog_content = "슈와브를 심문하고 그의 집에서 발견한 증거물을 토대로,\n심판소는 기묘한 결론을 도출했어.",
  ui_story_5043_50431501_14_dialog_content = "슈와브는 맹수를 「길들이는」 것과 유사한 방식으로 그 암귀들을 복종시켰던 거야.",
  ui_story_5043_50431501_15_dialog_content = "길들여?!",
  ui_story_5043_50431501_16_dialog_content = "암귀가 길들일 수 있는 거였어?",
  ui_story_5043_50431501_17_dialog_content = "생각해 봐. 완전히 불가능한 이야기는 아니야.",
  ui_story_5043_50431501_18_dialog_content = "암귀는 대대로 오로리안의 적이었어.\n그러니 우린 본능적으로 녀석들을 대립의 상대로 생각했지.",
  ui_story_5043_50431501_19_dialog_content = "하지만 종족 간의 원한을 제쳐두면, 암귀는 그저 지능이 낮은 생물에 불과해.",
  ui_story_5043_50431501_20_dialog_content = "녀석들도 다른 동물과 마찬가지로 자신의 습성과 욕망을 가지고 있어.",
  ui_story_5043_50431501_21_dialog_content = "동물을 길들일 때도 그렇잖아?\n잘 관찰해서 특징을 파악하고, 말을 듣게 만들면 되는 것처럼 말이야.",
  ui_story_5043_50431501_22_dialog_content = "슈와브는 선조들이 늑대에게 했던 일을 암귀들에게 똑같이 했을 뿐이야.",
  ui_story_5043_50431501_23_dialog_content = "그런 거였구나...",
  ui_story_5043_50431501_24_dialog_content = "하긴, 맞는 말이네. 그래도 역시 신기하지만.",
  ui_story_5043_50431501_25_dialog_content = "사실 다른 측면에서도 그런 실마리는 있었어.",
  ui_story_5043_50431501_26_dialog_content = "슈와브는 오로리안을 경멸했지만, 작은 동물들에겐 친화력이 무척 높았거든.",
  ui_story_5043_50431501_27_dialog_content = "그래서 불가사의할 정도의 인내심을 가지고 그런 일을 해올 수 있었고,\n그 덕분에 우린 생각도 못 한 결과를 만들 수 있었던 거야.",
  ui_story_5043_50431501_28_dialog_content = "그렇게 보면 오로리안이 아닌 시선에서 봤을 땐,\n슈와브도 그렇게 나쁜 녀석은 아니었겠네.",
  ui_story_5043_50431501_29_dialog_content = "아니, 잠깐... 나도 오로리안이 아니잖아...",
  ui_story_5043_50431501_30_dialog_content = "자, 수다는 여기까지 하자.",
  ui_story_5043_50431501_31_dialog_content = "슈와브의 재판이 곧 시작될 거야.",
  ui_story_5043_50431501_32_dialog_content = "피고인 슈와브는 배후에서 암귀를 조종해 조각상을 파괴한 혐의로 기소되었습니다.",
  ui_story_5043_50431501_33_dialog_content = "본 심판소의 엄밀한 조사 결과, 그 혐의가 확실하게 입증되었습니다.",
  ui_story_5043_50431501_34_dialog_content = "피고인, 죄를 인정하십니까?",
  ui_story_5043_50431501_35_dialog_content = "......",
  ui_story_5043_50431501_36_dialog_content = "(전에는 그렇게나 오만하던 녀석이 지금은 엄청 풀이 죽어 있네.)",
  ui_story_5043_50431501_37_dialog_content = "본 사건의 피고인이 저지른 행위는 그 죄질이 매우 불량합니다.\n그러나 그 행위가 심각한 실질적 피해를 초래하지는 않았습니다.",
  ui_story_5043_50431501_38_dialog_content = "따라서 피고인이 아직 젊고, 개전의 여지가 충분한 점을 참작하여,\n본 심판소는 피고인에게 금고형을 선고하지 않겠습니다.",
  ui_story_5043_50431501_39_dialog_content = "어라? 감옥에 안 가도 되는 겁니까?",
  ui_story_5043_50431501_40_dialog_content = "따지고 보면 슈와브는 그저 극단적인 사고방식의 괴짜일 뿐이야.",
  ui_story_5043_50431501_41_dialog_content = "중대한 피해를 일으키지 않은 이상, 무거운 실형을 선고할 필요는 없어.",
  ui_story_5043_50431501_42_dialog_content = "금고형을 부과하지 않는다 해서 피고인이 법의 심판을 피할 수 있는 것은 아닙니다.",
  ui_story_5043_50431501_43_dialog_content = "살라르 가문과 피고인에게 본건의 피해 복구에 필요한\n일체의 비용을 부담할 것을 명령합니다.",
  ui_story_5043_50431501_44_dialog_content = "심판소 근로의 보수로 지급된 임금 또한 전액 몰수합니다.",
  ui_story_5043_50431501_45_dialog_content = "물론입니다. 처벌을 수용하겠습니다.",
  ui_story_5043_50431501_46_dialog_content = "전혀 신경 안 쓰는 모양인데...",
  ui_story_5043_50431501_47_dialog_content = "슈와브에겐 돈이 가장 하찮은 물건일 테니까.",
  ui_story_5043_50431501_48_dialog_content = "그렇게 본다면... 이 처벌, 왠지 너무 가벼운 건 아닐까?",
  ui_story_5043_50431501_49_dialog_content = "물론 처벌은 그것으로 끝이 아닙니다.",
  ui_story_5043_50431501_50_dialog_content = "본건을 상세히 검토한 결과, 우리는 피고인의 극단적인 행위가\n귀족 교육체계의 실책에 기인한 것임을 알 수 있었습니다.",
  ui_story_5043_50431501_51_dialog_content = "그 실책을 보완하기 위해, 본 심판소는 피고인에게 전문기관으로 돌아가\n교육을 재이수할 것을 명령합니다.",
  ui_story_5043_50431501_52_dialog_content = "뭐라고요?! 여명 아카데미로 다시 돌아가라는 겁니까?",
  ui_story_5043_50431501_53_dialog_content = "암귀와 결탁한 것은 매우 큰 죄입니다. 반드시 엄중한 처벌이 필요합니다.",
  ui_story_5043_50431501_X53_dialog_content = "따라서 피고인에게 빛의 신의 가르침을 다시 받도록 해야 한다는 것이\n본 심판소가 내린 판단입니다.",
  ui_story_5043_50431501_54_dialog_content = "이를 위해 피고인을 <color=#FFB400>수녀 교육 전담 신전</color>에 배정합니다.",
  ui_story_5043_50431501_55_dialog_content = "수, 수녀라고요?!",
  ui_story_5043_50431501_56_dialog_content = "대심판관님, 그, 그런 판결이 꼭 필요합니까?!",
  ui_story_5043_50431501_57_dialog_content = "부디 피고인이 잘못을 바로잡고 새롭게 태어나길 바랍니다.\n그럼 앞으로 피고인을 가르칠 선생님과 인사를 나누세요.",
  ui_story_5043_50431501_58_dialog_content = "안녕하세요, 슈와브 경. 또 만났네요.",
  ui_story_5043_50431501_59_dialog_content = "다, 당신이 왜 여기 있습니까?! 설마 당신이 꺼낸 제안이었습니까?!",
  ui_story_5043_50431501_60_dialog_content = "신전에서는 정규 신학 교육 외에도, 바느질이나 요리와 같은 즐거운 수업도 있답니다.",
  ui_story_5043_50431501_61_dialog_content = "앞으로 몇 년 동안 잘 부탁할게요.",
  ui_story_5043_50431501_62_dialog_content = "안 돼요! 안 됩니다! 여자밖에 없는 그런 곳엔 못 간다고요!",
  ui_story_5043_50431501_63_dialog_content = "아무래도 피고인은 가치관도 다시 형성할 필요가 있을 것 같네요.",
  ui_story_5043_50431501_64_dialog_content = "피고인을 데려가서 입학 준비를 시키세요.",
  ui_story_5043_50431501_65_dialog_content = "다음으로, 본건에서는 피고인 외에도 처벌이 필요한 사건 연루자들이 있습니다.",
  ui_story_5043_50431501_66_dialog_content = "레인 심판관.",
  ui_story_5043_50431501_67_dialog_content = "네!",
  ui_story_5043_50431501_68_dialog_content = "살라르 장원에 무단으로 침입한 것이 사실입니까?",
  ui_story_5043_50431501_69_dialog_content = "네.",
  ui_story_5043_50431501_70_dialog_content = "(역시 자수했구나...)",
  ui_story_5043_50431501_71_dialog_content = "알겠습니다. 그렇다면 심판관 수칙 제127조 규정에 따라...",
  ui_story_5043_50431501_72_dialog_content = "당신의 이번 달 실적은 무효이며, 월급도 백야성 최저임금을 기준으로 지급합니다.",
  ui_story_5043_50431501_73_dialog_content = "아, 알겠습니다...",
  ui_story_5043_50431501_74_dialog_content = "(레인 씨, 안색이 엄청 안 좋아... 엄청 충격 받은 모양이네!)",
  ui_story_5043_50431501_75_dialog_content = "에이, 정말... 저도 있습니다!",
  ui_story_5043_50431501_76_dialog_content = "저도 살라르 장원에 침입했습니다. 처벌은 저도 함께 받겠습니다.",
  ui_story_5043_50431501_77_dialog_content = "호오? 마티외 심판관도 그랬나요?",
  ui_story_5043_50431501_78_dialog_content = "저, 저도요! 저도 갔어요...",
  ui_story_5043_50431501_79_dialog_content = "정직하게 스스로 죄를 인정하다니 기쁘군요.\n그렇다면 마티외 심판관도 이번 달 월급을 전액 삭감하고...",
  ui_story_5043_50431501_80_dialog_content = "3인은 나중에 가서 심판소 정문을 청소하세요.",
  ui_story_5043_50431501_81_dialog_content = "온통 시든 꽃이 떨어져 있어서 미관에 좋지 않네요.",
  ui_story_5043_50431501_82_dialog_content = "하아아? 어, 어째서 그런 처벌을...",
  ui_story_5043_50431501_83_dialog_content = "그럼 다른 벌이 좋으신가요?",
  ui_story_5043_50431501_84_dialog_content = "아, 아니에요! 대심판관님! 감사합니다! 지금 바로 갈게요!",
  ui_story_5043_50431501_85_dialog_content = "그 외에 한 건의 범죄 행위가 또 있습니다.",
  ui_story_5043_50431501_86_dialog_content = "증인 복슬이는 증인석으로 나오세요.",
  ui_story_5043_50431501_87_dialog_content = "네, 네, 대심판관님!",
  ui_story_5043_50431501_88_dialog_content = "아... 복슬 씨...",
  ui_story_5043_50431501_89_dialog_content = "(우와, 복슬이 녀석 옷 좀 봐!)",
  ui_story_5043_50431501_90_dialog_content = "(정말 잘 만든 옷이잖아. 완전 백야성 사람 같네!)",
  ui_story_5043_50431501_91_dialog_content = "증인은 본 사건의 피해자임에도 불구하고 오로리안에게 도움을 주었습니다.\n이는 칭찬할 만한 행위입니다.",
  ui_story_5043_50431501_92_dialog_content = "그러나 심판소에서의 위증이 범죄라는 사실은 변하지 않습니다.",
  ui_story_5043_50431501_93_dialog_content = "이 건에 있어서 증인을 교사한 레인 심판관에게는 위증교사죄가 성립합니다.",
  ui_story_5043_50431501_94_dialog_content = "네... 알고 있어요...",
  ui_story_5043_50431501_95_dialog_content = "그렇다면 두 사람에게 다음 처벌을 선고합니다.",
  ui_story_5043_50431501_96_dialog_content = "가서 슈와브에게 사과하세요.",
  ui_story_5043_50431501_97_dialog_content = "으우...... 네?",
  ui_story_5043_50431501_98_dialog_content = "사, 사과만 하면 되나요?",
  ui_story_5043_50431501_99_dialog_content = "슈와브는 기망의 피해자로서 무척 화가 났을 거예요.\n그러니 진심으로 사과하는 게 좋아요.",
  ui_story_5043_50431501_100_dialog_content = "자, 이것으로 본 사건 관계자에 대한 모든 판결과 처벌이 끝났습니다.",
  ui_story_5043_50431501_101_dialog_content = "「목 없는 조각상 연쇄 사건」의 재판을 마치고, 오늘은 휴정합니다!",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>며칠 뒤</color>",
  ui_story_5043_50431501_104_dialog_content = "크흠, 이것으로 몇 달 전 용주에 다녀온 소감 발표를 마치겠습니다.",
  ui_story_5043_50431501_105_dialog_content = "좋다, 사의를 표하겠네, PlayerName.",
  ui_story_5043_50431501_106_dialog_content = "이 세계의 정세 변화는 예측하기 어려우나, 백야성의 입장은 변하지 않는다.",
  ui_story_5043_50431501_107_dialog_content = "올해에도 백야성과 헤븐즈 밸리가 우호적인 왕래를 이어가기를 바라는 바다.",
  ui_story_5043_50431501_108_dialog_content = "부디 그대의 생각도 나와 같았으면 좋겠군.",
  ui_story_5043_50431501_109_dialog_content = "벼, 별말씀을요! 저도 물론 모두와 사이좋게 지내고 싶다고 생각하고 있어요!",
  ui_story_5043_50431501_110_dialog_content = "그렇다면 좋다.",
  ui_story_5043_50431501_111_dialog_content = "(휴... 어떻게든 끝났네!)",
  ui_story_5043_50431501_112_dialog_content = "이번 발표, 꽤 근사했어, PlayerName.",
  ui_story_5043_50431501_113_dialog_content = "그래? 하하... 사실 속으론 좀 긴장했는데.",
  ui_story_5043_50431501_114_dialog_content = "회의의 주요 안건은 이것으로 끝이군. 다른 질문이 있다면 하게.",
  ui_story_5043_50431501_115_dialog_content = "심판소의 보고는 모두 마쳤습니다.",
  ui_story_5043_50431501_116_dialog_content = "아우토 공작은 어떠한가.",
  ui_story_5043_50431501_117_dialog_content = "허허, 오래 앉아있었더니 피곤하군.",
  ui_story_5043_50431501_118_dialog_content = "그렇다면 이만 해산하기로 하지.",
  ui_story_5043_50431501_119_dialog_content = "(안 돼. 모처럼 심판소와 원로원이 출석한 이상, 이 자리를 빌어 설명해야만 해.)",
  ui_story_5043_50431501_120_dialog_content = "(최근 백야성에 나타난 암귀, 열광한 백성들 외에도 기회를 틈타 혼란을 일으킨 자들이 있어.)",
  ui_story_5043_50431501_121_dialog_content = "(하이가든 호위대를 대표해서 원로원의 책임을 물어야겠어!)",
  ui_story_5043_50431501_122_dialog_content = "성주님, 아우토 공작, 잠시만요.",
  ui_story_5043_50431501_123_dialog_content = "솔라드 성주, 최근 하이가든이 여러 돌발 사건을 매우 잘 처리했더군.",
  ui_story_5043_50431501_124_dialog_content = "몸을 낮추고 백성들을 가까이하는 그 마음가짐에 감탄했네.",
  ui_story_5043_50431501_125_dialog_content = "하하, 아우토 공작, 과찬이로군. 모두 원로원의 지지가 있었던 덕분이 아닌가.",
  ui_story_5043_50431501_126_dialog_content = "원로원이 군사를 보내 암귀를 몰아내 주지 않았다면,\n하이가든 호위대도 그만큼의 성과를 내지 못했겠지.",
  ui_story_5043_50431501_127_dialog_content = "무슨 일이냐, 카렌.",
  ui_story_5043_50431501_128_dialog_content = "......",
  ui_story_5043_50431501_129_dialog_content = "부녀간의 귀중한 시간을 방해할 순 없으니, 먼저 가보도록 하지.",
  ui_story_5043_50431501_130_dialog_content = "전하, 원로원의 호위병들이 관월제 살롱에서 무슨 짓을 했는지 알고 계실 텐데요.",
  ui_story_5043_50431501_131_dialog_content = "물론 너보다도 잘 알고 있지.",
  ui_story_5043_50431501_132_dialog_content = "지난 1년 동안, 전보다 많이 진중해졌더구나.\n물론 그 용감함도 여전히 간직하고 있으면서 말이야.",
  ui_story_5043_50431501_133_dialog_content = "허나 정치의 문제는 용기만으로 해결할 수 있는 것이 아니다.",
  ui_story_5043_50431501_134_dialog_content = "지금 하는 일을 마치고 나면, 하이가든의 일원들에게 휴가를 주도록 하지.",
  ui_story_5043_50431501_135_dialog_content = "감사합니다. 하지만 필요 없습니다.",
  ui_story_5043_50431501_136_dialog_content = "PlayerName, 가자.",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>팡──! 팡──! 팡──!</color>",
  ui_story_5043_50431501_138_dialog_content = "PlayerName 씨, 보고 업무의 성공을 축하드려요!",
  ui_story_5043_50431501_139_dialog_content = "방금 이리돈 대심판관님이 회의실에서 나왔을 때 이미 알았어요!",
  ui_story_5043_50431501_140_dialog_content = "이건 저번에 바이런 씨를 위해 준비했던 폭죽입니다.",
  ui_story_5043_50431501_141_dialog_content = "이렇게 사용했으니 낭비하지 않은 셈이겠죠.",
  ui_story_5043_50431501_142_dialog_content = "어떠냐, 깜짝 놀랐겠지?",
  ui_story_5043_50431501_143_dialog_content = "공주 전하도 그렇게 정색만 하지 말고 좀 기뻐해 보세요!",
  ui_story_5043_50431501_144_dialog_content = "PlayerName, 순조롭게 일이 끝난 걸 축하해.",
  ui_story_5043_50431501_145_dialog_content = "우와... 다들 고마워!",
  ui_story_5043_50431501_146_dialog_content = "당신들...",
  ui_story_5043_50431501_147_dialog_content = "뭐, 됐어. 역시 당신들은 정말 어쩔 수가 없네.",
  ui_story_5043_50431501_148_dialog_content = "여러분, 흥을 깨고 싶진 않지만, 심판소 일은 아직 끝나지 않았어요.",
  ui_story_5043_50431501_149_dialog_content = "카렌 전하도 함께 가시죠.",
  ui_story_5043_50431501_150_dialog_content = "이 일은 하이가든의 협력이 필요하거든요.",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>하이가든, 심판소</color>",
  ui_story_5043_50431501_152_dialog_content = "그렇구나.",
  ui_story_5043_50431501_153_dialog_content = "연애 지부는 해산됐지만, 대량의 사건이 처리되지 못한 채로 남았을 테니까.",
  ui_story_5043_50431501_154_dialog_content = "심판소의 업무 처리는 정말 세심하네.",
  ui_story_5043_50431501_155_dialog_content = "와, 이렇게 많은 사건기록을 언제 다 읽지...",
  ui_story_5043_50431501_156_dialog_content = "그것들은 그럼──",
  ui_story_5043_50431501_157_dialog_content = "알겠습니다...",
  ui_story_5043_50431501_158_dialog_content = "카렌 전하, 여기 서류에 기록돼 있는 사건은 언뜻 보기엔\n그저 남녀간의 감정싸움에 지나지 않겠죠.",
  ui_story_5043_50431501_159_dialog_content = "하지만 이 기록들은 백야성 사회 기반의 건설이나 안정 등에 존재하는\n숨은 문제들을 반영하고 있기도 해요.",
  ui_story_5043_50431501_160_dialog_content = "또한 이 서류들을 통해 전 미드가든과 다운타운 주민들의 사고방식을\n더 깊이 이해할 수 있었어요.",
  ui_story_5043_50431501_161_dialog_content = "그들의 사랑에 대한 사고방식, 신앙에 대한 해석 등...\n모두 제가 새로운 생각을 하도록 만들었죠.",
  ui_story_5043_50431501_162_dialog_content = "그러니 이 사건 기록들은 다음 법 개정에도 큰 도움이 될 거라고 생각해요.",
  ui_story_5043_50431501_163_dialog_content = "그때가 되면 성주님, 그리고 특히 카렌 전하께서 부디 심판소의\n업무와 판단을 지지해 주셨으면 해요.",
  ui_story_5043_50431501_164_dialog_content = "조금 더 넓게 본다면, 이는 백야성의 미래를 위해서도 중요한 일이에요.",
  ui_story_5043_50431501_165_dialog_content = "알겠어, 지지를 약속할게.",
  ui_story_5043_50431501_166_dialog_content = "같은 생각을 하는 게 이리돈 씨 혼자만은 아닐 거야.",
  ui_story_5043_50431501_167_dialog_content = "카렌, 기분 좋아 보이네?",
  ui_story_5043_50431501_168_dialog_content = "그렇게 티가 나?",
  ui_story_5043_50431501_169_dialog_content = "이렇게 보니 이 거리도 어느새 원래 모습으로 돌아가 버렸군요.",
  ui_story_5043_50431501_170_dialog_content = "떠들썩한 살롱도, 시위행진도 없고, 하늘에 뜬 달도 없습니다.",
  ui_story_5043_50431501_171_dialog_content = "별것도 아닌데 놀라긴, 우리 귀족들은 원래 그런 거라고.",
  ui_story_5043_50431501_172_dialog_content = "백야성의 풍조는 언제나 변덕스러웠지. 게다가 새로운 풍조를 놓칠 순 없잖아?",
  ui_story_5043_50431501_173_dialog_content = "봐라.",
  ui_story_5043_50431501_174_dialog_content = "어라? 저건 제 장갑이잖아요?",
  ui_story_5043_50431501_175_dialog_content = "이미 최신 유행 아이템이 돼버렸다고. 지금 사교계의 귀족들이라면 전부 끼고 있지.",
  ui_story_5043_50431501_176_dialog_content = "조금 무겁긴 하지만, 난 이미 일곱 쌍이나 샀다니까~",
  ui_story_5043_50431501_177_dialog_content = "참 할 일도 없네.",
  ui_story_5043_50431501_178_dialog_content = "정말 전형적인 귀족 도련님 그 자체네요...",
  ui_story_5043_50431501_179_dialog_content = "티나 양, 최신 유행의 선구자가 된 소감은?",
  ui_story_5043_50431501_180_dialog_content = "참, 복슬이랑은 어떻게 돼가고 있지? 녀석의 사육자가 되는 데 성공했나?",
  ui_story_5043_50431501_181_dialog_content = "비록 백야성에선 절대 금지된 일이지만... 그래도 정말 재미있는 일이잖아!",
  ui_story_5043_50431501_182_dialog_content = "저기... 사실 저... 오늘 복슬 씨랑 여기서 만나기로 약속했어요.",
  ui_story_5043_50431501_183_dialog_content = "하지만... 오늘 만나는 건... <color=#FFB400>이별</color>을 이야기하기 위해서예요.",
  ui_story_5043_50431501_184_dialog_content = "네?!",
  ui_story_5043_50431501_185_dialog_content = "잠깐만, 이렇게 갑자기? 티나 양, 그 녀석에 대한 열정이 벌써 사라진 거야?",
  ui_story_5043_50431501_186_dialog_content = "아니요, 오히려 그 반대예요.\n전 귀엽고, 착하고, 많은 곳을 여행하고 있는 복슬 씨가 정말 좋아요.",
  ui_story_5043_50431501_187_dialog_content = "암귀는 무섭고 가증스러운 존재지만, 복슬 씨는 다른 암귀와는 달라요.",
  ui_story_5043_50431501_188_dialog_content = "하지만 모든 사람이 그걸 알아주는 것은 아니에요.",
  ui_story_5043_50431501_189_dialog_content = "만약 저와 함께 백야성에 머문다면, 복슬 씨의 삶은 불편해질 거예요.",
  ui_story_5043_50431501_190_dialog_content = "백야성에서 보낸 지난 한 달 동안, 복슬 씨에겐 즐거운 일보다 무서운 일이 더 많았겠죠.",
  ui_story_5043_50431501_191_dialog_content = "...어라?",
  ui_story_5043_50431501_192_dialog_content = "우으...",
  ui_story_5043_50431501_193_dialog_content = "복슬아, 숨어 있지 말고 이리 와!",
  ui_story_5043_50431501_194_dialog_content = "여, 여러분, 안녕하세요...",
  ui_story_5043_50431501_X194_dialog_content = "새 옷으로 갈아입었구나!",
  ui_story_5043_50431501_X195_dialog_content = "정말 잘 만든 옷이잖아. 완전 백야성 사람 같네!",
  ui_story_5043_50431501_X196_dialog_content = "네... 오늘은 중요한 날이라 단정하게 입고 왔어요...",
  ui_story_5043_50431501_195_dialog_content = "사실... 저도... 여러분께 작별 인사를 하러 온 거예요...",
  ui_story_5043_50431501_196_dialog_content = "역시 여행을 계속할 생각인 거구나.",
  ui_story_5043_50431501_197_dialog_content = "네... 하, 하지만... 여러분이 생각하는 것과는... 조금 달라요...",
  ui_story_5043_50431501_198_dialog_content = "백야성에 있는 동안... 확실히 많은 무서운 일들이 있었고... 전 항상 공포에 빠져 있었어요...",
  ui_story_5043_50431501_199_dialog_content = "하지만 이 시간 동안의 추억 덕분에 전 정말 행복했어요...",
  ui_story_5043_50431501_200_dialog_content = "여러분을... 만날 수 있었으니까요...",
  ui_story_5043_50431501_201_dialog_content = "특히... 티나를 알게 돼서 행복했어요...",
  ui_story_5043_50431501_202_dialog_content = "고마워요, 복슬 씨.",
  ui_story_5043_50431501_203_dialog_content = "저, 전 처음으로 오로리안에게 아무 목적도 없는 선의를 받았어요...",
  ui_story_5043_50431501_204_dialog_content = "이건 제게 무척 소중한 경험이에요... 그래서 전 행복했어요...",
  ui_story_5043_50431501_205_dialog_content = "(아무 목적도 없는 선의...)",
  ui_story_5043_50431501_206_dialog_content = "(맞아, 그건 정말 얻기 힘든 소중한 마음이잖아.)",
  ui_story_5043_50431501_207_dialog_content = "...가세요, 복슬 씨. 당신의 여행을 계속하는 거예요.",
  ui_story_5043_50431501_208_dialog_content = "다음에 또 기회가 있다면, 아마 다시 만날 수 있을 거예요.",
